(window.GIM_TS=window.GIM_TS||{})["Menachot.2"]={"from":48,"a":[["ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שלא כרב שילא, ממה ששנינו בברייתא הראשונה: \u0003דם שנטמא וזרקו, בשוגג\u0004 — \u0003הורצה, במזיד\u0004 — \u0003לא הורצה,\u0004 ושלא כדברי רב שילא, שאמר שאם זרקו במזיד הורצה! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך יש להבין את הברייתא לפי רב שילא: \u0003דם שנטמא וזרקו בין בשוגג בין במזיד,\u0004 אם \u0003נטמא בשוגג\u0004 — \u0003הורצה,\u0004 אם נטמא \u0003במזיד\u0004 — \u0003לא הורצה.\u0004","אם לאחר שקמץ מן המנחה \u0003נטמאו שיריה\u0004 המיועדים לכהנים, או \u0003נשרפו שיריה,\u0004 או \u0003אבדו שיריה\u0004 — \u0003כמדת\u0004 (לפי שיטת) \u0003ר' אליעזר\u0004 הרי היא \u0003כשירה\u0004 ויקטיר את הקומץ, \u0003וכמדת ר' יהושע פסולה,\u0004 ואינו מקטיר את הקומץ, שהקומץ בא להתיר את השיריים.","על מה שאמר ר' יהושע, שמנחה שנטמאו שייריה פסולה, \u0003אמר רב: והוא שנטמאו כל שיריה, אבל\u0004 אם נטמאו רק \u0003מקצת שיריה\u0004 — \u0003לא,\u0004 הריהי כשרה, ויקטיר את הקומץ.","ומקדימים: \u0003קא סלקא דעתך\u0004 \u0005[עולה על דעתנו\u0006 לומר\u0005]\u0006 שרק אם \u0003נטמא\u0004 חלק מן השיריים — \u0003אין\u0004 \u0005[כן]\u0006 המנחה כשרה, אבל אם היה חלק \u0003אבוד ושרוף\u0004 — \u0003לא.\u0004 ומתקשים בדבר: \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 רב? \u0003אי קסבר\u0004 \u0005[אם הוא סבור]:\u0006 \u0003שיורא מילתא היא\u0004 \u0005[שיור דבר\u0006 נחשב \u0005הוא],\u0006 ולמרות שחלק אינו ראוי לאכילה מקטירים על הנותר את הקומץ — \u0003אפילו אבוד ושרוף נמי\u0004 \u0005[גם כן]\u0006 יקטיר על מה שנותר! \u0003אי קסבר\u0004 \u0005[אם הוא סבור]:\u0006 \u0003שיורא לאו מילתא היא\u0004 \u0005[שיור אינו דבר נחשב],\u0006 \u0003ו\u0004במקרה ש\u0003נטמא\u0004 חלק מן השיריים \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא מכשיר — משום ש\u0003מרצה\u0004 ה\u0003ציץ\u0004 על הטומאה; \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אפילו נטמאו \u0003כל שיריה נמי\u0004 \u0005[גם כן]\u0006 יכשיר מטעם זה!","ומשיבים: \u0003לעולם\u0004 תפרש \u0003קסבר\u0004 \u0005[\u0006ש\u0005הוא\u0006 \u0003סבור]:\u0004 \u0003שיורא מילתא היא\u0004 \u0005[שיור דבר\u0006 נחשב \u0005הוא],\u0006 \u0003ו\u0004מה שאמר \u0003נטמא\u0004 מקצת השיריים כשר, כוונתו — \u0003והוא הדין לאבוד ושרוף, והאי דקאמר\u0004 \u0005[וזה שהוא אומר]\u0006 רק \u0003נטמא\u0004 — \u0003רישייהו נקט\u0004 \u0005[את תחילתם תפס],\u0006 את המקרה הראשון שהזכירה המשנה (\"נטמאו שיריה\"). ומניין שר' יהושע מכשיר גם במקרה שאבד או נשרף חלק מן השיריים?","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע אומר: כל הזבחים שבתורה שנשתייר מהן כזית בשר\u0004 להתירו באכילה, \u0003או כזית חלב\u0004 להתירו בהקרבה — \u0003זורק את הדם,\u0004 שדין הדם ובשר הזבח כדין הקומץ ושיריי המנחה.","אגב כך מביאים את המשכה של הברייתא: אם נשאר \u0003כחצי זית בשר וכחצי זית חלב\u0004 — \u0003אינו זורק את הדם,\u0004 שהרי החלב עולה למזבח, ואילו הבשר נאכל, ואינם מצטרפים. \u0003ובעולה אפילו\u0004 נשתייר \u0003כחצי זית בשר וכחצי זית חלב\u0004 — \u0003זורק את הדם, מפני שכולה\u0004 עולה \u0003כליל\u0004 למזבח, ואין הבדל בענין זה בין חלב לבשר. \u0003ובמנחה אפילו כולה קיימת\u0004 — \u0003לא יזרוק.\u0004","ותוהים: \u0003מנחה מאי עבידתה\u0004 \u0005[מה מעשיה],\u0006 כלומר, מה עניינה של מנחה כאן? הרי מדובר בזריקה של דם הזבח! \u0003אמר רב פפא:\u0004 הכוונה היא \u0003ל\u0004\u0003מנחת נסכים\u0004 שצריך להביא עם הזבח; \u0003סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר: \u0003הואיל ובהדי זבח קא אתיא\u0004 \u0005[וביחד עם הזבח היא באה]\u0006 — \u0003כגופיה דזיבחא דמיא\u0004 \u0005[כגופו של הזבח היא נחשבת],\u0006 ואם נשארה מנחת הנסכים ייחשב הדבר כאילו נשאר משהו מן הזבח, ויזרוק את הדם למרות שלא נשאר דבר מן הבשר או מן החלב, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא יזרוק את הדם.","ושואלים: לגופו \u0005של דבר,\u0006 \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאם נשאר רק כזית מן החלב זורק עליו את הדם? \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל, ומטו בה\u0004 \u0005[ו\u0006יש שהיו \u0005מביאים\u0006 \u0005אותה]\u0006 \u0003משום ר' יהושע בן חנניא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"וזרק הכהן את הדם... \u0003והקטיר החלב לריח ניחח לה' \"\u0004(ויקרא יז, ו), ולא נזכר שם בשר, ללמד שאפילו אם נשאר רק \u0003חלב\u0004 זורק את הדם, \u0003ואף על פי שאין בשר.\u0004","ושואלים: \u0003ואשכחן\u0004 \u0005[ומצאנו]\u0006 מקור למקרה שנשתייר רק \u0003חלב,\u0004 אם נשתיירו רק \u0003יותרת\u0004 הכבד \u0003ושתי כליות\u0004 להקריבם \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שיזרוק? ומוסיפים: וצריך אתה לומר כן, \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005הוא שונה]\u0006 בברייתא: \u0003ובמנחה,\u0004 כלומר, אם נשתיירה מנחת נסכים הבאה עם הזבח — \u0003אפילו כולה קיימת לא יזרוק\u0004 את הדם, ויש לדייק מכאן: דווקא אם נשתיירה \u0003מנחה הוא\u0004 ש\u0003לא יזרוק,\u0004 מפני שאינה חלק מגוף הקרבן, \u0003הא\u0004 \u0005[הרי]\u0006 אם נשארו \u0003יותרת ושתי כליות\u0004 שהם מגוף הבהמה — \u0003יזרוק.\u0004","ואם כן \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: \u0003ר' יוחנן דידיה\u0004 \u0005[משל עצמו]\u0006 \u0003אמר,\u0004 ולא בשם חכמים אחרים (כדין האמור קודם): נאמר שם \u0003\"לריח ניחח\",\u0004 ללמד ש\u0003כל שאתה מעלה לריח ניחוח,\u0004 ובכלל זה היותרת ושתי הכליות, זורקים עליו את הדם.","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"חלב\"\u0004 במפורש, \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"לריח ניחח\", דאי כתב\u0004 \u0005[שאם היה כותב]\u0006 רק \u0003\"חלב\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כך: \u0003חלב\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003יותרת ושתי כליות\u0004 — \u0003לא,\u0004 משום כך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"ריח ניחח\". ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 \u0003\"לריח ניחח\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אפילו מנחה\u0004 (מנחת נסכים) בכלל זה, שגם היא מוקטרת על המזבח — לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"חלב\",\u0004 ללמד שהכוונה היא לדבר שהוא מגופו של הזבח.","קומץ \u0003שלא\u0004 נתקדש \u0003בכלי שרת\u0004 להקטירו — הרי זה \u0003פסול, ור' שמעון מכשיר.\u0004 אם \u0003הקטיר קומצה פעמים,\u0004 כלומר, בשתי פעמים — \u0003כשרה.\u0004","\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון\u0004 שהקומץ כשר גם אם לא קידשו להקטרה בכלי שרת? ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 ביחס למנחה: \u0003\"קדש קדשים היא כחטאת וכאשם\"\u0004 (ויקרא ו, י), ומה שהשווה אותה גם לחטאת וגם לאשם בא לומר שיכול לעשותה כחטאת או כאשם, שאם \u0003בא לעובדה ביד\u0004 כחטאת, שלאחר קמיצה רוצה להעלות את הקומץ בידו וכך להקטירו — \u0003עובדה ב\u0004יד \u0003ימין, כ\u0004מו שעושה ב\u0003חטאת\u0004 שמזה מדמה באצבע ידו הימנית. ואם רוצה לעובדה \u0003בכלי\u0004 — \u0003עובדה\u0004 גם \u0003בשמאל, כ\u0004מו שעושה ב\u0003אשם\u0004 שדמו נזרק בכלי על המזבח, וגם בידו השמאלית.","\u0003ור' ינאי אמר:\u0004 לדעת ר' שמעון אין צורך כלל בקידוש בכלי שרת, אלא \u0003כיון שקמצו\u0004 את הקומץ \u0003מכלי שרת, מעלהו ומקטירו\u0004 בכל דרך, \u0003אפילו\u0004 אם היה מניחו לשם כך \u0003בהמיינו\u0004 (באבנט שלו), \u0003ואפילו במקידה\u0004 (כלי) \u0003של חרש. רב נחמן בר יצחק אמר: הכל,\u0004 ובכלל זה ר' שמעון, \u0003מודים בקומץ שטעון קידוש\u0004 בכלי שרת.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על ר' יהודה בר' חייא ממה ששנינו בברייתא: \u0003הקטר חלבים ואברים,\u0004 כלומר, חלבים ואברים העומדים להקטרה, \u0003ו\u0004כן \u0003עצים שהעלן בין ביד בין בכלי, בין בימין ובין בשמאל\u0004 — \u0003כשרין;\u0004 וכן \u0003הקומץ והקטורת והלבונה שהעלן בין ביד בין בכלי, בין בימין בין בשמאל\u0004 — \u0003כשרין.\u0004 אם כן, הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא,\u0004 שאמר שאם עובדה ביד עובדה רק בימין, ולא בשמאל!","ומשיבים, \u0003אמר לך\u0004 \u0005[היה יכול לומר לך]\u0006 \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: לצדדין קתני\u0004 \u0005[הוא שונה],\u0006 כלומר, מה שהוא שונה \"בין ביד בין בכלי בין בימין בין בשמאל\" וכו' יש לפצל לשניים, כאילו הוא שונה: שהעלן \u0003ביד\u0004 — \u0003בימין,\u0004 או \u0003בכלי\u0004 — \u0003בין בימין בין בשמאל.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה בענין זה ממה ששנינו בברייתא אחרת: \u0003קמצו שלא מכלי שרת, וקידשו שלא בכלי שרת, והעלו והקטירו שלא בכלי שרת\u0004 — \u0003פסול, ר' אלעזר ור' שמעון מכשירין במתן\u0004 הקומץ ב\u0003כלי,\u0004 שאין צריך כלי שרת, ושלא כדעת רב נחמן בר יצחק, שאמר שהכל מודים בקומץ שטעון קידוש!","ומשיבים, \u0003אימא\u0004 \u0005[אמור]:\u0006 ר' אלעזר ור' שמעון מכשירים \u0003ממתן כלי ואילך,\u0004 כלומר, לאחר שנתן אותו בכלי שרת לקדשו, שאין צורך להעלותו ולהקטירו בכלי שרת.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שלא כדברי רב נחמן בר יצחק, ממה ששנינו בברייתא, \u0003וחכמים אומרים: קומץ טעון כלי שרת, כיצד? קומצו מכלי שרת ומקדשו בכלי שרת ומעלו ומקטירו בכלי שרת. ר' שמעון אומר: כיון שקמצו מכלי שרת, מעלו ומקטירו שלא בכלי שרת ודיו,\u0004 הרי שלדעת ר' שמעון אין צורך בקידוש הקומץ בכלי שרת!","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך, ר' שמעון אומר: \u0003כיון שקמצו וקדשו בכלי שרת, מעלו ומקטירו ודיו.\u0004","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003קמץ בימינו ונתן\u0004 את הקומץ \u0003בשמאלו\u0004 — \u0003יחזיר\u0004 אותו \u0003לימינו.\u0004 אם היה הקומץ \u0003בשמאלו\u0004"],["\u0003וחישב עליה\u0004 באותה שעה מחשבת פסול, \u0003בין\u0004 שחישב מחשבת \u0003חוץ למקומו בין\u0004 שחישב מחשבת \u0003חוץ לזמנו\u0004 — הרי זה \u0003פסול ואין בו כרת.\u0004","\u0003(ל\"א)\u0004 אם בזמן שהיתה בימינו \u0003חישב עליה\u0004 מחשבת \u0003חוץ למקומו\u0004 — \u0003פסול ואין בו כרת, חוץ לזמנו\u0004 — \u0003פיגול וחייבין עליו כרת, דברי ר' אלעזר ור' שמעון.\u0004","\u0003וחכמים אומרים: כיון שנתנו\u0004 את הקומץ \u0003לשמאל\u0004 — \u0003פסלתו מתנתו\u0004 מה שניתן לשמאל, ושוב אין תקנה להחזירו לימין; \u0003מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003משום דבעי\u0004 \u0005[שצריך]\u0006 הקומץ \u0003קדושה בכלי,\u0004 שיתנו אותו בכלי שרת, \u0003וכיון שנתנו לשמאל\u0004 — \u0003נעשה כדם\u0004 הזבח \u0003שנשפך מצואר בהמה על הרצפה\u0004 קודם שקיבלו בכלי שרת, \u0003ואספו,\u0004 \u0003ש\u0004הוא \u0003פסול,\u0004 ולא יועיל הדבר לתיתו בכלי שרת לאחר מכן.","ונדייק: \u0003מכלל\u0004 הדברים אתה למד ש\u0003ר' אלעזר ור' שמעון\u0004 האומרים שלא פסלתו נתינתו לשמאל \u0003לא בעו\u0004 \u0005[אינם צריכים]\u0006 כלל \u0003מתן\u0004 הקומץ ב\u0003כלי\u0004 שרת לקדשו, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רב נחמן\u0004 בר יצחק, שאמר שגם ר' שמעון מצריך קידוש בכלי! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו דבריו.","ומעירים: \u0003לר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא מסייעא ליה\u0004 \u0005[מסייעת לו]\u0006 ברייתא זו, שהוא אומר (בעמוד הקודם) כי לדעת ר' שמעון, כשעושה את עבודת המנחה ביד צריך שיעשנה בימין, ומשום כך כשהעביר את הקומץ לשמאלו צריך להחזירו לימינו. ואולם \u0003לר' ינאי\u0004 שאמר כי משעה שקמץ את הקומץ מכלי שרת יכול להעלותו ולהקטירו בכל דבר, \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר שתהא זו קושיה חמורה]?\u0006 שהרי מכאן עולה שרק ביד ימין ניתן להקטירו!","ומשיבים, \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003ר' ינאי: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי, \u0003כ\u0004שיטת ה\u0003תנא\u0004 השונה ש\u0003הקטר\u0004 חלבים ואיברים והעלאת הקומץ כשרים בין בימין בין בשמאל, \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003לצדדים קתני\u0004 \u0005[הוא שונה]\u0006 ברייתא זו, כפי שתירצו אותה לעיל לשיטת ר' יהודה בר' חייא, אלא כפשוטה.","נאמר במשנה: \u0003הקטיר קומצה פעמים\u0004 — \u0003כשרה. אמר ר' יהושע בן לוי\u0004 יש לדייק: הקטיר קומצה \u0003פעמים\u0004 כשרה — \u0003ולא פעמי פעמים,\u0004 כלומר, דווקא כשמקטיר מחצית בכל פעם היא כשרה, ולא בפחות מזה, \u0003ור' יוחנן אמר:\u0004 מה ששנינו שהקטיר קומצה \u0003פעמים\u0004 כשרה — \u0003ואפילו\u0004 הקטיר \u0003פעמי פעמים.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ביניהם]?\u0006 במה נחלקו? \u0003אמר ר' זירא:\u0004 האם \u0003יש קומץ\u0004 שהוא \u0003פחות מ\u0004שיעור \u0003שני זיתים ו\u0004האם \u0003יש הקטרה פחותה מכזית איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006","\u0003ר' יהושע בן לוי סבר\u0004 \u0005[סבור]:\u0006 \u0003אין קומץ פחות\u0004 לעולם \u0003משני זיתים,\u0004 \u0003ואין הקטרה פחותה מכזית,\u0004 ולפיכך מה ששנינו במשנה פעמיים הוא בדווקא. \u0003ור' יוחנן סבר\u0004 \u0005[סבור]:\u0006 \u0003יש קומץ פחות משני זיתים, ויש הקטרה פחותה מכזית,\u0004 ואם כן, גם אם הקטיר את הקומץ בכמה פעמים הרי זה כשר.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו בשאלה: \u0003קומץ מאימתי\u0004 בדיוק \u0003מתיר\u0004 את ה\u0003שירים\u0004 של המנחה \u0003באכילה\u0004 לכהנים? \u0003ר' חנינא אומר: משמשלה בו את האור\u0004 (האש), שהתחילה לאחוז בו. \u0003ר' יוחנן אמר: משתצית בו את האור\u0004 משתבער האש \u0003ברובו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לרבה בר רב יצחק:\u0004 \u0003אסברה לך טעמא\u0004 \u0005[אסביר לך\u0006 את \u0005טעמו]\u0006 של \u0003ר' יוחנן,\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"והנה עלה קיטר הארץ כקיטר הכבשן\"\u0004 (בראשית יט, כח), והרי \u0003אין כבשן מעלה קיטור עד שתצית האור ברובו,\u0004 ומכאן הוא לומד לקומץ שנאמרה בו לשון הקטרה (\"והקטיר הכהן את אזכרתה\", ויקרא ב, ב).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין בר רב אדא לרבא: אמרי\u0004 \u0005[אומרים]\u0006 \u0003תלמידיך\u0004 ש\u0003אמר רב עמרם, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין לי אלא דברים שדרכן ליקרב בלילה, כגון אברים\u0004 של עולה \u0003ופדרים\u0004 חלבים של עולה (ושאר קרבנות) — \u0003שמעלן ומקטירן מבוא השמש\u0004 מהשקיעה, \u0003ומתעכלין והולכין כל הלילה כולה,\u0004 שנאמר לגבי העולה: \"היא העולה על מוקדה על המזבח כל הלילה עד הבוקר\" (שם ו, ב), ואולם","\u0003דברים שדרכן\u0004 (שמצוותם) \u0003ליקרב\u0004 על המזבח \u0003ביום, כגון הקומץ והלבונה והקטרת, ומנחת כהנים ומנחת כהן משוח ומנחת נסכים\u0004 הקרבות כליל על המזבח, מנין \u0003שמעלן ומקטירן מבוא השמש?\u0004 ותוהים: מבוא השמש?","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 ש\u0003דרכן ליקרב ביום! אלא\u0004 הכוונה היא: מנין שמעלן ומקטירן \u0003עם בא השמש,\u0004 כלומר, סמוך לשקיעת השמש, \u0003ש\u0004גם הם \u0003מתעכלין והולכין כל הלילה,\u0004 ואין צריך להיגמר עיכולם ביום, \u0003מנין? תלמוד לומר: \"זאת תורת העלה\"\u0004 (שם) — \u0003ריבה\u0004 כל העולים על המזבח.","\u0003והא\u0004 \u0005[והרי]\u0006 אם מעלה ומקטיר את הקומץ \u0003עם בא השמש\u0004 — \u0003לא משכחת לה\u0004 \u0005[אין אתה מוצא]\u0006 \u0003שתצית האור ברובו\u0004 מבעוד יום כדי שיותרו השיריים באכילה, וכדברי ר' יוחנן! ומשיבים, \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 שדייקנו מן הברייתא, שאין צורך שתשלוט האור ברובו — הרי זה כדי \u0003לקלוט,\u0004 כדי שייחשבו הדברים \"לחמו של מזבח\", וכך ניתן להמשיך ולהקטירם כל הלילה, \u0003כאן\u0004 שאמר ר' יוחנן שצריך שתשלוט האור ברובו — \u0003הרי זה כדי\u0004 \u0003להתיר\u0004 את השיריים באכילה לכהנים.","ומעירים: \u0003ר' אלעזר מתני לה\u0004 \u0005[שונה אותה]\u0006 בברייתא \u0003\"מבוא השמש\",\u0004 כמו ששנינו מתחילה, שהקומץ והלבונה וכו' מעלים ומקטירים אותם לאחר שקיעת החמה, \u0003ומוקים לה\u0004 \u0005[ומעמיד אותה]\u0006 \u0003בפוקעין,\u0004 בחלקים שפקעו ונפלו מעל המזבח, שאותם מחזירים ומעלים גם בלילה. \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' ינאי:\u0004 מדובר \u0003בפוקעין.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' ינאי הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' ינאי: קטרת שפקעה מעל גבי המזבח, אפילו קרטין\u0004 (גושים קטנים) \u0003שבה אין מחזירין אותן,\u0004 בניגוד למה ששנינו לשיטתו בברייתא זו! \u0003ותני\u0004 \u0005[ו\u0006כן \u0005שנה]\u0006 \u0003רב חנינא בר מניומי בדבי\u0004 \u0005[ב\u0006בברייתא של \u0005בית מדרשו]\u0006 של \u0003ר' אליעזר בן יעקב:\u0004 נאמר \u0003\"אשר תאכל האש את העלה על המזבח\"\u0004 (שם פסוק ג), ומ\"את העולה\" יש לדייק: \u0003עיכולי עולה,\u0004 כלומר, איברי עולה שנתעכלו באש, \u0003אתה מחזיר\u0004 למזבח, \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחזיר עיכולי קטרת!\u0004 ומשיבים: \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מיכן\u0004 מן הברייתא את המילה \u0003\"קטרת\"\u0004 בין הדברים שמקטירים כל הלילה.","\u0003אמר ר' אסי: כי פשיט\u0004 \u0005[כאשר היה פושט,\u0006 מסביר\u0003]\u0004 \u0003ר' אלעזר\u0004 את מסכת \u0003מנחות בעי הכי\u0004 \u0005[היה שואל]\u0006 כך, וכך \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: קומץ שסידרו\u0004 שהניחו על המזבח, \u0003וסידר\u0004 מ\u0003עליו את המערכה\u0004 של העצים \u0003מהו?\u0004 האם \u0003דרך הקטרה בכך, או אין דרך הקטרה בכך,\u0004 אלא דווקא כשהוא ניתן על המערכה? לשאלה זו לא נמצאה תשובה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003חזקיה: אברין\u0004 של עולה \u0003שסידרן\u0004 על המזבח \u0003וסידר עליהן את המערכה, מהו?\u0004 האם נאמר כי \u0003\"על העצים\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 שנאמר: \"וערכו בני אהרן הכהנים את הנתחים וכו' על העצים אשר על האש אשר על המזבח\" (שם א, ח), וכוונתו — \u0003דוקא על העצים, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דכתיב קרא אחרינא\u0004 \u0005[שכתוב מקרא אחר]:\u0006 \u0003\"אשר תאכל האש את העלה על המזבח\"\u0004 (שם ו, ג), ומשמע שהעולה יכולה להיות על גוף המזבח עצמו — \u0003אי בעי הכי עביד\u0004 \u0005[אם רוצה כך הוא עושה]\u0006 \u0003אי בעי הכי עביד\u0004 \u0005[אם רוצה כך הוא עושה]?\u0006 גם שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יצחק נפחא: אברין שסידרן\u0004 על המזבח \u0003בצידי המערכה\u0004 של העצים, \u0003מהו?\u0004 ומסבירים: \u0003אליבא דמאן דאמר\u0004 \u0005[לפי\u0006 שיטתו \u0005של מי שאומר]\u0006 \"על\" פירושו \u0003על ממש\u0004 — \u0003לא תיבעי לך\u0004 \u0005[לא תישאל לך]\u0006 שאלה זו,"],["ש\u0003\"על העצים\" כתיב\u0004 \u0005[נאמר],\u0006 ולא בצידם,","\u0003כי תיבעי לך\u0004 \u0005[כאשר תישאל לך\u0006 השאלה\u0005]\u0006 הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לפי\u0006 שיטת \u0005מי שאומר]\u0006 במשנה להלן (מנחות צו,א) בענין בזיכים של לחם הפנים ש\"\u0003על\"\u0004 משמעו \u0003בסמוך, מאי\u0004 \u0005[מהו]?\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נאמר \u0003\"על\u0004 העצים\" — \u0003בסמוך\u0004 לעצים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 כאן שנאמר: \"על העצים אשר על האש\" יש לפרש \u0003\"על העצים\" דומיא\u0004 \u0005[בדומה]\u0006 למה שנאמר \u0003\"על המזבח\", מה התם\u0004 \u0005[שם]\u0006 \u0003על\u0004 המזבח \u0003ממש, אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003על\u0004 העצים \u0003ממש?\u0004 לשאלה זו לא נמצא פתרון, ולפיכך \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003הקומץ מיעוטו מעכב את רובו,\u0004 שאם חסר כל שהוא — פסול. \u0003עשרון\u0004 עשירית האיפה סולת שמביאים למנחה \u0003מיעוטו מעכב את רובו. היין\u0004 שמביאים לנסכים \u0003מיעוטו מעכב את רובו.\u0004 לוג \u0003השמן\u0004 שמביאים למנחה \u0003מיעוטו מעכב את רובו.\u0004","\u0003הסולת והשמן\u0004 של המנחה \u0003מעכבין זה את זה. הקומץ והלבונה\u0004 שנותנים על המנחה, שצריך להקטיר את שניהם, \u0003מעכבין זה את זה.\u0004","ביחס למה ששנינו שהקומץ מיעוטו מעכב את רובו, מבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור הדין\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"מלא קמצו\" תרי זימני\u0004 \u0005[שתי פעמים],\u0006 במנחת נדבה (ויקרא ב, ב) ובמנחת חוטא (שם ה, יב), וכל ששנה עליו הכתוב — מעכב.","ומה ששנינו: \u0003עשרון\u0004 המנחה \u0003מיעוטו מעכב את רובו, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"וקמץ הכהן \u0003מסלתה\"\u0004 (שם ב, ב) — מן הסולת שהיתה בה מתחילה, ללמד \u0003שאם חסרה כל שהוא\u0004 — \u0003פסולה.\u0004","ומה ששנינו: \u0003היין\u0004 של הנסכים \u0003מיעוטו מעכב את רובו,\u0004 נלמד ממה שנאמר בפרשת הנסכים: \u0003\"ככה\u0004 יעשה\" (במדבר טו, יא), להדגיש: כך ולא פחות מכך.","ומה ששנינו ש\u0003השמן\u0004 של המנחה \u0003מיעוטו מעכב את רובו,\u0004 השמן של \u0003מנחת נסכים\u0004 נלמד ממה שנאמר: \u0003\"ככה\"\u0004 (שם), \u0003ו\u0004של \u0003מנחת נדבה\u0004 — ממה ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ומשמנה\"\u0004 (ויקרא ב, ב), מן השמן שהיה בה, ללמד \u0003שאם חסר כל שהוא\u0004 — \u0003פסולה.\u0004","ומה ששנינו ש\u0003השמן והסולת מעכבין זה את זה\u0004 נלמד ממה שנאמר: \"וקמץ וכו' \u0003מסלתה ומשמנה\"\u0004 (שם), ללמד שיש צורך בשניהם יחד, ושוב חזר על כך הכתוב במנחת העומר: \u0003\"מגרשה ומשמנה\"\u0004 (שם טז), הרי שנה על כך הכתוב לעכב.","ומה ששנינו: \u0003הקומץ והלבונה מעכבין זה את זה,\u0004 נלמד ממה שנאמר: \"וקמץ וכו' מסלתה ומשמנה \u0003על כל לבונתה\"\u0004 (שם ב), ושוב נאמר במנחת חוטא: \u0003\"ואת כל הלבונה אשר על המנחה\"\u0004 (שם ו, ח), ללמד שהם מעכבים זה את זה.","\u0003שני שעירי יום הכפורים,\u0004 השעיר לה' והשעיר לעזאזל, \u0003מעכבין זה את זה,\u0004 שאין עושים עבודתו של האחד בלא האחר. \u0003שני כבשי עצרת\u0004 הבאים עם שתי הלחם \u0003מעכבין זה את זה. שתי חלות,\u0004 שתי הלחם שמביאים בעצרת \u0003מעכבות זו את זו.\u0004","\u0003שני סדרין\u0004 של לחם הפנים \u0003מעכבין זה את זה. שני בזיכין\u0004 של לבונה של לחם הפנים \u0003מעכבין זה את זה. הסדרין והבזיכין מעכבין זה את זה.\u0004","\u0003שני מינים\u0004 של לחם \u0003שב\u0004קרבן \u0003נזיר,\u0004 חלות ורקיקים (במדבר ו, טו), \u0003שלשה\u0004 מינים \u0003שבפרה\u0004 האדומה, ששורפים עמה עץ ארז ואזוב ושני ותולעת (שם יט, ו), \u0003וארבעה\u0004 מיני לחם \u0003שבתודה,\u0004 חלות ורקיקים, רבוכה וחמץ (ויקרא ז, יב), \u0003וארבעה\u0004 מינים \u0003שבלולב,\u0004 לולב, אתרוג, הדס וערבה (שם כג, מ), \u0003וארבע\u0004 מינים \u0003שבמצורע\u0004 שהוא נטהר על ידם, עץ ארז ואזוב ושני תולעת וציפורים (שם יד, ד) — \u0003מעכבין זה את זה.\u0004","\u0003שבעה הזאות שבפרה\u0004 אדומה, שמזה הכהן מדמה כנגד פתח אהל מועד (במדבר יט, ד), \u0003מעכבות זו את זו. שבע הזיות שעל בין הבדים\u0004 בפר ושעיר של יום הכיפורים (ויקרא טז, יד-טו), וכן ההזיות \u0003שעל הפרכת,\u0004 ו\u0003שעל מזבח הזהב\u0004 ביום הכיפורים, ובשאר כל החטאות הנעשות בפנים — \u0003מעכבות זו את זו.\u0004","ומביאים את המקור לדינים שבמשנתנו. \u0003שני שעירי יום הכפורים מעכבין זה את זה\u0004 — שנאמר בעבודת יום הכיפורים \u0003חוקה\u0004 (\"והיתה לכם לחקת עולם\". ויקרא טז, כט), וכל מקום שנאמר חוקה הוא לעכב.","\u0003שני כבשי עצרת מעכבין זה את זה\u0004 — שנאמרה בהם לשון \u0003הויה\u0004 (\"קדש יהיו\". שם כג, כ), וכל לשון הויה היא לעכב, לומר שכך יהיה ולא אחרת. \u0003שתי חלות\u0004 של עצרת מעכבות זו את זו — שנאמרה בהן \u0003הויה\u0004 (\"סלת תהיינה\". שם יז).","\u0003שני סדרין\u0004 של לחם הפנים — שנאמרה בהם לשון \u0003חוקה\u0004 (\"חק עולם\". שם כד, ט), וכן \u0003שני בזיכין\u0004 — מ\u0003חוקה\u0004 האמורה שם, וכן \u0003הסדרין והבזיכין\u0004 — מ\u0003חוקה\u0004 האמורה שם.","\u0003שני מינים שבנזיר\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בנזיר: \u0003\"כן יעשה\u0004 על תורת נזרו\" (במדבר ו, כא), להדגיש: דווקא כך יעשה. \u0003שלשה\u0004 מינים \u0003שבפרה\u0004 — שנאמרה בה \u0003חוקה\u0004 (\"זאת חקת התורה\". שם יט, ב).","\u0003ארבעה\u0004 מינים \u0003שבתודה\u0004 — \u0003דאיתקש\u0004 \u0005[שהוקשה]\u0006 \u0003לנזיר, דכתיב\u0004 \u0005[שנאמר]\u0006 בתודה: \u0003\"על זבח תודת שלמיו\"\u0004 (ויקרא ז, יג), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"שלמיו\"\u0004 — \u0003לרבות שלמי נזיר,\u0004 וכבר למדנו בנזיר שהמינים שבו מעכבים זה את זה.","\u0003וארבעה\u0004 מינים \u0003שבמצורע\u0004 מעכבים זה את זה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת תהיה תורת המצרע\"\u0004 (ויקרא יד, ב), ולשון הויה היא לעכב. ומה ששנינו: \u0003וארבעה\u0004 מינים \u0003שבלולב\u0004 שמעכבים זה את זה, נלמד מה שנאמר בהם \u0003\"ולקחתם\"\u0004 (שם כג, מ), ודורשים מלה זו במשמעות \u0003לקיחה תמה,\u0004 שלימה.","\u0003אמר רב חנן בר רבא: לא שנו\u0004 שארבעה מינים שבלולב מעכבים זה את זה \u0003אלא\u0004 במקרה \u0003שאין לו\u0004 את כל ארבעה המינים, \u0003אבל יש לו\u0004 את כל הארבעה — \u0003אין מעכבין,\u0004 ויוצא ידי חובתו גם אם נוטל כל אחד בפני עצמו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003ארבעה מינין שבלולב, שנים מהן עושין פירות\u0004 — לולב (של תמר) ואתרוג, \u0003ושנים מהם אין עושין פירות\u0004 — הדס וערבה, \u0003העושין פירות יהיו זקוקין לשאין עושין\u0004 פירות, \u0003ושאין עושין פירות יהיו זקוקין לעושין פירות, ואין אדם יוצא ידי חובתו בהן עד שיהו כולן באגודה אחת;\u0004","\u0003וכן ישראל בהרצאה,\u0004 כאשר הם מתרצים לפני המקום בתפילה ותענית, אינם נענים \u0003עד שיהו כולן באגודה אחת, שנאמר: \"הבונה בשמים מעלותיו ואגדתו על ארץ יסדה\"\u0004 (עמוס ט, ו), לומר שבזמן שהם באגודה אחת הם מיוסדים בארץ. הרי שאין יוצאים בנטילת ארבעה מינים עד שיהיו אגודים כאחד!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003לולב בין אגוד בין שאינו אגוד\u0004 — \u0003כשר; ר' יהודה אומר: אגוד\u0004 — \u0003כשר, שאינו אגוד\u0004 — \u0003פסול.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה?\u0004 ומשיבים: \u0003גמר\u0004 \u0005[\u0006שהוא \u0005לומד]\u0006 בגזירה שוה \u0003קיחה קיחה מאגודת אזוב\u0004 שבפסח מצרים, שנאמר שם: \"ולקחתם אגודת אזוב\" (שמות יב, כב), ובארבעה מינים נאמר: \"ולקחתם לכם פרי עץ הדר\" וכו' (ויקרא כג, מ),","\u0003מה להלן באגודה\u0004 — \u0003אף כאן באגודה.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה טעמם? ומשיבים: \u0003לא גמרי\u0004 \u0005[\u0006הם \u0005אינם למדים]\u0006 גזירה שווה זו של \u0003קיחה קיחה.\u0004","ושואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003לולב מצוה לאוגדו, ואם לא אגדו\u0004 — \u0003כשר, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 אם \u0003לא אגדו אמאי\u0004 \u0005[מדוע]\u0006 \u0003כשר\u0004 בדיעבד? הרי הוא אומר שפסול! \u0003אי רבנן\u0004 \u0005[אם\u0006 תאמר כשיטת \u0005חכמים]\u0006 \u0003מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 \u0003מצוה\u0004 יש בכך? הרי אינם לומדים גזירה שווה של קיחה קיחה!","ומשיבים: \u0003לעולם\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מצוה\u0004 יש כאן? \u0003משום \"זה אלי ואנוהו\"\u0004 (שם טו, ב), שיש לעשות את המצוות בצורה נאה, ומשום כך ראוי ליטול את ארבעת המינים כשהם אגודים יחד.","ושבים לדין משנתנו. מה ששנינו: \u0003שבע הזאות שבפרה מעכבות זו את זו,\u0004 נלמד ממה שנאמרה בפרה אדומה לשון \u0003חוקה\u0004 (במדבר יט, ב).","ומה ששנינו: \u0003שבע הזאות שעל בין הבדים ושעל מזבח הזהב ושעל הפרוכת מעכבות זו את זו;\u0004 הזאות של \u0003יום הכפורים\u0004 — שהרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 בעבודת יום הכיפורים לשון \u0003חוקה\u0004 (ויקרא טז, כט).","הזאות על הפרוכת ועל מזבח הזהב של \u0003פר כהן משוח ו\u0004של \u0003פר העלם דבר של ציבור, ו\u0004של \u0003שעירי עבודה זרה\u0004 — \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005],\u0006 מה שנאמר בפר העלם דבר של ציבור (שם ד, כ): \u0003\"ועשה לפר כאשר עשה לפר\u0004 החטאת\" של כהן משיח (שם ד, ג— יב) \u0003מה תלמוד לומר?\u0004 אין בכך צורך, שהרי ממילא חזרה התורה על כל הפרטים האמורים שם! אלא נאמר כדי \u0003לכפול\u0004 את הציווי \u0003בהזאות,\u0004 ללמד"],["\u0003שאם חיסר אחת מן המתנות\u0004 (הנתינות, ההזאות) \u0003לא עשה כלום.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבע הזאות שבפרה\u0004 אדומה, שהכהן עומד במזרח ומזה מדמה כנגד פתח אהל מועד, \u0003שעשאן\u0004 שלא כראוי, \u0003בין\u0004 שעשאן \u0003שלא לשמן, בין שלא\u0004 היו \u0003מכוונות אל נכח פני אוהל מועד\u0004 (במדבר יט, ד), כלומר, לכיוון פתח ההיכל אלא לצדדים \u0003—\u0004 \u0003פסולות. ו\u0004ההזאות","\u0003שבפנים\u0004 של דם החטאות הפנימיות — פר ושעיר של יום הכיפורים, וכן פר כהן משיח ופר העלם דבר ושעירי עבודה זרה, שצריך להזות \"לפני ה' את פני פרוכת הקדש\" (ויקרא ד, ו), \u0003ו\u0004כן ההזאות \u0003שבמצורע\u0004 שמזה מלוג השמן \"שבע פעמים לפני ה' \" (שם יד, טז), אם עשאן \u0003שלא לשמן\u0004 — \u0003פסולות,\u0004 אבל אם עשאן \u0003שלא מכוונות\u0004 כנגד קדש הקדשים — \u0003כשרות.\u0004","ומתקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 ל\u0003גבי פרה: שלא לשמן\u0004 — \u0003פסולות, שלא מכוונות\u0004 — \u0003כשרות,\u0004 ובברייתא לעיל שנינו שאם עשאן שלא מכוונות — פסולות! \u0003אמר רב חסדא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' יהודה, הא רבנן\u0004 \u0005[זו\u0006 כשיטת \u0005חכמים].\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מחוסרי כפרה,\u0004 כלומר, אלה שצריכים להביא קרבן לגמר טהרתם, כדי להיות מותרים להיכנס למקדש ולאכול מן הקדשים (אף על פי שכבר טבלו מטומאתם והעריבה עליהם השמש), \u0003אם נכנסו לעזרה בשוגג\u0004 — הרי זה \u0003חייב חטאת,\u0004 אם נכנסו \u0003במזיד\u0004 — \u0003ענוש כרת, ואין צריך לומר\u0004 אם נכנס לשם \u0003טבול יום\u0004 מי שטבל מטומאתו ולא העריבה עליו השמש, \u0003ושאר כל הטמאים\u0004 שעדיין לא טבלו מטומאתם.","\u0003וטהורים שנכנסו לפנים ממחיצתן,\u0004 כלומר, נכנסו פנימה מן המקום שבו מותר להם להיכנס, וכגון כהנים שנכנסו להיכל שלא לצורך עבודה, אם נכנסו \u0003להיכל כולו\u0004 בכל חלק ממנו — חייבים \u0003ב\u0004מלקות \u0003ארבעים,\u0004 אם נכנסו \u0003מבית לפרכת\u0004 (לקודש הקדשים), או \u0003אל פני הכפרת,\u0004 שהתקרבו עד לפני הארון — הרי הם \u0003ב\u0004חיוב \u0003מיתה. ר' יהודה אומר: כל היכל כולו ו\u0004גם \u0003מבית לפרכת\u0004 — \u0003ב\u0004מלקות \u0003ארבעים, ו\u0004רק אם ניגש \u0003אל פני הכפרת\u0004 — הרי זה \u0003במיתה.\u0004","ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003בהאי קרא\u0004 \u0005[\u0006הבנתו של \u0005מקרא זה]:\u0006 שנאמר \u0003\"ויאמר ה' אל משה דבר אל אהרן אחיך ואל יבוא בכל עת אל הקדש מבית לפרכת אל פני הכפרת אשר על הארון ולא ימות\"\u0004 (שם טז, ב), \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003אל הקודש,\u0004 כלומר, ההיכל — הרי הוא \u0003בלא יבא\u0004 במצות לא תעשה בלבד, שלוקים עליו ארבעים מלקות, \u0003מבית לפרכת ואל פני הכפרת\u0004 — \u0003בלא ימות,\u0004 שחייב על כך מיתה.","\u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 כך צריך להבין את המקרא, \u0003אל הקודש ומבית לפרכת\u0004 — \u0003בלא יבא,\u0004 \u0003ואל פני הכפרת\u0004 — \u0003בלא ימות.\u0004","ושואלים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 הסבורים שמבית לפרוכת בלאו? ומסבירים: \u0003אי סלקא דעתך כדקאמר\u0004 \u0005[אם עולה על דעתך כמו שאומר]\u0006 \u0003ר' יהודה,\u0004 שמבית לפרוכת במיתה — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \"ואל יבוא בכל עת \u0003אל הקדש\" ו\"אל פני הכפרת\u0004 ולא ימות\", \u0003ולא בעי\u0004 \u0005[ולא צריך]\u0006 היה לכתוב \u0003\"מבית לפרכת\", ואנא אמינא\u0004 \u0005[ואני הייתי אומר]\u0006 מעצמי: אם על ה\u0003היכל\u0004 (\"הקודש\") \u0003מיחייב\u0004 \u0005[חייב]\u0006 מלקות, \u0003מבית לפרכת מבעיא\u0004 \u0005[נצרכה לומר]?\u0006 ואם כן \u0003\"מבית הפרכת\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהוא \u0003במיתה.\u0004","\u0003ור' יהודה\u0004 משיב על כך: \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 \u0003\"אל הקדש\" ולא כתב\u0004 \u0005[ולא היתה כותבת]\u0006 \u0003\"מבית לפרכת\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003קודש\u0004 — \u0003מבית לפרכת,\u0004 קודש הקדשים, והוא בלאו לבד, \u0003אבל היכל\u0004 אפילו איסור \u0003לאו\u0004 \u0005[לא תעשה]\u0006 \u0003נמי לא\u0004 \u0005[גם כן אין\u0006 בו\u0005].\u0006 \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם אומרים על טענה זו? \u0003ההוא לא מצית אמרת\u0004 \u0005[דבר זה לא יכול היית לומר],\u0006 שהרי ה\u0003היכל כולו איקרי\u0004 \u0005[נקרא]\u0006 \u0003\"קודש\", שנאמר: \"והבדילה הפרכת לכם בין הקדש ובין קדש הקדשים\"\u0004 (שמות כו, לג), משמע שההיכל נקרא קודש.","ועוד שואלים: \u0003ור' יהודה מאי טעמא\u0004 \u0005[מה טעמו]\u0006 שמבית לפרוכת בלא תעשה ואינו במיתה? ומשיבים \u0003אי סלקא דעתך כדקא אמרי רבנן\u0004 \u0005[אם עולה על דעתך כמו שאומרים חכמים],\u0006 שמבית לפרוכת ב\"לא ימות\" — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \"אל יבוא \u0003אל הקודש\" ו\"מבית לפרכת\u0004 לא ימות\", \u0003ולא בעי\u0004 \u0005[ולא יצטרך לומר]\u0006 \u0003\"אל פני הכפרת\", ואנא אמינא\u0004 \u0005[ואני\u0006 הייתי \u0005אומר]\u0006 מדעתי: אם \u0003מבית לפרוכת\u0004 חייב \u0003במיתה, אל פני הכפרת מיבעיא\u0004 \u0005[נצרכה\u0006 \u0003לומר]\u0004 שהוא במיתה? ואם כן \u0003\"אל פני הכפרת\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 קודם \"ולא ימות\" \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003\"אל פני הכפרת\" במיתה, \"מבית לפרכת\"\u0004 רק \u0003באזהרה,\u0004 באיסור לא תעשה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם אומרים על טענה זו? ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן],\u0006 אם רק לענין חיוב מיתה באמת \u0003לא צריך\u0004 היה להיכתב אלא \"מבית פרוכת\", \u0003והאי דכתב רחמנא\u0004 \u0005[וזה שכתבה התורה]\u0006 \u0003\"אל פני הכפרת\",\u0004 הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003דרך משופש\u0004 (משובש, עקום), שאם לא נכנס לקודש הקדשים כשפניו למזרח (\"אל פני הכפורת\") אינו חייב מיתה,","\u0003כדתנא דבי\u0004 \u0005[כמו ששנה החכם מבית\u0006 מדרשו\u0003]\u0004 של \u0003ר' אליעזר בן יעקב:\u0004 מה שנאמר \"והזה \u0003אל פני הכפרת קדמה\"\u0004 (ויקרא טז, יד) — \u0003זה בנה\u0004 בנין \u0003אב,\u0004 לימד לכל הדומה לו, ש\u0003כל מקום שנאמר \"פני\" אינו אלא פני קדים,\u0004 הצד הפונה למזרח.","ושואלים: \u0003ור' יהודה,\u0004 מה הוא אומר על טענה זו? הרי לשם כך הוצרך הכתוב! ומשיבים: אם כן \u0003לימא קרא\u0004 \u0005[שיאמר\u0006 \u0003המקרא]\u0004 רק \u0003\"פני\u0004 הכפורת\", \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"אל\"? שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003\"אל\u0004 פני הכפורת\" \u0003דוקא,\u0004 שרק אם נכנס עד לשם חייב מיתה, אבל מבית לפרוכת אינה במיתה. \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 הם אומרים: \u0003\"אל\" לאו\u0004 \u0005[אינו]\u0006 \u0003דוקא,\u0004 אין לדייק מכך.","ומעתה שבים לענין הסתירה שבין הברייתות, האם הזאות של פרה אדומה שאינן מכוונות פסולות או כשרות, \u0003ו\u0004כך מסבירים: \u0003ר' יהודה\u0004 ש\u0003אמר \"אל פני הכפרת\" דוקא,\u0004 שיש לדייק מן המלה \"אל פני הכפורת\" שרק באופן זה הוא חייב, אם כן \u0003\"והזה אל נכח\u0004 פני אהל מועד\" (במדבר יט, ד) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003דוקא\u0004 הוא, ללמד שאם לא היו מכוונות הריהן פסולות.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: \u0003מדהתם לאו\u0004 \u0005[מ\u0006כיון \u0005ששם אין זה]\u0006 \u0003דוקא\u0004 — \u0003הכא נמי לאו\u0004 \u0005[כאן גם כן אין זה]\u0006 \u0003דוקא,\u0004 ואם לא היו מכוונות כשרות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: ל\u0004שיטת \u0003ר' יהודה,\u0004 צריך אתה לומר כי \u0003מ\u0004תוך ש\u0003\"אל\" דוקא,\u0004 גם מה שנאמר בעבודת יום הכיפורים \u0003(אל נכח) [\u0004\"והזה \u0003על]\u0004 פני הכפרת\" (ויקרא טז, יד) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003דוקא\u0004 הוא ומעכב; \u0003אלא\u0004 לפי זה \u0003מקדש שני דלא הוו\u0004 \u0005[שלא היו בו]\u0006 \u0003ארון וכפורת, הכי נמי דלא עביד\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינו עושה]\u0006 \u0003הזאות?\u0004 והרי אין חולק שהיו עושים כן (ראה משנה יומא נג,ב)!","\u0003אמר רבה בר עולא, אמר קרא\u0004 \u0005[המקרא]\u0006 בעבודת יום הכיפורים: \u0003\"וכפר את מקדש הקדש\"\u0004 (שם לג), לומר: לאו דווקא על הארון (\"הקדש\"), אלא \u0003מקום המקודש לקודש,\u0004 כלומר, על המקום המיועד לארון. עד כאן לפי השיטה שהסתירה שבין הברייתות האם הזאות של פרה אדומה שאינן מכוונות כשרות, תלויה במחלוקת רבי יהודה וחכמים.","\u0003רבא אמר: הא והא רבנן\u0004 \u0005[זו וזו\u0006 כשיטת \u0005חכמים],\u0006"],["\u0003הא\u0004 \u0005[זו]\u0006 ששנינו בה שאם עשה את הזאות הפרה שלא מכוונות כשרות — במקרה \u0003דקאי\u0004 \u0005[שעמד]\u0006 הכהן בכיוון \u0003מזרח ומערב ואדי\u0004 \u0005[והיזה],\u0006 שכיון שעמד כשפניו למערב, לעבר פתח אהל מועד, אף על פי שאינו מכוון בדיוק כנגד הפתח הרי זה כשר. \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בה שהוא פסול — במקרה \u0003דקאי\u0004 \u0005[שעמד]\u0006 בכיוון \u0003צפון ודרום ואדי\u0004 \u0005[והיזה],\u0006 שכיון שאינו עומד כלל נגד הפתח הרי זה פסול.","ושבים למה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003ו\u0004הזאות \u0003שבפנים ו\u0004הזאות מלוג השמן \u0003שבמצורע, שלא לשמן\u0004 — \u0003פסולות, שלא מכוונות\u0004 — \u0003כשרות.\u0004 וביחס למצורע מקשים, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 הזאות של מצורע, \u0003בין\u0004 שהיזה אותן \u0003שלא לשמן בין שלא מכוונות\u0004 — \u0003כשרות!\u0004","\u0003אמר רב יוסף, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' אליעזר והא רבנן\u0004 \u0005[וזו\u0006 כשיטת \u0005חכמים];\u0006 \u0003ר' אליעזר\u0004 ש\u0003מקיש אשם לחטאת,\u0004 שמן ההיקש \"כחטאת כאשם תורה אחת להם\" (ויקרא ז, ז) הוא למד שכשם שחטאת פסולה שלא לשמה כך אשם פסול שלא לשמו, ובכלל זה אשם מצורע — הוא \u0003מקיש נמי\u0004 \u0005[גם כן]\u0006 \u0003לוג\u0004 שמן של מצורע \u0003לאשם\u0004 מצורע, שהם כתובים באותו פסוק, ולכן אם היזה מלוג השמן שלא לשמו — פסול, ואילו \u0003רבנן לא מקשי\u0004 \u0005[חכמים אינם מקישים]\u0006 אשם לחטאת, וממילא אין מקום לפסול בלוג השמן.","ומקשים על הסבר זה: \u0003ולר' אליעזר, וכי דבר הלמד בהיקש חוזר ומלמד בהיקש?\u0004 והרי אם למד בהיקש מחטאת לאשם, אינו יכול לחזור וללמד דין זה ללוג!","\u0003אלא אמר רבא\u0004 באופן אחר: \u0003הא והא רבנן\u0004 \u0005[זו וזו\u0006 כדברי \u0005חכמים],\u0006 \u0003כאן\u0004 שהזאות שבמצורע כשרות שלא לשמן, הרי זה כדי \u0003להכשיר הקרבן\u0004 ולהתיר את שיירי הלוג באכילה לכהנים. \u0003כאן\u0004 ששנינו שהן פסולות, הרי זה לענין \u0003להרצות, שלא עלו לבעלים\u0004 (למצורע) \u0003לשום חובה\u0004 ועדיין אינו מותר לאכול בקדשים.","\u0003שבעה קני מנורה מעכבין זה את זה,\u0004 שחייבים להיות שבעה קנים במנורה. וכן \u0003שבעה נרותיה\u0004 שיש בראשי הקנים \u0003מעכבין זה את זה. שתי פרשיות שבמזוזה\u0004 \"שמע\" (דברים ו, א— ט) \"והיה אם שמוע\" (שם יא, יג— כא) \u0003מעכבות זו את זו,\u0004 ולא זו בלבד, \u0003אלא\u0004 \u0003אפילו כתב אחד\u0004 אות אחת חסרה \u0003מעכבן.\u0004","וכן \u0003ארבע פרשיות שבתפילין,\u0004 \"שמע\" \"והיה אם שמוע\" \"קדש לי\" (שמות יג, א— ט) \"והיה כי יביאך\" (שם יא— טז), \u0003מעכבין זו את זו,\u0004 ו\u0003אפילו כתב אחד מעכבן. ארבע ציציות\u0004 שבבגד \u0003מעכבות זו את זו,\u0004 ואם חיסר אחת לא קיים את המצוה, לפי \u0003שארבעתן מצוה אחת. ר' ישמעאל אומר: ארבעתן ארבע מצו‍ת\u0004 נבדלות הן, ואינן מעכבות זו את זו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שקני המנורה מעכבים זה את זה? ומשיבים: משום שלשון \u0003הויה כתיב בהו\u0004 \u0005[נאמר בהם],\u0006 שנאמר: \"כפתוריהם וקנותם ממנה יהיו\" (שם כה, לו).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנורה\u0004 \u0003היתה באה מן העשת\u0004 גוש מתכת, שמכה עליו בקורנס וכך עושה אותה, \u0003ומן הזהב\u0004 היתה באה; אם \u0003עשאה מן הגרוטאות\u0004 שברים שצירף אותם לכלל מנורה — \u0003פסולה,\u0004 עשאה \u0003משאר מיני מתכות\u0004 — \u0003כשרה.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 שאם עשאה \u0003מן הגרוטאות פסולה\u0004 — מפני \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"כולה \u0003מקשה\u0004 אחת זהב טהור\" (שם) \u0003ו\u0004נאמרה שם לשון \u0003הויה\u0004 (\"יהיו\"), לומר שהוא לעיכוב, והרי לענין \u0003שאר מיני מתכות נמי\u0004 \u0005[גם כן]\u0006 נאמר \u0003זהב והויה\u0004 (\"יהיו\")!","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ועשית מנורת זהב טהור מקשה תיעשה\" (שם לא), \u0003\"תיעשה\"\u0004 — בכל אופן, \u0003לרבות\u0004 \u0003שאר מיני מתכות.\u0004 ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\"תיעשה\" מתייחס למה שנאמר שם \"מקשה\", ו\u0003לרבות\u0004 אם עשאה מ\u0003גרוטאות!\u0004 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לפרש כן, משום שעל \u0003\"מקשה\" כתיבה\u0004 \u0005[כתובה]\u0006 \u0003הויה,\u0004 שנאמר \"יהיו כולה מקשה\" (שמות כה, לו), לעכב, מקשה ולא גרוטאות.","ומקשים: הלשון \u0003\"תיעשה\"\u0004 שמשמעה לרבות \u0003נמי\u0004 \u0005[גם כן]\u0006 סמוך ל\u0003\"מקשה\" כתיב\u0004 \u0005[כתובה],\u0006 שנאמר: \"מקשה תיעשה\" (שם לא)! ומשיבים: נאמר \u0003\"מקשה\" \"מקשה\"\u0004 פעמיים (שם בפסוק לא ופסוק לו), ומשם למדנו \u0003לעכב.\u0004","ומקשים: ומדוע לא נאמר כי \u0003\"זהב\" \"זהב\"\u0004 שנאמר פעמיים באותם פסוקים \u0003נמי\u0004 \u0005[גם כן]\u0006 בא \u0003לעכב!\u0004","ודוחים: \u0003האי מאי\u0004 \u0005[זה מהו]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003מן הגרוטאות פסולה,\u0004 אבל \u0003משאר מיני מתכות כשרה\u0004 — \u0003היינו\u0004 \u0005[זהו]\u0006 שהוצרך הכתוב לאמר פעמיים נוספות \u0003\"זהב\" \"זהב\",\u0004 וכן \u0003\"מקשה\" \"מקשה\"\u0004 \u0003לדרשא\u0004 אחרת, המסתמכת על הנחה זאת, וכאשר יבואר להלן. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003מן הגרוטאות כשרה,\u0004 אבל אם עשאה \u0003משאר מיני מתכות פסולה,\u0004 אם כן \u0003\"זהב\" \"זהב\" \"מקשה\" \"מקשה\" מאי דרשת ביה\u0004 \u0005[מה אתה דורש בו]?\u0006","ומסבירים: \u0003מאי דרשא\u0004 \u0005[מהי הדרשה]\u0006 שאנו דורשים לדרך זו מן הכפילות של \"זהב\"? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר \u0003\"ככר זהב טהור יעשה אתה את כל הכלים האלה\"\u0004 (שם לט, כא), לומר: אם המנורה \u0003באה זהב\u0004 — הרי היא \u0003באה\u0004 במשקל \u0003ככר\u0004 דווקא, אם \u0003אינה באה זהב,\u0004 אלא משאר מיני מתכות — \u0003אינה באה ככר,\u0004 אלא פחות או יותר מככר. וכן מה שנאמר \"זהב\" שוב בסמוך ל\u0003\"גביעיה כפתוריה ופרחיה\"\u0004 (שם פסוק לא), בא ללמד: אם \u0003באה זהב\u0004 — \u0003באה\u0004 עם \u0003גביעים כפתורים ופרחים, אינה באה זהב\u0004 אלא משאר מיני מתכות — \u0003אינה באה\u0004 עם \u0003גביעים כפתורים ופרחים.\u0004","ולגופה של דרשה זו מקשים: \u0003ואימא נמי\u0004 \u0005[ואמור גם כן]\u0006 לגבי קני המנורה, שגם בסמוך להם נאמר \"זהב\" (שם פסוק לו): אם \u0003באה זהב\u0004 — \u0003באה\u0004 גם \u0003קנים, אינה באה זהב\u0004 — \u0003אינה באה קנים,\u0004 אלא די בקנה אחד בלבד! ומשיבים: \u0003ההוא\u0004 קנה אחד בלבד אינו נקרא מנורה, אלא \u0003פמוט מיקרי\u0004 \u0005[נקרא].\u0006 ומהי הדרשה ביחס ל\"מקשה\"?","שנאמר: \u0003\"וזה מעשה המנרה מקשה זהב\"\u0004 (במדבר ח, ד), לומר: אם \u0003באה זהב\u0004 — \u0003באה מקשה, אינה באה זהב\u0004 — \u0003אינה באה מקשה,\u0004 אלא יכול לעשותה מגרוטאות.","ושואלים: \u0003\"מקשה\" דסיפא\u0004 \u0005[ש\u0006נאמר \u0005בסוף\u0006 אותו פסוק\u0005],\u0006 שנאמר שם \"מקשה היא\", \u0003למאי אתא\u0004 \u0005[למה בא]?\u0006 ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חצוצרות,\u0004 שהן כשרות גם אם לא נעשו מקשה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חצוצרות\u0004 כסף שנצטוה משה לעשות במדבר \u0003היו באים מן העשת\u0004 (גוש אחד של מתכת) ו\u0003מן הכסף,\u0004 אם \u0003עשאם מן הגרוטאות\u0004 — \u0003כשרים, משאר מיני מתכות\u0004 — \u0003פסולים.\u0004","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003משאר מיני מתכות\u0004 שהם \u0003פסולים\u0004 — מפני \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003כסף ו\u0004נאמר \u0003הויה,\u0004 שנאמר: \"עשה לך שתי חצוצרות כסף מקשה תעשה אותם והיו\" (שם י, ב), והלוא \u0003מן הגרוטאות נמי\u0004 \u0005[גם כן]\u0006 נאמר שיהיו פסולות, שהרי \u0003מקשה והויה\u0004 נאמר בהם! ומשיבים: \u0003מיעט רחמנא\u0004 \u0005[מיעטה\u0006 \u0003התורה]\u0004 ל\u0003גבי מנורה \"מקשה היא\",\u0004 והלשון היא באה למעט: \u0003\"היא\"\u0004 — \u0003ולא חצוצרות.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל הכלים\u0004"],["\u0003שעשה משה, כשרים לו,\u0004 כלומר, בדורו, \u0003וכשרים\u0004 גם \u0003לדורות\u0004 הבאים, \u0003חצוצרות\u0004 שעשה משה — \u0003כשרות לו ופסולות לדורות.\u0004","ושואלים: \u0003חצוצרות מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שאתה אומר כן? \u0003אילימא דאמר קרא\u0004 \u0005[אם תאמר\u0006 משום \u0005שאמר הכתוב]:\u0006 \u0003\"עשה לך\u0004 שתי חצוצרות כסף (במדבר י, ב), ואנו מדייקים: \u0003\"לך\"\u0004 — \u0003ולא לדורות, אלא מעתה,\u0004 מה שנאמר בארון: \u0003\"ועשית לך ארון עץ\"\u0004 (דברים י, א), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003\"לך\" ולא לדורות?\u0004 והלא ארון זה שימש לדורות!","\u0003אלא,\u0004 מה שנאמר שם \"לך\" יש להסבירו באופן אחר, \u0003אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003\"לך\"\u0004 — כוונתו \u0003משלך,\u0004 מרכושך, \u0003אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 שאמר לו הקדוש ברוך הוא: \u0003כביכול, בשלך אני רוצה יותר משלהם\u0004 (משל ישראל), ואם כן \u0003האי נמי\u0004 \u0005[זה גם כן],\u0006 \"לך\" שנאמר בחצוצרות, \u0003מיבעי ליה להכי\u0004 \u0005[נצרך לו לכך]\u0006 לפרש אותו באופן זה, ולא לפוסלן לדורות! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בחצוצרות, \u0003דאמר קרא\u0004 \u0005[שאמר הפסוק]\u0006 \u0003\"לך\" \"לך\" תרי זימני\u0004 \u0005[שתי פעמים],\u0006 שנאמר שם \u0003\"עשה לך\u0004 שתי חצוצרות כסף\" וגם \u0003\"והיו לך\u0004 למקרא העדה\" (במדבר י, ב).","מסופר, \u0003תני\u0004 \u0005[שונה\u0006 היה\u0005]\u0006 \u0003רב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חנין קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף\u0004 ברייתא זו: \u0003מנורה היתה\u0004 \u0003באה מן העשת\u0004 (גוש מתכת) ו\u0003מן הזהב,\u0004 ומכל מקום אם \u0003עשאה של כסף\u0004 — \u0003כשרה.\u0004 עשאה \u0003של בעץ\u0004 (בדיל) \u0003ושל אבר\u0004 (עופרת) \u0003ושל גיסטרון\u0004 (שאר מיני מתכות) — \u0003רבי פוסל, ור' יוסי בר' יהודה מכשיר.\u0004 אם עשאה \u0003של עץ ושל עצם ושל זכוכית\u0004 — \u0003דברי הכל פסולה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מאי דעתך\u0004 \u0005[מה דעתך]?\u0006 מה יסוד המחלוקת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בין מר\u0004 \u0005[חכם זה]\u0006 \u0003ובין מר\u0004 \u0005[חכם זה]\u0006 \u0003כללי ופרטי דרשי\u0004 \u0005[\u0006בדרך \u0005כללים ופרטים הם דורשים]\u0006 את הכתוב במנורה: \"ועשית מנורת זהב טהור וכו' מקשה תיעשה המנורה\" (שמות כה, לא), שיש שם כלל (\"ועשית מנורת\") ופרט (\"זהב\") וכלל (\"תיעשה המנורה\"), ללמד על כל דבר שהוא כעין הפרט שהוא כשר,","\u0003מיהו\u0004 \u0005[\u0006ו\u0005אולם]\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוסי בר' יהודה \u0005סבור]:\u0006 \u0003מה הפרט\u0004 ה\u0003מפורש,\u0004 זהב, הוא \u0003של מתכת\u0004 — \u0003אף כל\u0004 מנורה שעושים תהא \u0003של מתכת,\u0004 ובכלל זה כל מתכת. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003מה הפרט מפורש,\u0004 זהב, הוא \u0003דבר חשוב\u0004 — \u0003אף כל\u0004 מנורה שעושים תהיה דווקא מ\u0003דבר חשוב,\u0004 ולכן דווקא מנורה מכסף כשרה, אבל לא \u0003מבעץ וכיוצא בו.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003סמי דידך מקמי דידי\u0004 \u0005[מחוק\u0006 את הברייתא \u0005שלך מפני\u0006 הברייתא \u0005שלי,\u0006 שאני שונה\u0005],\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כלי שרת שעשאן של עץ\u0004 — \u0003רבי פוסל, ור' יוסי בר' יהודה מכשיר.\u0004 ולפי ברייתא זו \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 מה יסוד המחלוקת? \u0003רבי דריש כללי ופרטי\u0004 \u0005[דורש\u0006 במידת \u0005כללים ופרטים],\u0006 \u0003ור' יוסי בר' יהודה דריש ריבויי ומיעוטי\u0004 \u0005[דורש ריבויים ומיעוטים].\u0006 כיצד?","\u0003רבי דריש כללי ופרטי\u0004 \u0005[דורש כללים ופרטים],\u0006 שמה שנאמר \u0003\"ועשית מנרת\"\u0004 (שמות כה, לא) — הרי זה \u0003כלל,\u0004 ציווי כללי על עשיית מנורה, \u0003\"זהב טהור\"\u0004 — הרי זה \u0003פרט, \"מקשה תיעשה המנורה\"\u0004 — \u0003חזר וכלל,\u0004 אם כן יש לנו \u0003כלל ופרט וכלל,\u0004 ולפי המדות שהתורה נדרשת בהן — \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט, מה הפרט\u0004 (\"זהב\") \u0003מפורש\u0004 הוא \u0003של מתכת, אף כל\u0004 מנורה שאתה עושה תהיה \u0003של מתכת.\u0004","ואילו \u0003ר' יוסי בר' יהודה דריש ריבויי ומיעוטי\u0004 [דורש ריבויים ומיעוטים]: \u0003\"ועשית מנורת\"\u0004 — הרי זה \u0003ריבה, \"זהב טהור\"\u0004 — \u0003מיעט, \"מקשה תיעשה המנורה\"\u0004 — \u0003חזר וריבה,\u0004 ולפי כללי המדרש, \u0003ריבה ומיעט וריבה\u0004 — \u0003ריבה הכל, ו\u0004אם כן \u0003מאי רבי\u0004 \u0005[מה ריבה]\u0006 — \u0003רבי כל מילי\u0004 \u0005[ריבה כל דבר],\u0006 שעושים את המנורה מכל חומר, \u0003ומאי מיעט\u0004 \u0005[ומה מיעט],\u0006 שהרי על כל פנים יש פה גם מיעוט — \u0003מיעט\u0004 מנורה \u0003של חרס,\u0004 שהוא הרחוק ביותר מזהב. אמר לו רב פפא בן רב חנין: מדוע סבור אתה שהברייתא שלך נכונה יותר?","\u0003אדרבה, סמי דידך מקמי דידי\u0004 \u0005[מחוק\u0006 את \u0005שלך מלפני שלי]!\u0006 אמר לו רב יוסף: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003אין לו זהב מביא\u0004 מנורה \u0003אף של כסף,\u0004 אף \u0003של נחשת,\u0004 ו\u0003של ברזל, ושל בדיל, ושל עופרת. ר' יוסי בר' יהודה מכשיר אף בשל עץ,\u0004 משמע שהמחלוקת היא דווקא בעץ, אבל בבדיל ושכמותו גם רבי מכשיר.","\u0003ותניא אידך\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא יעשה אדם בית\u0004 כ\u0003תבנית\u0004 ה\u0003היכל\u0004 בדיוק, או \u0003אכסדרה כנגד\u0004 ה\u0003אולם\u0004 בדיוק, וכן \u0003חצר כנגד עזרה, שלחן כנגד שלחן\u0004 שבמקדש, \u0003מנורה כנגד מנורה, אבל עושה הוא\u0004 מנורה \u0003של חמשה ושל ששה ושל שמנה\u0004 קנים, שלא כמנורת המקדש שהיא של שבעה קנים; \u0003ו\u0004מנורה \u0003של שבעה\u0004 קנים \u0003לא יעשה ואפילו\u0004 \u0003משאר מיני מתכות,\u0004 מפני שמנורה משאר מיני מתכות היתה כשירה גם במקדש.","\u0003ר' יוסי בר ר' יהודה אומר: אף של עץ לא יעשה\u0004 של שבעה קנים, שלא יעשה \u0003כדרך שעשו מלכי בית חשמונאי\u0004 במקדש. \u0003אמרו לו: משם ראיה?\u0004 לא מנורה של עץ עשו, אלא \u0003שפודים של ברזל היו\u0004 להם \u0003וחיפום בבעץ\u0004 ציפו אותם בבדיל כדי שייראו נאים יותר, לאחר ש\u0003העשירו\u0004 \u0003עשאום\u0004 את קני המנורה \u0003של כסף, חזרו והעשירו עשאום של זהב.\u0004","\u0003אמר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003סבא\u0004 \u0005[זקן\u0006 אחד\u0005]:\u0006 \u0003גובהה של מנורה שמנה עשר טפחים.\u0004 כיצד? \u0003הרגלים והפרח\u0004 שעליהם \u0003שלשה טפחים, וטפחיים חלק, ו\u0004עוד \u0003טפח\u0004 אחד \u0003שבו גביע וכפתור ופרח, ו\u0004עוד \u0003טפחיים חלק, וטפח כפתור\u0004","\u0003ושני קנים יוצאין ממנו\u0004 מן הכפתור \u0003אחד אילך\u0004 \u0005[לכאן]\u0006 \u0003ואחד אילך\u0004 \u0005[לכאן],\u0006 \u0003ונמשכין\u0004 הקנים \u0003ועולין כנגד גובהה של מנורה, ו\u0004שוב יש \u0003טפח חלק, וטפח כפתור ושני קנים יוצאין ממנו אחד אילך ואחד אילך,\u0004 וגם הם \u0003נמשכין ועולין כנגד גובהה של מנורה, ו\u0004שוב \u0003טפח חלק, וטפח כפתור ושני קנים יוצאין ממנו אחד אילך ואחד אילך, ונמשכין ועולין כנגד גובהה של מנורה, ו\u0004עוד \u0003טפחיים חלק, נשתיירו שם\u0004 עוד \u0003שלשה טפחים שבהן\u0004 יש \u0003שלשה גביעין וכפתור ופרח.\u0004","\u0003וגביעין\u0004 שהיו במנורה \u0003למה הן דומין? כמין כוסות אלכסנדריים\u0004 צרים וארוכים, \u0003כפתורים למה הן דומין? כמין תפוחי הכרתיים, פרחים למה הן דומין? כמין פרחי העמודין\u0004 שעושים פיתוחים באבן. \u0003ונמצאו\u0004 בסך הכל \u0003גביעין\u0004 במנורה \u0003עשרים ושנים, כפתורים אחד עשר, פרחים תשעה.\u0004","\u0003גביעים מעכבין זה את זה, כפתורים מעכבין זה את זה, פרחים מעכבין זה את זה,\u0004 וכן \u0003גביעים כפתורים ופרחים מעכבין זה את זה.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח],\u0006 מובן מה שנאמר שיש \u0003גביעים עשרים ושנים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובמנרה ארבעה גבעים\u0004 משוקדים\" (שמות כה, לד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"שלשה גבעים משקדים בקנה האחד כפתור ופרח\" וגו'\u0004 (שם לג), ואם כן, בסך הכל \u0003ארבעה\u0004 גביעים \u0003דידה\u0004 \u0005[שלה]\u0006 של המנורה עצמה, כלומר, הקנה האמצעי,"],["\u0003ותמני סרי\u0004 \u0005[ושמונה עשר]\u0006 של ה\u0003קנים,\u0004 שהרי היו ששה קנים, ונאמר: \"שלשה גביעים משוקדים בקנה האחד\" (שמות כה, לג) — \u0003הא עשרין ותרתין\u0004 \u0005[הרי עשרים ושנים].\u0006 \u0003כפתורין נמי\u0004 \u0005[גם כן]\u0006 \u0003אחד עשר\u0004 הם, כיצד? \u0003כפתורין תרי דידה\u0004 \u0005[שנים שלה],\u0006 שנאמר \"כפתוריה\" (שם פסוק לד) ומיעוט רבים שנים, \u0003וששה\u0004 של ה\u0003קנים,\u0004 שנאמר \"בקנה האחד כפתור ופרח\" (שם פסוק לג) — הרי שמונה, ועוד מה שנאמר: \u0003\"וכפתר\u0004 תחת שני הקנים ממנה \u0003וכפתר\u0004 תחת שני הקנים ממנה \u0003וכפתר\u0004 תחת שני הקנים ממנה\" (שם פסוק לה) — \u0003הא חד סר\u0004 \u0005[הרי אחד עשר].\u0006","\u0003אלא פרחים תשעה מנלן\u0004 \u0005[מנין לנו]?\u0006 והרי \u0003פרחים תרי דידה\u0004 \u0005[שנים שלה]\u0006 שנאמר \"ופרחיה\" (שם פסוק לד), \u0003וששה\u0004 של ה\u0003קנים,\u0004 שנאמר \"בקנה האחד כפתור ופרח\" (שם פסוק לג), אם כן \u0003תמניא הוו\u0004 \u0005[שמונה הם]!\u0006 \u0003אמר רב שלמן, כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"עד ירכה עד פרחה מקשה היא\"\u0004 (במדבר ח, ד), לומר שיש עוד פרח אחד, שהיה סמוך לירכה.","\u0003אמר רב: גובהה של מנורה תשעה טפחים. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב שימי בר חייא לרב\u0004 ממה ששנינו: \u0003אבן היתה לפני מנורה ובה שלש מעלות\u0004 (מדרגות), \u0003שעליה הכהן עומד ומטיב את הנרות,\u0004 ואם גובהה של המנורה תשעה טפחים, לשם מה צריך הכהן מעלות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003שימי את\u0004 \u0005[אתה]?\u0006 אתה הוא המקשה לי? \u0003כי קאמינא\u0004 \u0005[כאשר אמרתי]\u0006 שגובה המנורה תשעה טפחים, לא אמרתי על כל גובהה של המנורה (שהוא שמונה עשר טפחים), אלא \u0003משפת קנים ולמעלה,\u0004 מאותה נקודה שהקנים מתחילים להתפצל ממנה.","\u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והפרח והנרות והמלקחים זהב הוא מכלות זהב\"\u0004 (דברי הימים ב ד, כא). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מיכלות זהב\"? אמר רב אמי: שכילתו\u0004 המנורה וכליה \u0003לכל\u0004 ה\u0003זהב\u0004 ה\u0003סגור של שלמה,\u0004 שהשתמש לעשייתה בזהב סגור (שם פסוק כ) בכמות מרובה מאד, \u0003ש\u0004\u0003אמר רב יהודה, אמר רב: עשר מנורות עשה שלמה, וכל אחת ואחת הביא לה\u0004 לצורכה \u0003אלף ככר זהב, והכניסוהו\u0004 את הזהב \u0003אלף פעמים לכור\u0004 לזקק אותו, עד שנתמעט ונשאר זהב נקי ביותר, \u0003והעמידוהו על ככר\u0004 אחד לכל מנורה, כפי שנאמר \"ככר זהב טהור יעשה אותה\" (שמות כה, לט).","ושואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 וכי לא נותר לו זהב? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וכל כלי משקה המלך שלמה זהב וכל כלי בית יער הלבנון זהב סגור אין כסף נחשב בימי שלמה למאומה\"\u0004 (דברי הימים ב ט, כ)! ומשיבים: \u0003זהב סגור קא אמרינן\u0004 \u0005[אומרים אנו]\u0006 שכילתה המנורה, אבל זהב רגיל היה לו.","ושואלים: \u0003ומי חסר כולי האי\u0004 \u0005[והאם הזהב חסר כל כך]\u0006 עד שיוצא ככר אחד מזיקוק של אלף ככרות? \u0003והתניא\u0004 \u0005[והרי שנויה ברייתא],\u0006 \u0003ר' יוסי בר' יהודה אומר: מעשה והיתה מנורת בית המקדש יתירה\u0004 במשקל \u0003על\u0004 מנורה \u0003של משה בדינר זהב קורדיקיני, והכניסוה שמונים פעמים לכור\u0004 עד ש\u0003העמידוהו על ככר\u0004 בדיוק! ומשיבים: \u0003כיון דקאי קאי\u0004 \u0005[שעמד עמד]\u0006 לאחר שזיקק אותו שלמה שוב לא ירד ממנו אלא כדי דינר ולא יותר.","\u0003אמר ר' שמואל בר נחמני, אמר ר' יונתן, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"על המנרה הטהרה\"\u0004 (ויקרא כד, ד)? לומר \u0003שירדו מעשיה ממקום טהרה,\u0004 מן השמים, שהראהו הקדוש ברוך הוא למשה מנורה ועשה כמותה. ושואלים: \u0003אלא מעתה,\u0004 מה שנאמר \u0003\"על השלחן הטהור\"\u0004 (שם פסוק ו), תאמר גם כן \u0003שירדו מעשיו ממקום טהור? אלא\u0004 אנו אומרים אחרת: \u0003טהור\u0004 — \u0003מכלל שהוא\u0004 יכול להיות גם \u0003טמא,\u0004 שהוא ראוי לקבל טומאה, ואם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לגבי המנורה, תפרש: \u0003טהורה מכלל שהיא\u0004 יכולה להיות גם \u0003טמאה!\u0004","ודוחים: \u0003בשלמא התם\u0004 \u0005[נניח,\u0006 מובן הדבר \u0005שם]\u0006 לגבי השולחן \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"על השלחן הטהור\",\u0004 ש\u0003מכלל\u0004 הדברים אתה למד \u0003שהוא\u0004 יכול להיות \u0003טמא?\u0004 הלוא \u0003כלי עץ העשוי לנחת הוא,\u0004 שאינו מיועד לטלטול, \u0003וכל כלי עץ העשוי לנחת אינו מקבל טומאה! אלא מלמד\u0004 שלא תמיד היה מונח במקומו, אלא פעמים היה מיטלטל, \u0003ש\u0004היו \u0003מגביהין אותו לעולי רגלים ומראים להם לחם הפנים\u0004 שהיה עליו, \u0003ואומר להם\u0004 לבאים: \u0003ראו חיבתכם לפני המקום,\u0004 וכיון שכך עשוי היה לקבל טומאה.","אגב כך שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חיבתכם?\u0004 מה החיבה שיש בדבר? ומשיבים: \u0003כ\u0004דברי \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: נס גדול נעשה בלחם הפנים, סילוקו\u0004 לאחר שבוע שלם שהיה מונח על השולחן — \u0003כסידורו,\u0004 שנשאר חם כיום שהניחוהו על השלחן, \u0003שנאמר\u0004 בלחם הפנים: \u0003\"לשום לחם חם ביום הלקחו\"\u0004 (שמואל א כא, ז), שהיה חם ביום שהיו לוקחים אותו.","ושבים לעיקר הענין: \u0003אלא הכא\u0004 \u0005[כאן]\u0006 לגבי המנורה, האם יש לפרש \u0003טהורה מכלל שהיא טמאה?\u0004 הלוא \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהיא יכולה להיות \u0005טמאה, שהרי\u0006 \u0003כלי מתכות נינהו\u0004 \u0005[הם],\u0006 \u0003וכלי מתכות מקבלין טומאה,\u0004 אפילו אם אינם מיטלטלים! \u0003אלא\u0004 בהכרח צריך אתה לדרוש: \u0003שירדו מעשיה ממקום טהרה.\u0004","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין זה, \u0003רבי יוסי ברבי יהודה אומר: ארון של אש ושלחן של אש ומנורה של אש ירדו מן השמים, וראה משה\u0004 את תבניתם \u0003ועשה כמותם, שנאמר\u0004 לאחר הציווי על כלים אלה: \u0003\"וראה ועשה כתבניתם אשר אתה מראה בהר\"\u0004 (שמות כה, מ).","ושואלים: \u0003אלא מעתה,\u0004 לפי זה, מה שנאמר \u0003\"והקמת את המשכן כמשפטו אשר הראית בהר\"\u0004 (שם כו, ל), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תפרש, שהראה לו משכן של אש? ומשיבים: \u0003הכא כתיב\u0004 \u0005[כאן נאמר]\u0006 \u0003\"כמשפטו\",\u0004 כלומר, הלכותיו נאמרו לו, \u0003התם כתיב\u0004 \u0005[שם נאמר]\u0006 \u0003\"כתבניתם\",\u0004 משמע שהראה לו תבנית.","ועוד בענין זה \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן: גבריאל\u0004 המלאך \u0003חגור כמין פסיקיא\u0004 (חגורה רחבה) \u0003היה,\u0004 כדרך האומנים, שחוגרים עצמם כדי שלא ייגררו בגדיהם, \u0003והראה לו למשה\u0004 כיצד \u0003מעשה\u0004 ה\u0003מנורה\u0004 בפועל, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזה מעשה המנרה\"\u0004 (במדבר ח, ד), משמע שהראה לו בדיוק כיצד נעשית המנורה.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי ישמעאל: שלשה דברים היו קשין לו למשה\u0004 להבינם בדיוק, \u0003עד שהראה לו הקדוש ברוך הוא באצבעו\u0004 כיצד הם, \u0003ואלו הן:\u0004 צורת ה\u0003מנורה, וראש חדש\u0004 מתי בדיוק זמן המולד, \u0003ושרצים\u0004 מה הם השרצים האסורים. ומפרטים: \u0003מנורה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזה מעשה המנרה\"\u0004 (במדבר ח, ד). \u0003ראש חודש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"החדש הזה לכם ראש חדשים\"\u0004 (שמות יב, ב). \u0003שרצים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזה לכם הטמא\"\u0004 (ויקרא יא, כט). \u0003ויש אומרים: אף הלכות שחיטה\u0004 הראה לו, \u0003שנאמר: \"וזה אשר תעשה על המזבח\"\u0004 (שמות כט, לח), ושחיטה היא תחילת עשיית המזבח.","נאמר במשנה: \u0003שתי פרשיות שבמזוזה מעכבות זו את זו, ואפילו כתב\u0004 (אות) \u0003אחד מעכבן.\u0004 ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכתב אחד מעכב, שהרי נאמר \"וכתבתם\" (דברים ו, ט) שצריך שתהא הכתיבה תמה ושלמה!","\u0003אמר רב יהודה, אמר רב: לא נצרכה\u0004 הלכה זו \u0003אלא לקוצה של יוד,\u0004 שאפילו חסר קוצה של יוד הרי זה פוסל את המזוזה. ושואלים: \u0003והא נמי פשיטא\u0004 \u0005[והרי זה גם כן פשוט],\u0006 שהרי לא עשה את האות כראוי! \u0003אלא\u0004 נצרכה הלכה זו \u0003לכאידך\u0004 \u0005[לכ\u0006 דבר \u0005אחר]\u0006 שאמר \u0003רב יהודה אמר רב,\u0004 ש\u0003אמר רב יהודה, אמר רב: כל אות שאין גויל\u0004 חלק \u0003מוקף לה מארבע רוחותיה,\u0004 אלא שהיא דבוקה לאות אחרת — הרי \u0003זו\u0004 \u0003פסולה.\u0004","ובדומה לכך \u0003אמר\u0004 חכם \u0003אשיאן בר נדבך משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה:\u0004 אם \u0003ניקב תוכו של ה\"י\u0004 שהיה נקב בחלל של הה\"י — הרי זה \u0003כשר,\u0004 אבל אם היה נקב ב\u0003יריכו\u0004 של הה\"י — \u0003פסול. אמר ר' זירא: לדידי מפרשה לי מיניה\u0004 \u0005[לי נתפרש הדבר ממנו]\u0006 מפיו של \u0003רב הונא, ורבי יעקב אמר: לדידי מפרשה לי מיניה\u0004 \u0005[לי נתפרש הדבר ממנו]\u0006 מפיו של \u0003רב יהודה\u0004 באופן זה: \u0003ניקב תוכו של ה\"י\u0004 — \u0003כשר.\u0004 אבל אם ניקב \u0003יריכו, אם נשתייר בו\u0004 בחלק המחובר לגג האות \u0003כשיעור אות קטנה\u0004 כלומר, כשיעור יו\"ד — \u0003כשר, ואם לאו\u0004 — \u0003פסול.\u0004","מסופר, \u0003אגרא חמוה\u0004 \u0005[חמיו]\u0006 של \u0003ר' אבא\u0004"],["\u0003איפסיקא ליה כרעא\u0004 \u0005[נפסקה לו הרגל]\u0006 של ה\u0003ה\"י\u0004 במילה \u0003\"העם\"\u0004 (שמות יג, ג) שבתפילין \u0003בניקבא\u0004 \u0005[על ידי נקב],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אבא\u0004 חתנו לשאול מה הדין, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם משתייר בו\u0004 ברגל הה\"י \u0003כשיעור אות קטנה\u0004 שמחובר לגג האות — \u0003כשר, ואם לאו\u0004 — \u0003פסול.\u0004","מסופר, \u0003ראמי בר תמרי\u0004 ש\u0003הוא חמוה\u0004 \u0005[חמיו]\u0006 של \u0003רמי בר דיקולי, איפסיקא ליה כרעא\u0004 \u0005[נפסקה לו הרגל]\u0006 של ה\u0003וי\"ו\u0004 במילה \u0003\"ויהרג\u0004 ה' כל בכור\" (שם טו) שבתפילין \u0003בניקבא\u0004 \u0005[על ידי נקב],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' זירא\u0004 לשאול, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אייתי ינוקא דלא חכים\u0004 \u0005[לך הבא תינוק שלא חכם]\u0006 \u0003ולא טפש,\u0004 כלומר, ילד ממוצע, \u0003אי קרי ליה\u0004 \u0005[אם הוא קורא]\u0006 את המילה \u0003\"ויהרג\"\u0004 — \u0003כשר\u0004 הוא, שאות זו \u0003יש לראותה כוי\"ו,\u0004 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003הרי\u0004 \u0003\"יהרג\" הוא,\u0004 כאילו היה כתוב \"ייהרג\" עם שני יודי\"ן, \u0003ופסול.\u0004","\u0003אמר רב יהודה, אמר רב: בשעה שעלה משה למרום\u0004 לקבל את התורה, \u0003מצאו להקדוש ברוך הוא שיושב וקושר כתרים\u0004 (עושה תגים) \u0003לאותיות\u0004 התורה, \u0003אמר לפניו\u0004 משה: \u0003רבונו של עולם, מי מעכב על ידך?\u0004 כלומר, מי מונע ממך לתת את התורה כפי שהיא? \u0003אמר לו: אדם אחד יש שעתיד להיות בסוף כמה דורות ועקיבא בן יוסף שמו,\u0004 ר' עקיבא, \u0003שעתיד לדרוש על כל קוץ וקוץ\u0004 מהכתרים הללו \u0003תילין תילין של הלכות,\u0004 ובשבילו צריך לעשות אותם.","\u0003אמר לפניו: רבונו של עולם, הראהו לי, אמר לו: חזור לאחורך.\u0004 \u0003הלך\u0004 משה רבינו \u0003וישב\u0004 \u0003בסוף שמונה שורות\u0004 בבית המדרש של ר' עקיבא, \u0003ולא היה יודע מה הן אומרים,\u0004 שלא הבין את המשא ומתן, \u0003תשש כחו\u0004 מחולשת הדעת. \u0003כיון שהגיע\u0004 רבי עקיבא \u0003לדבר אחד, אמרו לו תלמידיו: רבי, מנין לך\u0004 דבר זה? \u0003אמר להן: הלכה למשה מסיני.\u0004 שמע כך משה רבינו ו\u0003נתיישבה דעתו,\u0004 שגם זה בכלל התורה שהוא עומד לקבל.","\u0003חזר ובא לפני הקדוש ברוך הוא, אמר לפניו: רבונו של עולם, יש לך אדם\u0004 גדול \u0003כזה ואתה נותן תורה על ידי? אמר לו: שתוק\u0004 ואל תערער, \u0003כך עלה במחשבה לפני. אמר לפניו: רבונו של עולם, הראיתני תורתו, הראני\u0004 מה יהיה \u0003שכרו.\u0004 \u0003אמר לו: חזור\u0004 שוב לאחורך. \u0003חזר לאחוריו, ראה ששוקלין\u0004 את \u0003בשרו\u0004 של ר' עקיבא \u0003במקולין\u0004 (באיטליז), שנהרג ביסורים על ידי הרומאים, \u0003אמר לפניו: רבונו של עולם, זו תורה וזו שכרה? אמר לו: שתוק, כך עלה במחשבה לפני.\u0004","ועוד בענין תגי האותיות \u0003אמר רבא: שבעה אותיות\u0004 מתוך האל\"ף בי\"ת \u0003צריכות שלשה זיונין\u0004 (תגים) על כל אחת מהן, \u0003ואלו הן:\u0004 האותיות \u0003שעטנ\"ז ג\"ץ. אמר רב אשי: חזינא להו לספרי דווקני דבי\u0004 \u0005[ראיתי אותם את הסופרים הדייקנים של בית]\u0006 \u0003רב דחטרי להו לגגיה\u0004 \u0005[שהיו עושים\u0006 כעין \u0005חטוטרת לגגה]\u0006 של האות \u0003חי\"ת,\u0004 \u0003ותלו ליה לכרעיה\u0004 \u0005[ותולים את הרגל]\u0006 השמאלית של ה\u0003ה\"י\u0004 באויר, שדקדקו שלא תהיה מחוברת לגג האות;","\u0003חטרי להו לגגיה\u0004 \u0005[עושים\u0006 כעין \u0005חטוטרת בגגו]\u0006 של ה\u0003חי\"ת\u0004 — רמז הוא: \u0003כלומר, חי\u0004 הקב\"ה \u0003הוא ברומו של עולם, ותלו ליה לכרעיה\u0004 \u0005[ותולים את הרגל]\u0006 של ה\u0003ה\"י,\u0004 טעמו של דבר הוא \u0003כדבעא מיניה\u0004 \u0005[כמו ששאל ממנו]\u0006 \u0003ר' יהודה נשיאה מר' אמי, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"בטחו בה' עדי עד כי ביה ה' צור עולמים\"\u0004 (ישעיהו כו, ד)? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל התולה בטחונו בהקדוש ברוך הוא, הרי\u0004 הוא \u0003לו מחסה בעולם הזה ולעולם\u0004 \u0003הבא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה נשיאה: מה שקשה לי הוא לא פירושו הפשוט של הפסוק, אלא \u0003אנא הכי קא קשיא לי\u0004 \u0005[אני כך קשה לי\u0006\u0003],\u0004 \u0003מאי שנא דכתיב\u0004 \u0005[\u0006ב\u0005מה שונה שנאמר]\u0006 \u0003\"ביה\" ולא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"יה\"?\u0004","אמר לו: \u0003כ\u0004מו ש\u0003דרש ר' יהודה בר ר'\u0004 \u0003אילעאי:\u0004 \"ביה ה' צור עולמים\" — \u0003אלו שני עולמות שברא הקדוש ברוך הוא,\u0004 בשם י—ה, \u0003אחד בה\"י ואחד ביו\"ד, ואיני יודע אם העולם הבא ביו\"ד והעולם הזה בה\"י, אם העולם הזה ביו\"ד והעולם הבא בה\"י;\u0004","\u0003כשהוא אומר: \"אלה תולדות השמים והארץ בהבראם\"\u0004 (בראשית ב, ד), \u0003אל תקרי\u0004 (תקרא) \u0003\"בהבראם\" אלא: בה\"י בראם\u0004 את השמים והארץ, הוי אומר: העולם הזה (השמים והארץ) נברא \u0003בה\"י, והעולם הבא ביו\"ד.\u0004","\u0003ומפני מה נברא העולם הזה בה\"י\u0004 דווקא? \u0003מפני ש\u0004האות ה\"י שפתוחה מצידה התחתון \u0003דומה\u0004 בצורתה \u0003לאכסדרה,\u0004 הפתוחה לרווחה מצידה האחד, רמז \u0003שכל הרוצה לצאת יצא,\u0004 שרשות ביד האדם בעולם הזה לבחור בטוב או ברע. ושואלים: \u0003ומאי טעמא תליא כרעיה\u0004 \u0005[ומה הטעם תלויה רגלו]\u0006 השמאלית של הה\"י, שאינה מגיעה לגג? ומשיבים: \u0003דאי הדר בתשובה מעיילי ליה\u0004 \u0005[שאם הוא חוזר בתשובה מכניסים אותו]\u0006 מן הפתח העליון.","ושואלים: \u0003וליעייל בהך\u0004 \u0005[ושיכנס בזה]\u0006 שממנו יצא! ומשיבים: \u0003לא מסתייעא מילתא\u0004 \u0005[אין הדבר מסתייע],\u0006 מפני שכדי לעשות תשובה צריכים סיוע מלמעלה, \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אם ללצים הוא יליץ ולענוים יתן חן\"\u0004 (משלי ג, לד)? אם \u0003בא\u0004 אדם \u0003לטהר\u0004 — \u0003מסייעין אותו\u0004 מלמעלה (\"לענוים יתן חן\"), \u0003בא לטמא\u0004 — \u0003פותחין לו,\u0004 רק מאפשרים לו ללכת בדרכו (\"ללצים יליץ\"). ועוד שואלים: \u0003ומאי טעמא אית ליה תאגא\u0004 \u0005[ומה טעם יש לו כתר]\u0006 לה\"י בקצה גגו? ומשיבים: \u0003אמר הקדוש ברוך הוא אם\u0004 אדם \u0003חוזר\u0004 בו מעבירה שבידו — \u0003אני קושר לו קשר\u0004 של כתר מלמעלה.","ועוד שואלים: \u0003מפני מה נברא העולם הבא ביו\"ד\u0004 שהיא האות הקטנה? ומשיבים: \u0003מפני שצדיקים שבו מועטים. ומפני מה כפוף ראשו\u0004 של יו\"ד כמין קוץ בצידו השמאלי? \u0003מפני שצדיקים שבו\u0004 בעולם הבא \u0003כפוף ראשיהם מפני מעשיהן,\u0004 לפי \u0003ש\u0004מעשיהן \u0003אינן דומין זה לזה,\u0004 וכל אחד בוש מחבירו.","\u0003אמר רב יוסף: הני תרתי מילי\u0004 \u0005[אלה שני הדברים]\u0006 \u0003אמר רב\u0004 לגבי \u0003ספרים, ותניא תיובתיה\u0004 \u0005[ושנויה תשובה\u0006 לדבריו בברייתא\u0005]:\u0006 \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב: ספר תורה שיש בו שתי טעיות בכל דף ודף,\u0004 כלומר, בכל עמודה ועמודה — \u0003יתקן,\u0004 אם היו בו \u0003שלש\u0004 טעויות בכל דף — \u0003יגנז\u0004 הספר;","\u0003ותניא תיובתיה\u0004 \u0005[ושנויה תשובתו\u0006 בברייתא\u0005]:\u0006 אם היו בו \u0003שלש\u0004 טעויות בכל דף — \u0003יתקן, ארבע\u0004 או יותר — \u0003יגנז.\u0004 ובענין זה \u0003תנא\u0004 \u0005[שנה החכם\u0006 בברייתא\u0005]:\u0006 \u0003אם יש בו\u0004 בספר \u0003דף אחת שלימה\u0004 בלי טעויות — \u0003מצלת על כולו,\u0004 ואפשר לתקן את הכל. \u0003אמר ר' יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: והוא דכתיב רוביה דספרא שפיר\u0004 \u0005[\u0006בזמן \u0005שכתוב רובו של הספר כראוי],\u0006 ולא שכולו מלא טעויות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: אי אית בההוא\u0004 \u0005[אם יש באותו]\u0006 \u0003דף\u0004 שלם \u0003שלש טעיות מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אמר ליה: הואיל ואיתיהיב לאיתקוני מיתקן\u0004 \u0005[הואיל ו\u0006דף זה כשלעצמו \u0005ניתן לתיקון מיתקן\u0006 הספר כולו\u0005].\u0006 ומוסיפים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שאמרנו, שלא ניתן לתקן את הספר כשהיו בו טעויות רבות, אמורים כשהיו בו אותיות \u0003חסירות\u0004 שצריך להוסיף אותן בין השורות, \u0003אבל יתירות לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה,\u0004 מפני שיכול למחוק אותן, ואין זה פגם. ושואלים: \u0003חסירות מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 ניתן לתקן? \u0003אמר רב כהנא: משום דמיחזי\u0004 \u0005[שנראה]\u0006 הספר \u0003כמנומר\u0004 כשמוסיפים אותיות רבות בין השורות.","וכן \u0003מסופר,\u0004 \u0003אגרא חמוה\u0004 \u0005[חמיו]\u0006 של \u0003ר' אבא הוה ליה\u0004 \u0005[היו לו]\u0006 אותיות \u0003יתירות\u0004 רבות \u0003בסיפריה\u0004 \u0005[בספרו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אבא\u0004 לשאול, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא אמרן\u0004 \u0005[לא אמרנו]\u0006 שלא יכול לתקן, \u0003אלא בחסירות,\u0004"],["\u0003אבל יתרות לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש, אלא מוחק את האות היתירה. זוהי הלכה אחת שאמר רב, שיש סתירה לדבריו מברייתא.","\u0003אידך\u0004 \u0005[האחרת]\u0006 היא זו ש\u0003אמר רב: הכותב ספר תורה ובא לגמור, גומר\u0004 בכל מקום \u0003ואפילו באמצע הדף.\u0004 על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003הכותב ספר תורה, בא לו לגמור\u0004 את הספר — \u0003לא יגמור באמצע הדף כדרך ש\u0004הוא \u0003גומר בחומשין\u0004 בודדים הכתובים לעצמם, \u0003אלא מקצר והולך\u0004 ברוחב השורות \u0003עד\u0004 שייגמר הספר ב\u0003סוף הדף!\u0004 ומשיבים: \u0003כי קא אמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 שגומר אפילו באמצע הדף הרי זה \u0003ב\u0004גומר \u0003חומשין.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ספר תורה קאמר\u0004 \u0005[הוא אומר]!\u0006 ומשיבים: כוונתו, \u0003ב\u0004סוף כל אחד מן ה\u0003חומשין\u0004 שהם חלק \u0003של ספר תורה\u0004 שלם. ומכל מקום את סוף התורה כולה מודה רב שצריך לכתוב בסוף הדף. ומקשים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בר אבא אמר רב גידל, אמר רב:\u0004 את המילים \u0003\"לעיני כל ישראל\"\u0004 שבסוף התורה (דברים לד, יב) כותב \u0003באמצע הדף!\u0004 ומשיבים: \u0003ההיא באמצע שיטה\u0004 (שורה) \u0003איתמר\u0004 \u0005[נאמרה],\u0006 כלומר, באמצע רוחב הדף, אבל צריך שיהיה הדבר בסוף הדף לאורכו.","ונחלקו חכמים בענין זה, \u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]:\u0006 \u0003אף באמצע שיטה\u0004 יכול לגמור, ולא רק בסופה. \u0003רב אשי אמר: באמצע שיטה דווקא. והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003באמצע שיטה דווקא.\u0004","כיון שהוזכרה מסורת הלכה זו מביאים עוד מה \u0003ש\u0004\u0003אמר ר' יהושע בר אבא, אמר רב גידל, אמר רב: שמנה פסוקים\u0004 אחרונים \u0003שבתורה,\u0004 מ\"וימת משה\" עד \"לעיני כל ישראל\" (דברים לב ה— יב), \u0003יחיד קורא אותן בבית הכנסת,\u0004 ואין מחלקים אותם לשנים. ואומרים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 נאמרו הדברים האלה, שפסוקים אלה נשתנו מן התורה כולה? ש\u0003לא כ\u0004שיטת \u0003ר' שמעון.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"וימת שם משה עבד ה' \"\u0004(שם ה), ותמוה: \u0003אפשר משה\u0004 עדיין \u0003חי וכתב\u0004 בעצמו: \u0003\"וימת שם משה\"? אלא עד כאן כתב משה, מכאן ואילך כתב יהושע בן נון\u0004 והשלים את הספר, אלו \u0003דברי ר' יהודה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שדברים אלה הם דברי \u0003ר' נחמיה.\u0004","\u0003אמר לו ר' שמעון: אפשר\u0004 ש\u0003ספר תורה חסר\u0004 אפילו \u0003אות אחת? וכתיב\u0004 \u0005[ו\u0006הרי \u0005נאמר]\u0006 קודם לכן בדברי משה אל הלויים: \u0003\"לקח את ספר התורה הזה ושמתם אותו\u0004 בארון\" (שם לא, כו), ואם כן בשעה שמסרו להם, בחייו, כבר היה זה ספר תורה שלם!","\u0003אלא, עד כאן\u0004 בכל התורה — \u0003הקדוש ברוך הוא אומר ומשה כותב ו\u0004גם \u0003אומר\u0004 מה שכותב, \u0003מכאן ואילך\u0004 ממה שנאמר \"וימת משה\" — \u0003הקדוש ברוך הוא אומר\u0004 את הדברים \u0003ומשה כותב בדמע,\u0004 ולא היה אומר את הדברים, מרוב צערו, \u0003כמה שנאמר להלן,\u0004 בנבואת החורבן שאמר ירמיהו לסופרו ברוך בן נריה: \u0003\"ויאמר להם ברוך מפיו יקרא אלי את כל הדברים האלה ואני כתב על הספר בדיו\"\u0004 (ירמיהו לא, כו).","ואם כן, האם \u0003לימא\u0004 \u0005[נאמר],\u0006 שדברי רב גידל בשם רב, שיש לפסוקים האחרונים של התורה דין מיוחד, הם ש\u0003לא כר' שמעון?\u0004 שהרי לדעתו אין הבדל בין פסוקים אלו לכל התורה. ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' שמעון,\u0004 יש לומר כי \u0003הואיל ואישתני אישתני\u0004 \u0005[כיון שהשתנה,\u0006 שנכתב בדמע, \u0005נשתנה\u0006 גם דינו\u0005].\u0006","\u0003ו\u0004עוד \u0003אמר ר' יהושע בר אבא, אמר רב גידל, אמר רב: הלוקח\u0004 (קונה) \u0003ספר תורה מן השוק\u0004 — הרי הוא \u0003כחוטף מצוה מן השוק,\u0004 שהרי יש מצוה לכל אחד לכתוב ספר תורה לעצמו. ואם \u0003כתבו\u0004 בעצמו — \u0003מעלה עליו הכתוב כאילו קיבלו מהר סיני. אמר רב ששת: אם הגיה\u0004 בספר תורה \u0003אפילו אות אחת, מעלה עליו\u0004 הכתוב \u0003כאילו כתבו.\u0004","כיון שהזכרנו הלכות כתיבת ספר תורה באים לדון בהם בהרחבה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עושה אדם יריעה\u0004 אחת של קלף \u0003מבת שלש דפין\u0004 (עמודות) \u0003ועד בת שמנה דפין,\u0004 אבל יריעה \u0003פחות מיכן\u0004 (משלוש) \u0003ויתר על כן\u0004 (על שמונה) \u0003לא יעשה.\u0004","\u0003ולא ירבה בדפין,\u0004 לעשות שמונה דפים ביריעה צרה — \u0003מפני שנראה\u0004 כל דף כ\u0003אגרת\u0004 שהשורות בה קצרות. \u0003ולא ימעט ב\u0004מספר ה\u0003דפין\u0004 ביריעה רחבה, \u0003מפני ש\u0004כשהשורות רחבות \u0003עיניו משוטטות\u0004 וקשה למצוא את תחילת השורה. \u0003אלא\u0004 רוחב רצוי של דף הוא \u0003כגון\u0004 שכותב \u0003\"למשפחותיכם למשפחותיכם למשפחותיכם\" שלש פעמים.\u0004","אם \u0003נזדמנה לו יריעה\u0004 רחבה, \u0003בת תשע דפים,\u0004 והרי אין עושים כן — \u0003לא יחלוק\u0004 אותה לשתי יריעות שיש בהן \u0003שלש לכאן ושש לכאן, אלא ארבע לכאן וחמש לכאן,\u0004 כדי שיהיו שוות כמה שאפשר.","\u0003במה דברים אמורים\u0004 שצריך לעשות לפחות שלושה דפים ביריעה? \u0003בתחלת הספר\u0004 ובאמצעו, \u0003אבל\u0004 כשמגיע \u0003בסוף הספר\u0004 — \u0003אפילו פסוק אחד ואפילו דף אחד.\u0004 ותוהים: \u0003פסוק אחד סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 שיכתוב על יריעה שלימה? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 כותב אפילו \u0003פסוק אחד בדף אחד\u0004 ואינו חושש.","\u0003שיעור גליון\u0004 החלק הגלוי, שאיננו כתוב, השוליים: \u0003מלמטה\u0004 — \u0003טפח, מלמעלה\u0004 שהוא מתבלה פחות \u0003—\u0004 \u0003שלש אצבעות, ובין דף לדף\u0004 — יעשה \u0003כמלא ריוח רוחב שתי אצבעות, ובחומשין\u0004 בודדים, שאינם ספר תורה שלם — יתן \u0003מלמטה\u0004 גליון \u0003שלש אצבעות, מלמעלה שתי אצבעות, ובין דף לדף\u0004 — \u0003כמלא ריוח רוחב גודל.\u0004","\u0003ובין שיטה לשיטה\u0004 (שורה לשורה) של ספר תורה — יעשה ריוח \u0003כמלא שיטה, ובין תיבה לתיבה\u0004 (מילה למילה) — יעשה ריוח \u0003כמלא אות קטנה, ובין אות לאות\u0004 — די בריוח \u0003כמלא חוט השערה.\u0004","ומוסיפים: אף שצריך ליתן ריוח כפי ששנינו לעיל, \u0003אל ימעט אדם את הכתב\u0004 לעשות חלק מן השורות באותיות קטנות יותר — \u0003לא מפני ריוח של מטה\u0004 שצריך להשאיר בתחתית הדף, \u0003ולא מפני ריוח של מעלה, ולא מפני ריוח שבין שיטה לשיטה, ולא מפני ריוח שבין פרשה לפרשה,\u0004 שאין זה נוי לספר התורה.","\u0003נזדמנה לו תיבה בת חמש אותיות\u0004 ואינה נכנסת בתוך הדף — \u0003לא יכתוב שתים\u0004 שתי אותיות \u0003בתוך הדף ושלש\u0004 מהן \u0003חוץ לדף,\u0004"],["\u0003אלא\u0004 יכתוב \u0003שלש\u0004 אותיות \u0003בתוך הדף ושתים חוץ לדף.\u0004 ומכל מקום, אם \u0003נזדמנה לו תיבה\u0004 שכולה \u0003בת שתי אותיות,\u0004 כגון \"את\" — \u0003לא יזרקנה\u0004 כולה \u0003לבין הדפין, אלא חוזר וכותב\u0004 אותה \u0003בתחילת השיטה\u0004 הבאה.","\u0003הטועה בשם,\u0004 שהיה צריך לכתוב שם ה', ודילג וכתב את המלה הבאה — \u0003גורר\u0004 (מגרד) \u0003את מה שכתב, ותולה\u0004 (כותב מעל השורה) \u0003את מה שגרר, וכותב את השם על מקום הגרר,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר: אף תולין את השם\u0004 מעל השורה, בלא לגרור מה שכתב. \u0003ר' יצחק אומר:\u0004 לא רק גורר, אלא \u0003אף מוחק\u0004 את מה שהיה קודם, אם היה לח, \u0003וכותב\u0004 את השם במקומו.","\u0003ר' שמעון שזורי אומר: כל השם כולו תולין,\u0004 אבל \u0003מקצתו,\u0004 כלומר, אם היה לו מקום לכתוב רק שתי אותיות ולא את כולו — \u0003אין תולין. ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' מאיר: אין כותבין את השם לא על מקום הגרר ולא על מקום המחק, ואין תולין אותו,\u0004 שאין זה ראוי לו, \u0003כיצד עושה? מסלק את היריעה כולה\u0004 שעשה בה טעות זו \u0003וגונזה.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר: \u0003רב חננאל אמר\u0004 בשם \u0003רב, הלכה: תולין את השם. רבה בר בר חנה, אמר ר' יצחק בר שמואל, הלכה: מוחק וכותב.\u0004","ושואלים: הואיל וכבר נחלקו בכך תנאים, \u0003ולימא מר\u0004 \u0005[ושיאמר חכם זה]\u0006 \u0003הלכה כמר\u0004 \u0005[כחכם זה]\u0006 כלומר, כדעת ר' יוסי, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 יאמר ש\u0003הלכה כמר\u0004 \u0005[כחכם זה,\u0006 כר' יצחק\u0005]!\u0006 ומסבירים: \u0003משום דאפכי להו\u0004 \u0005[\u0006שיש \u0005ש\u0006היו \u0005הופכים אותן,\u0006 את השיטות\u0005]\u0006 של התנאים, ולכן אם היו אומרים רק שמות החכמים לא היו יודעים מה ההלכה, ולכן היו צריכים לפרש את המסקנה.","ומביאים מה ש\u0003אמר רבין בר חיננא, אמר עולא, אמר ר' חנינא: הלכה\u0004 \u0003כר' שמעון שזורי. ולא עוד, אלא כל מקום ששנה ר' שמעון שזורי, הלכה כמותו.\u0004","ושואלים: \u0003אהייא\u0004 \u0005[על מה]\u0006 נאמרו דברים אלה? \u0003אילימא אהא\u0004 \u0005[אם תאמר על זו],\u0006 ש\u0003ר' שמעון שזורי אומר\u0004 בברייתא שהבאנו לעיל: \u0003כל השם כולו תולין, מקצתו אין תולין; והא איתמר עלה\u0004 \u0005[והרי נאמר עליה]:\u0006 \u0003אמר רב חננאל, אמר רב, הלכה: תולין את השם, ורבה בר בר חנה, אמר רב יצחק בר שמואל, הלכה: מוחק וכותב.\u0004","\u0003ואם איתא\u0004 \u0005[יש]\u0006 שעל דין זה אמר ר' חנינא שהלכה \u0005כר' שמעון שזורי,\u0006 \u0003הוא,\u0004 רבין בר חיננא \u0003נמי לימא\u0004 \u0005[גם כן יאמר]\u0006 בשם ר' חנינא: הלכה, כל השם כולו תולין מקצתו אין תולין!","אלא תאמר כי לא על זה נאמר \u0003אלא אהא\u0004 \u0005[על\u0006 הלכה \u0005זו],\u0006 \u0003ר' שמעון שזורי אומר:\u0004 בן פקועה, שהוא ולד בהמה שהיה במעי אמו בשעה שנשחטה, \u0003אפילו\u0004 היה \u0003בן חמש שנים\u0004 וגדול וחזק, שהוא \u0003חורש בשדה\u0004 — \u0003שחיטת אמו\u0004 כשהיה במעיה \u0003מטהרתו,\u0004 ואינו זקוק לשחיטה;","\u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה],\u0006 במקומה במסכת חולין ש\u0003זעירי אמר\u0004 בשם \u0003ר' חנינא: הלכה כר' שמעון שזורי, ואם איתא\u0004 \u0005[יש]\u0006 שלהלכה זו התכוון ר' חנינא, \u0003הוא נמי לימא\u0004 \u0005[גם כן יאמר\u0006 כך\u0005]\u0006 שם בשם ר' חנינא, שהלכה כר' שמעון שזורי!","\u0003אלא אהא\u0004 \u0005[על\u0006 הלכה \u0005זו],\u0006 \u0003בראשונה היו אומרים: היוצא בקולר\u0004 ליהרג על ידי המלכות \u0003ואמר \"כתבו גט לאשתי\",\u0004 אף על פי שלא פירש כראוי \"כתבו ותנו\" — \u0003הרי אלו יכתבו ויתנו,\u0004 שבוודאי לכך התכוון, משום שהוא יודע שהולך למות. \u0003חזרו לומר: אף המפרש\u0004 לים \u0003והיוצא בשיירא\u0004 אם אמר רק \"כתבו\" — כותבים ונותנים, שלכך התכוון. \u0003ר' שמעון שזורי אומר: אף\u0004 חולה \u0003המסוכן\u0004 די שאומר \"כתבו\".","\u0003אי נמי אהא\u0004 \u0005[או גם כן על\u0006 הלכה \u0005זו]\u0006 אמר ר' חנינא, ששנינו: \u0003תרומת מעשר של דמאי\u0004 (שהופרשה מתבואת עם הארץ, שיש חשש שאינו מעשר) \u0003שחזרה למקומה\u0004 שנפלה לתוך שאר התבואה, \u0003ר' שמעון שזורי אומר:\u0004 במקרה זה לא רק בשבת התירו לשאול את עם הארץ על תבואתו ולסמוך עליו, אלא \u0003אף בחול שואלו ואוכלו על פיו.\u0004","ואומרים: \u0003והא איתמר עלה\u0004 \u0005[והרי נאמר על כך],\u0006 \u0003אמר ר' יוחנן: הלכה כר' שמעון שזורי במסוכן\u0004 בענין גט, \u0003ובתרומת מעשר של דמאי, ואם איתא\u0004 \u0005[יש]\u0006 שעל כן אמר ר' חנינא שהלכה כר' שמעון שזורי, \u0003הוא\u0004 עולא \u0003נמי לימא\u0004 \u0005[גם כן יאמר]\u0006 בלשון זו בשם ר' חנינא!","\u0003אלא אהא\u0004 \u0005[על זו]\u0006 התכוון, ש\u0003ר' יוסי בן כיפר אומר משום ר' שמעון שזורי: פול המצרי שזרעו לזרע\u0004 כדי להשתמש בגידולים לזריעה ולא למאכל, אם \u0003מקצתו\u0004 של שדה הפול \u0003השריש\u0004 (היכה שרשים) \u0003לפני ראש השנה ומקצתו\u0004 השריש \u0003אחר ראש השנה\u0004 — \u0003אין תורמין מזה על זה,\u0004 ומדוע? \u0003לפי שאין תורמין ומעשרין לא מן החדש על הישן\u0004 משל שנה זו על של שנה אחרת, \u0003ולא מן הישן על החדש;\u0004","\u0003כיצד יעשה\u0004 כדי לתקן את התבואה? שהרי בזמן הקצירה קשה לדעת מה השריש קודם ומה השריש אחר כך — \u0003צובר גרנו לתוכו,\u0004 כלומר, אוסף את הכל יחד ומערב, \u0003ונמצא\u0004 שבסופו של דבר \u0003תורם ומעשר מן החדש שבו על החדש שבו, ומן הישן שבו על הישן שבו,\u0004 ועל כך אמר ר' חנינא שהלכה כר' שמעון שזורי;","\u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה],\u0006 \u0003אמר ר' שמואל בר נחמני, אמר ר' יוחנן: הלכה כר' שמעון שזורי, ואם איתא\u0004 \u0005[יש],\u0006 שביחס לכך פסק ר' חנינא כר' שמעון שזורי, \u0003הוא\u0004 עולא \u0003נמי לימא\u0004 \u0005[גם כן שיאמר]\u0006 כן בשם ר' חנינא!","\u0003אלא אמר רב פפא:\u0004 דברים אלה נאמרו לענין \u0003שידה,\u0004 ו\u0003רב נחמן בר יצחק אמר:\u0004 נאמרו בענין \u0003יין.\u0004 ומפרטים, \u0003רב פפא אמר:\u0004"],["על \u0003שידה, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 השידה שהיא כעין ארון עץ גדול, ששנינו שאם יש בה נפח ארבעים סאה אינה מקבלת טומאה, מפני שיצאה מתורת כלי, \u0003בית שמאי אומרים: נמדדת\u0004 שיעורה \u0003מבפנים,\u0004 ואם היה בחלל הפנימי ארבעים סאה אינה מקבלת טומאה, \u0003ובית הלל אומרים:\u0004 מודדים אותה \u0003מבחוץ\u0004 כולל עובי השידה עצמה. \u0003ומודים אלו ואלו,\u0004 כלומר, גם בית הלל מודים \u0003שאין עובי הרגלים ועובי הלבזבזין\u0004 (מעין זר על שפת השידה) \u0003נמדד\u0004 בתוך השיעור הזה.","\u0003ר' יוסי אומר: מודים\u0004 הם \u0003שעובי הרגלים ועובי הלבזבזין נמדד, ו\u0004אולם החלל \u0003ש\u0004\u0003ביניהן,\u0004 בין הרגלים והלבזבזין, \u0003אין נמדד. ר' שמעון שזורי אומר:\u0004 דווקא \u0003אם היו רגלים גבוהות טפח\u0004 — \u0003אין\u0004 החלל \u0003ביניהן נמדד,\u0004 מפני שהוא מקום חשוב לעצמו, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003ביניהן נמדד,\u0004 שהוא נחשב כחלק מן השידה. ועל כך אמר ר' חנינא שהלכה כר' שמעון שזורי.","\u0003רב נחמן בר יצחק אמר:\u0004 על ענין \u0003יין\u0004 אמר כן, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' מאיר אומר: שמן תחלה לעולם,\u0004 כלומר, תמיד הוא נחשב ראשון לטומאה, אפילו נגע בו דבר שהוא שני לטומאה, וכדין משקה. \u0003וחכמים אומרים: אף הדבש\u0004 נחשב למשקה, \u0003ר' שמעון שזורי אומר: אף היין.\u0004 ותוהים: האם \u0003מכלל\u0004 הדברים אתה יכול להבין \u0003דתנא קמא סבר\u0004 \u0005[שהתנא הראשון סבור]\u0006 ש\u0003יין לא\u0004 משקה? אלא \u0003אימא\u0004 \u0005[אמור]\u0006 שנה כך, \u0003ר' שמעון שזורי אומר: יין\u0004 נחשב משקה, ולא שמן ודבש.","אגב כך מביאים דבר נוסף שאמר ר' שמעון שזורי. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון שזורי: פעם אחת נתערב לי טבל\u0004 (תבואה שלא הופרשו ממנה תרומות ומעשרות) \u0003בחולין\u0004 מתוקנים, \u0003ובאתי ושאלתי את\u0004 \u0003ר' טרפון\u0004 כיצד לתקן את הטבל שבתוך התערובת, \u0003ואמר לי: לך קח\u0004 (קנה) \u0003לך מן השוק\u0004 תבואה סתם, שלא ברור אם היא מעושרת (דמאי), והיא חייבת במעשרות מדברי חכמים, \u0003ועשר עליו\u0004 על הטבל המעורב מתבואה זו.","ומסבירים את טעמו: \u0003קסבר\u0004 \u0005[סבור]\u0006 ר' טרפון כי \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 מיעוט הטבל \u0003ברובא\u0004 \u0005[ברוב]\u0006 \u0003בטל,\u0004 ופטור מלעשר תערובת זו, ורק חכמים אמרו שאינו בטל וחייבוהו לעשר, \u0003ו\u0004כן הוא סבור ש\u0003רוב עמי הארץ מעשרים הן,\u0004 ולפיכך מן התורה פטור מלעשר על תבואה הנלקחת מן השוק, \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003כתורם מן הפטור על הפטור.\u0004","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]:\u0006 \u0003לך קח\u0004 תבואה \u0003מן הגוי,\u0004 שהיא פטורה מן התורה וחייבת מדרבנן, ועשר ממנה על הטבל שנתבטל ברוב! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 ר' טרפון: \u0003אין קנין לגוי בארץ ישראל\u0004 כדי \u0003להפקיע\u0004 את חובת התבואה \u0003מיד מעשר, ו\u0004אם כן \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003מעשר\u0004 \u0003מן החיוב\u0004 (תבואת הגוי) \u0003על הפטור\u0004 (הטבל שבטל ברוב), ודבר זה אסור.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 גירסה אחרת, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' טרפון: \u0003לך קח מן הגוי\u0004 ועשר על הטבל שבתערובת, ולדרך זו \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003יש קנין לגוי בארץ ישראל להפקיע מיד מעשר, והוה ליה\u0004 \u0005[והרי זה]\u0006 כתורם \u0003מן הפטור על הפטור.\u0004","ועל כך שאלו, \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 עצה אחרת: \u0003קח מהשוק\u0004 מעם הארץ ועשר עליו! ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003אין רוב עמי הארץ מעשרין,\u0004 והרי זה כתורם מן החיוב על הפטור.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר בר שלמיא לרב פפא, הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבין בר חנינא, אמר עולא, אמר ר' חנינא: הלכה כר' שמעון שזורי, ולא עוד, אלא כל מקום ששנה ר' שמעון שזורי הלכה כמותו,\u0004 האם \u0003אף בנתערב ליה\u0004 \u0005[לו]\u0006 \u0003טבל בחולין\u0004 הלכה כמותו, או שמא אין אומרים כן אלא במשנה, ולא בברייתא?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 גם בענין זה הלכה כמותו. \u0003אמר רב אשי: אמר לי מר זוטרא, קשי\u0004 \u0005[התקשה]\u0006 \u0003בה\u0004 בענין זה \u0003ר' חנינא מסורא: פשיטא\u0004 \u0005[פשוט]\u0006 הדבר!"],["\u0003מי קאמר\u0004 \u0005[האם הוא אומר]\u0006 שהלכה כמותו \u0003במשנתינו,\u0004 ולא בברייתא? הרי \u0003\"כל מקום ששנה\" קאמר\u0004 \u0005[הוא אומר]!\u0006","\u0003אמר רב זעירא, אמר רב חננאל, אמר רב: קרע\u0004 שבספר תורה \u0003הבא בשני שיטין,\u0004 כלומר, נכנס משפת הקלף בעומק שתי שורות — \u0003יתפור\u0004 אותו, \u0003בשלש\u0004 — \u0003אל יתפור. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה זוטי\u0004 \u0005[הקטן]\u0006 \u0003לרב אשי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' ירמיה מדיפתי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הא דאמרינן\u0004 [זה שאומרים אנו] \u0003בשלש אל יתפור\u0004 — \u0003לא אמרן\u0004 \u0005[לא אמרנו]\u0006 \u0003אלא בעתיקתא\u0004 \u0005[ב\u0006יריעות \u0005ישנות],\u0006 \u0003אבל חדתתא לית לן בה\u0004 \u0005[\u0006ב\u0005חדשות אין לנו בזה],\u0006 מותר הדבר.","ומוסיפים: \u0003ולא עתיקתא עתיקתא\u0004 \u0005[ולא ישנות ישנות]\u0006 \u0003ממש, ולא חדתתא חדתתא\u0004 \u0005[ולא חדשות חדשות]\u0006 \u0003ממש, אלא הא דלא אפיצן\u0004 \u0005[זה שאינן\u0006 מעובדות \u0005בעפצים]\u0006 נחשבות ישנות, ולא יתפור, \u0003הא דאפיצן\u0004 \u0005[זה ש\u0006מעובדות \u0005בעפצים]\u0006 קרויות חדשות, ויתפור. \u0003והני מילי\u0004 \u0005[ודברים אלה,\u0006 שיכול לתפור, \u0005אמורים]\u0006 \u0003בגידין, אבל בגרדין\u0004 (חוטים) — \u0003לא.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יהודה בר אבא:\u0004 נקרע בריוח ש\u0003בין דף לדף,\u0004 שאם היה שם כתב היה נכנס יותר מעומק שלוש שיטין, וכן אם נקרע \u0003בין שיטה לשיטה, מאי\u0004 \u0005[מה]\u0006 הדין? שאלות אלו לא נפתרו, ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר ר' זעירי, אמר רב חננאל, אמר רב: מזוזה שכתבה שתים שתים,\u0004 שתי מילים בכל שורה — \u0003כשרה. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: אם כתב \u0003שתים\u0004 שתי מילים בשורה אחת, \u0003ושלש\u0004 מילים בשורה שמתחתיה, \u0003ו\u0004מילה \u0003אחת\u0004 בשורה הבאה, \u0003מהו? אמר רב נחמן בר יצחק: כל שכן\u0004 שהיא כשרה, \u0003שעשאה כשירה,\u0004 שכך כותבים את שירת הים \u0003בשורות שאינן מלאות, ואין מספר המלים שווה בהן.\u0004 \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003עשאה כשירה, או\u0004 עשה את ה\u0003שירה כמותה\u0004 בכתיבה רגילה — \u0003פסולה!\u0004 ומשיבים: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 הרי זה \u0003בספר תורה\u0004 ולא במזוזה.","\u0003אתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 \u0003אמר רבה בר בר חנה, אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רב אחא בר בר חנה, אמר ר' יוחנן: מזוזה שעשאה\u0004 שורה \u0003שתים\u0004 (בת שתי מלים), \u0003ו\u0004שורה מתחתיה \u0003שלש, ו\u0004שורה מתחתיה \u0003אחת\u0004 — \u0003כשרה, ובלבד שלא יעשנה כקובה\u0004 כמין אוהל, שיורד ומתרחב, שורה בת מילה אחת, ומתחתיה שתים ומתחתיה שלוש, \u0003ו\u0004כן \u0003בלבד שלא יעשנה כזנב\u0004 בשורות מתקצרות והולכות, שלוש שתים ואחת.","\u0003אמר רב חסדא:\u0004 את שתי המלים האחרונות של המזוזה \u0003\"על הארץ\"\u0004 (דברים יא, כא) כותב לבד \u0003בשיטה אחרונה.\u0004 ונחלקו בפירוש הדבר, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 כותבה \u0003בסוף\u0004 ה\u0003שיטה\u0004 האחרונה, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 כותבה \u0003בתחלת\u0004 ה\u0003שיטה\u0004 האחרונה.","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003בסוף שיטה,\u0004 מבין כי \"למען ירבו ימיכם וכו' כימי השמים על הארץ\" כוונתו \u0003\"כגבה שמים על הארץ\"\u0004 (תהלים קג, יא), ואם כותב \"על הארץ\" בסוף השיטה נמצא שהוא מתחת \"השמים\" שבסוף השורה הקודמת. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בתחילת\u0004 ה\u0003שיטה,\u0004 מבין את הכתוב \"כימי השמים על הארץ\" — \u0003כי היכי דמרחקא\u0004 \u0005[כמו שמרוחקים]\u0006 ה\u0003שמים מ\u0004ה\u0003ארץ,\u0004 וכשכותב את המלים \"על הארץ\" בתחילת השיטה, נמצא שהן מרוחקות מ\"השמים\" שבסוף השיטה הקודמת.","\u0003אמר ר' חלבו: חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב הונא דכריך לה\u0004 \u0005[שהיה כורך,\u0006 מגלגל \u0005אותה]\u0006 את המזוזה לאחר כתיבתה \u0003מ\"אחד\" כלפי \"שמע\",\u0004 כלומר, משמאל לימין, \u0003ועושה\u0004 את שתי \u0003פרשיותיה\u0004 של המזוזה \u0003סתומות,\u0004 שבשורה שגומר בה את \"שמע\" מתחיל בה \"והיה אם שמוע\".","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו, \u0003אמר ר' שמעון בן אלעזר: ר' מאיר היה כותבה\u0004 את המזוזה \u0003על דוכסוסטוס,\u0004 על שכבת העור הפנימית, ולא על קלף, שהוא השכבה החיצונית, ועושה אותה \u0003כמין דף\u0004 שבספר תורה, ארוכה וצרה."],["\u0003ועושה\u0004 לה \u0003ריוח מלמעלה וריוח מלמטה, ועושה פרשיותיה\u0004 של המזוזה \u0003פתוחות,\u0004 שהשורה שנגמרת בה פרשת \"שמע\" נשארת פתוחה, ומתחיל פרשת \"והיה אם שמוע\" בשורה חדשה. \u0003אמרתי לו: רבי, מה טעם\u0004 עושה אתה אותן פתוחות? הלוא סתומות הן בתורה! \u0003אמר לי: הואיל ואין\u0004 הפרשיות \u0003סמוכות\u0004 זו לזו \u0003מן התורה.\u0004","\u0003ואמר רב חננאל, אמר רב: הלכה כר' שמעון בן אלעזר, מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שהלכה כמותו לגבי הפרשיות שעושה אותן \u0003פתוחות?\u0004 וקשה מכאן על רב הונא, תלמידו של רב, שעשאן סתומות!","ודוחים: \u0003לא,\u0004 הלכה כמותו לגבי הענין \u0003של ה\u0004\u0003ריוח\u0004 שעושה מלמעלה ומלמטה. ושואלים: \u0003וכמה ריוח? אמר רב מנשיא בר יעקב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רב שמואל בר יעקב: כמלא אטבא דסיפרי\u0004 \u0005[האטב של הסופרים]\u0006 שהם מחזיקים בו את הדפים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: ואת לא תסברא דכי\u0004 \u0005[ואתה אינך סבור שכאשר]\u0006 \u0003אמר רב\u0004 שהלכה כר' שמעון בן אלעזר, אמר הלכה זו על ה\u0003ריוח\u0004 ולא על הפרשיות? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב אית ליה מנהגא\u0004 \u0005[יש לו מנהג],\u0006 כלומר, לדעתו יש משמעות מחייבת למנהג, \u0003והאידנא נהוג עלמא\u0004 \u0005[ועכשיו נוהגים הכל]\u0006 \u0003בסתומות!\u0004 ומנין שרב סומך על המנהג?","ש\u0003אמר רבה, אמר רב כהנא, אמר רב: אם יבא אליהו ויאמר חולצין\u0004 ליבם \u0003במנעל\u0004 — \u0003שומעין לו,\u0004 אבל אם יאמר \u0003אין חולצין בסנדל\u0004 — \u0003אין שומעין לו, שכבר נהגו העם\u0004 לחלוץ \u0003בסנדל.\u0004","\u0003ורב יוסף אמר\u0004 בשם \u0003רב כהנא, אמר רב: אם יבא אליהו ויאמר אין חולצין במנעל\u0004 — \u0003שומעין לו, אין חולצין בסנדל\u0004 — \u0003אין שומעין לו, שכבר נהגו העם בסנדל;\u0004","\u0003ואמרינן\u0004 \u0005[והיינו אומרים]\u0006 כשעסקנו בבעיה זו: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין לשון רבה ולשון \u0005רב יוסף בדברי רב? לגבי\u0006 \u0003מנעל לכתחילה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 האם ראוי לכתחילה לחלוץ במנעל או לא. ועל כל פנים, מוסכם שלדעת רב יש למנהג תוקף גדול, שלא ניתן לבטלו, והמנהג הוא בסתומות! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שפסק הלכה כר' שמעון בן אלעזר על ה\u0003ריוח\u0004 דווקא? ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003רב נחמן בר יצחק אמר: מצוה\u0004 לכתחילה \u0003לעשותן\u0004 את פרשיות המזוזה \u0003סתומות, ואי עבדינהו\u0004 \u0005[ואם עשה אותן]\u0006 \u0003פתוחות שפיר דמי\u0004 \u0005[יפה,\u0006 כשר \u0005הדבר],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003פתוחות דקאמר\u0004 \u0005[שאומר]\u0006 \u0003ר' שמעון בן אלעזר,\u0004 שר' מאיר היה עושה אותן פתוחות — \u0003אף פתוחות,\u0004 ולאו דווקא סתומות.","ומציעים, \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 מה ששנינו: \u0003כיוצא בו,\u0004 כפי שאין עושים מתפילין של ראש תפילין של יד, כך \u0003ספר תורה שבלה ותפילין שבלו אין עושין מהן מזוזה,\u0004 מפרשיות \"שמע\" \"והיה אם שמוע\" שבהם, ומדוע? \u0003לפי שאין מורידין מקדושה חמורה לקדושה קלה\u0004 יותר, ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003מורידין\u0004 מקדושה חמורה לקדושה קלה — היו \u0003עושין\u0004 מזוזה מפרשיות ספר תורה.","ואם פרשיות המזוזה הן לעולם פתוחות, \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הרי \u0003הכא\u0004 \u0005[כאן]\u0006 בספר תורה הן \u0003סתומות, והכא\u0004 \u0005[וכאן]\u0006 במזוזה הן \u0003פתוחות!\u0004 אלא מכאן שניתן לעשותן גם סתומות. ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 אם לא הטעם שאין מורידים מקדושה חמורה לקדושה קלה, ניתן היה \u0003להשלים\u0004 מזוזה שחסרה בשורה או שתים מספר תורה או תפילין שבלו, אבל לא ניתן לעשות את המזוזה כולה מדף של ספר תורה, מפני שהפרשיות שם סתומות.","ושואלים מצד אחר: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003מורידין\u0004 מקדושה חמורה לקדושה קלה — \u0003עושין\u0004 מזוזה מתפילין? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הלכה למשה מסיני\u0004 — \u0003תפילין\u0004 כותבים \u0003על הקלף\u0004 השכבה החיצונית של עור הבהמה, \u0003ומזוזה על דוכסוסטוס\u0004 השכבה הפנימית; על ה\u0003קלף\u0004 כותבים \u0003במקום\u0004 (בצד) הפונה ל\u0003בשר,\u0004 ואת ה\u0003דוכסוסטוס\u0004 כותבים \u0003במקום\u0004 (בצד) הפונה ל\u0003שער!\u0004 ומשיבים: דבר זה לא נאמר אלא \u0003למצוה\u0004 ולא לעכב.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 אם \u0003שינה\u0004 — \u0003פסול!\u0004 ואומרים: דבר זה נאמר לגבי \u0003תפילין\u0004 שנכתבו על הדוכסוסטוס כמזוזה, ולא לגבי מזוזה שנכתבה על קלף כתפילין. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שינה בין בזה ובין בזה\u0004 — \u0003פסול!\u0004 ומשיבים: אין הכוונה ששינה בין בתפילין ובין במזוזה, אלא \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר ששינה \u0003בתפילין, והא דכתבינהו\u0004 \u0005[וזה שכתב אותם]\u0006 על ה\u0003קלף\u0004 אבל \u0003במקום שער\u0004 ולא במקום בשר, \u0003והא\u0004 \u0005[וזה]\u0006"],["\u0003דכתבינהו\u0004 \u0005[שכתב אותם]\u0006 על \u0003דוכסוסטוס במקום בשר,\u0004 שבשני אלה השינוי פוסל, אבל מזוזה שכתבה על קלף כשרה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 מה שנאמר באותה ברייתא שאם \u0003שינה בזה ובזה\u0004 פסול, ומשמע שגם מזוזה שכתבה על קלף פסולה — \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שינה בזה ובזה\u0004 — \u0003פסול, ר' [אחא מכשיר משום ר'] אחאי בר' חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה אומר זאת \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' עקיבא בר' חנינא.\u0004","ומקשים עוד: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003מורידין\u0004 מקדושה חמורה לקדושה קלה \u0003—\u0004 היו \u0003עושין\u0004 מזוזה מתפילין שבלו? \u0003והא בעיא\u0004 \u0005[והרי צריכה]\u0006 המזוזה \u0003שרטוט\u0004 של שורות קודם שיכתוב, ש\u0003אמר רב מניומי בר חלקיה, אמר רב חמא בר גוריא אמר רב: כל מזוזה שאינה משורטטת\u0004 — \u0003פסולה, ורב מנימין בר חלקיה דידיה\u0004 \u0005[משלו]\u0006 \u0003אומר: שרטוט של מזוזה\u0004 — \u0003הלכה למשה מסיני,\u0004 ובתפילין לא מצאנו שצריך שרטוט!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין מזוזה, האם היא צריכה שרטוט. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ירמיה אומר משום\u0004 (בשם) \u0003רבינו\u0004 רב: \u0003תפילין ומזוזות נכתבות שלא מן הכתב,\u0004 כלומר, בלי להעתיק מן הכתב, אלא מן הזכרון, \u0003ואין צריכות שירטוט.\u0004","ומסכמים, \u0003והילכתא\u0004 \u0005[והלכה היא]\u0006 \u0003תפילין לא בעי\u0004 \u0005[לא צריכות]\u0006 \u0003שרטוט, ומזוזה בעיא\u0004 \u0005[צריכה]\u0006 \u0003שירטוט, ואידי ואידי\u0004 \u0005[וזו וזו]\u0006 \u0003נכתבות שלא מן הכתב. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מיגרס גריסין\u0004 \u0005[גרוסות הן],\u0006 כלומר, שגורות הן בפי כל אדם.","בהמשך למסורת שהוזכרה לעיל, שמסר ר' חלבו את מנהגיו של רב הונא, \u0003אמר רב חלבו: אנא חזיתיה\u0004 \u0005[אני ראיתי]\u0006 את \u0003רב הונא דהוה יתיב אפוריא\u0004 \u0005[שהיה יושב,\u0006 רוצה לשבת \u0005על מיטה]\u0006 ש\u0003ספר תורה\u0004 היה מונח \u0003עליה, וכף לכדא אארעא\u0004 \u0005[והפך כד על הארץ]\u0006 \u0003ואנח עליה\u0004 \u0005[והניח עליו]\u0006 את \u0003ספר\u0004 ה\u0003תורה, והדר יתיב\u0004 \u0005[ואחר כך ישב]\u0006 \u0003במיטה,\u0004 כי \u0003קסבר\u0004 \u0005[סבור היה]:\u0006 \u0003אסור לישב על גבי מיטה שספר תורה מונח עליה.\u0004","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 הלכה זו על מה שאמר \u0003רבה בר בר חנה,\u0004 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מותר לישב על גבי מיטה שספר תורה מונח עליה. ואם לחשך אדם לומר,\u0004 אם יבוא אדם לומר לך כנגד זה: הלוא ידוע \u0003ה\u0004\u0003מעשה בר' אלעזר שהיה יושב על המיטה ונזכר שספר תורה מונח עליה, ונשמט\u0004 מיד מן המיטה \u0003וישב על גבי קרקע, ודומה\u0004 היה \u0003כמי שהכישו נחש,\u0004 שקפץ בבהלה — \u0003התם\u0004 \u0005[שם]\u0006 \u0003ספר תורה על גבי קרקע הוה\u0004 \u0005[היה],\u0006 ובוודאי \u0005שבזיון הוא שהוא יושב על מיטה וספר התורה מונח על הקרקע.\u0006","\u0003אמר רב יהודה, אמר שמואל:\u0004 אם \u0003כתבה\u0004 את המזוזה כ\u0003אגרת,\u0004 כמו שכותבים מכתב, בלי לדקדק בכתיבתה — \u0003פסולה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אתיא\u0004 \u0005[נלמד]\u0006 הדבר בגזירה שווה \u0003כתיבה כתיבה מספר\u0004 התורה, שצריך להיות כתוב כראוי.","\u0003ואמר רב יהודה, אמר שמואל:\u0004 אם \u0003תלאה\u0004 את המזוזה \u0003במקל\u0004 בחלל הפתח ולא קבע אותה במזוזת הפתח — \u0003פסולה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"בשעריך\"\u0004 (דברים ה, ט) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 שתהיה קבועה בשער עצמו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 אם \u0003תלאה\u0004 את המזוזה \u0003במקל\u0004 בחלל הפתח, \u0003או שהניחה\u0004 קבעה \u0003אחר הדלת\u0004 בתוך הבית — יש בכך \u0003סכנה\u0004 \u0003ואין בה מצוה.\u0004","ואומרים: האנשים \u0003של בית מונבז המלך היו עושין בפונדקותיהן כן,\u0004 שהיו תולים מזוזה במקל \u0003זכר למזוזה,\u0004 שלא היו מקיימים בכך מצות מזוזה ממש, אלא כדי להזכיר שיש מצוה כזו.","\u0003ואמר רב יהודה, אמר שמואל: מצוה להניחה\u0004 את המזוזה \u0003בתוך חללו של פתח\u0004 ולא מבחוץ. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 הלוא \u0003\"בשעריך\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 משמע שצריך להיות בתוך השער ולא מבחוץ! ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר רבא: מצוה להניחה\u0004"],["\u0003בטפח הסמוך לרשות הרבים\u0004 אם כן הייתי אומר ש\u0003כמה דמרחק\u0004 \u0005[שהוא מרוחק יותר]\u0006 מפנים הבית הרי זה \u0003מעלי\u0004 \u0005[משובח],\u0006 ויכול להניחה בחוץ ממש, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שהמזוזה \u0005צריכה להיות בתוך חלל הפתח עצמו, ולא מבחוץ.\u0006","\u0003ואמר רב יהודה, אמר שמואל:\u0004 מזוזה ש\u0003כתבה\u0004 \u0003על שני דפין\u0004 — \u0003פסולה. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003כתבה על שני דפין והניחה בשני סיפין\u0004 בשתי מזוזות הפתח — הרי זו \u0003פסולה,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה מונחת \u0003בסף אחד\u0004 — \u0003כשרה,\u0004 למרות שהיא כתובה על שני דפים! ומשיבים: אין הכוונה שהניחה בשני סיפים ממש, אלא \u0003ראויה לשני סיפין קאמר\u0004 \u0005[הוא אומר],\u0006 שאם היתה כתובה על שני דפים, כך שניתן להפרידם זה מזה לשני סיפין — פסולה, וכדברי רב יהודה בשם שמואל.","\u0003ואמר רב יהודה, אמר שמואל: במזוזה,\u0004 כאשר צריך להחליט באיזה צד קובעים אותה, לפי כיוון הכניסה, שבצד ימין שלו נותנים את המזוזה — \u0003הלך אחר היכר ציר.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003היכר ציר? אמר רב אדא: אבקתא,\u0004 החור שבמפתן שציר הדלת סובב בו, שהוא נמצא בצד שאליו נכנסים. ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא הדבר]?\u0006 באיזה מקרה הוצרכנו להיכר זה — \u0003כגון פיתחא דבין תרי בתי\u0004 \u0005[פתח שבין שתי בתים],\u0006 כגון \u0003בין בי גברי לבי נשי\u0004 \u0005[בין חדר האנשים לחדר הנשים],\u0006 שבמקרה זה לא ברור לנו מהו כיוון הכניסה.","\u0003מסופר,\u0004 \u0003ריש גלותא בנא ביתא\u0004 \u0005[ראש הגולה בנה בית\u0006 חדש\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לרב נחמן: קבע לי מזוזתא\u0004 \u0005[מזוזות]\u0006 בבית, \u0003אמר רב נחמן: תלי דשי ברישא\u0004 \u0005[העמד את הדלתות בתחילה]\u0006 כדי שאוכל לדעת היכן לשים את המזוזות, לפי מקום צירי הדלתות.","\u0003אמר רב יהודה, אמר רב:\u0004 אם \u0003עשאה\u0004 את המזוזה \u0003כמין נגר\u0004 (בריח) שתחב אותה לחור שבמזוזת השער, או שקבעה על המזוזה כשהיא שוכבת — \u0003פסולה.\u0004 ומקשים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב יצחק בר יוסף אמר: כולהו מזוזתא דבי\u0004 \u0005[כל המזוזות שהיו בבית]\u0006 \u0003רבי כמין נגר הוו עבידן\u0004 \u0005[היו עשויות],\u0006 \u0003ו\u0004עוד אמר: \u0003ההיא פיתחא דעייל ביה רבי לבי מדרשא\u0004 \u0005[אותו פתח שנכנס בו רבי לבית המדרש]\u0006 \u0003לא הוה לה\u0004 \u0005[לא היה לו]\u0006 \u0003מזוזה!\u0004 ומשיבים: ביחס למזוזה שעשאה כמין נגר \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא דעבידא כסיכתא\u0004 \u0005[זה שעשויה כמין יתד]\u0006 שתוחב אותה לעומק המזוזה כשהיא שוכבת — הרי זה פסול, \u0003הא דעבידא כאיסתוירא\u0004 \u0005[זה שעשויה כמין קרסול\u0006\u0003]\u0004 כלומר, זקופה — הרי זה כשר.","ועל מה שנאמר שהפתח שנכנס בו רבי לבית המדרש לא היה בו מזוזה, שואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא ההוא פיתחא דהוה עייל בה\u0004 \u0005[והרי אותו פתח שהיה נכנס בו]\u0006 \u0003רב הונא לבי מדרשא\u0004 \u0005[לבית\u0006 \u0003המדרש]\u0004 \u0003והויא לה\u0004 \u0005[והיתה לו]\u0006 \u0003מזוזה!\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 פתח\u0005]\u0006 \u0003רגיל הוה\u0004 \u0005[היה],\u0006 שבו היו רגילים להיכנס כולם לבית המדרש. אבל הפתח של רבי היה פתח צדדי, שהיה מיועד לו בלבד, ולכן היה פטור ממזוזה, ש\u0003אמר רב יהודה אמר רב: במזוזה\u0004 \u0003הלך אחר הרגיל.\u0004","\u0003אמר ר' זירא אמר רב מתנא אמר שמואל: מצוה להניחה\u0004 את המזוזה \u0003בתחלת שליש העליון\u0004 של הפתח, \u0003ורב הונא אמר: מגביה מן הקרקע טפח,\u0004 או \u0003מרחיק מן הקורה\u0004 של מעלה \u0003טפח, וכל הפתח כולו\u0004 מלמעלה עד למטה \u0003כשר למזוזה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003מגביה מן הקרקע טפח, ומרחיק מן הקורה טפח, וכל הפתח כולו כשר למזוזה,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר:\u0004 נאמר \u0003\"וקשרתם\u0004 לאות על ידך\" (דברים ב, ח), ונאמר בסמוך \u0003\"וכתבתם\u0004 על מזוזות ביתך\" (שם ט), להקישם זה לזה, \u0003מה קשירה\u0004 היא \u0003בגובה\u0004 החלק העליון של היד — \u0003אף כתיבה בגובה\u0004 הפתח דווקא.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב הונא,\u0004 שאמר שמגביה מן הקרקע טפח או מרחיק מן הקורה טפח — \u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כ\u0004דעת \u0003ר' יהודה, אלא לשמואל\u0004 ש\u0003אמר\u0004 להניחה בתחילת השליש העליון, \u0003כמאן\u0004 \u0005[כמי]\u0006 אמר? \u0003לא כר' יהודה\u0004 \u0003ולא כר' יוסי!\u0004","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן: לעולם\u0004 תפרש \u0003שאמר את דבריו\u0004 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004"],["\u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003תחילת שליש העליון דקא אמר\u0004 \u0005[שהוא אומר]?\u0006 כוונתו \u0003להרחיקה, שלא להרחיקה מן הקורה של מעלה יותר משליש\u0004 גובה הפתח.","\u0003אמר רבא: מצוה להניחה\u0004 את המזוזה בפתח, \u0003בטפח הסמוך לרשות הרבים.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]:\u0006 \u0003כדי שיפגע במזוזה מיד,\u0004 שמיד שנכנס לפתח הבית יפגוש במצוה. \u0003רב חנינא מסורא אומר: כי היכי דתינטריה\u0004 \u0005[כדי שתשמור אותו]\u0006 המזוזה מבחוץ, כמו מה ש","\u0003אמר ר' חנינא: בוא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם, מדת בשר ודם\u0004 — ה\u0003מלך יושב מבפנים ועם\u0004 (עמו, עבדיו) \u0003משמרין אותו מבחוץ,\u0004 ואילו \u0003מדת הקדוש ברוך הוא אינו כן,\u0004 ישראל \u0003עבדיו יושבין מבפנים והוא משמרן מבחוץ\u0004 על ידי המזוזה, \u0003שנאמר: \"ה' שומרך ה' צלך על יד ימינך\"\u0004 (תהלים קכא, ה).","\u0003דרש\u0004 ברבים \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 אם \u0003העמיק לה טפח,\u0004 הכניס את המזוזה בעומק טפח במזוזת הפתח \u0003—\u0004 הרי היא \u0003פסולה.\u0004 ומציעים: \u0003לימא מסייעא ליה\u0004 \u0005[האם נאמר שמסייעת לו]\u0006 הברייתא, ששנינו בה: \u0003הניחה בפצין\u0004 כלומר, בעומק מזוזת העץ של הפתח, \u0003או ש\u0004לאחר שקבעה בפתח \u0003טלה עליה מלבן,\u0004 הוסיף לפתח מסגרת פנימית שמכסה את המזוזה, \u0003אם יש שם\u0004 עומק \u0003טפח\u0004 — \u0003צריך מזוזה אחרת, אם לאו\u0004 — \u0003אינו צריך מזוזה אחרת!\u0004","ודוחים: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה\u0006 הברייתא \u0005ההיא],\u0006 הרי זה \u0003בפתח שאחורי הדלת\u0004 שיש פתח נוסף מעברו השני של הפצים, ופצים זה משמש לשני הפתחים, ובאה הברייתא לומר שאם יש בעובי הפצים טפח — כל פתח חשוב לעצמו, וצריך ליתן מזוזה לכל אחד מהם.","ומקשים: \u0003הא בהדיא קתני לה\u0004 \u0005[הרי במפורש שנינו]\u0006 הלכה זו בהמשך אותה ברייתא: \u0003פתח שאחורי הדלת, אם יש שם טפח\u0004 — \u0003צריך\u0004 עוד \u0003מזוזה אחרת, ואם לאו\u0004 — \u0003אינו צריך מזוזה אחרת!\u0004 ומשיבים: \u0003כיצד קתני\u0004 \u0005[הוא שונה],\u0006 כלומר, אין שם שני דינים, אלא דין אחד שהברייתא ממשיכה ומפרשת: באיזה מקרה שנינו שאם יש שם טפח צריך מזוזה אחרת וכו' — כגון פתח שאחורי הדלת.","ועוד בענין קביעת המזוזה, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003העמיד לה\u0004 בפתח \u0003מלבן של קנים,\u0004 ואינו יכול לקבוע את המזוזה במסמרים לקנים — \u0003חותך\u0004 מעין \u0003שפופרת\u0004 מן הקנה הימני \u0003ומניחה\u0004 את המזוזה במקום אותה שפופרת. \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: לא שנו\u0004 שעושים כן, \u0003אלא\u0004 במקרה \u0003שהעמיד\u0004 את המלבן תחילה \u0003ולבסוף חתך\u0004 שפופרת \u0003והניחה\u0004 למזוזה, \u0003אבל\u0004 אם קודם שהעמיד את המלבן \u0003חתך\u0004 ממנו שפופרת \u0003והניח\u0004 במקומה מזוזה, \u0003ולבסוף העמיד\u0004 את המלבן בפתח — \u0003פסולה,\u0004 כי נאמר \u0003\"תעשה\"\u0004 — \u0003ולא מן העשוי,\u0004 וכאן נתן את המזוזה במלבן קודם שנתחייב במזוזה.","\u0003ואמר רבא: הני\u0004 \u0005[אותם]\u0006 \u0003פיתחי\u0004 \u0003שימאי\u0004 \u0005[פתחים שימאים,\u0006 פגומים\u0005]\u0006 \u0003פטורין מן המזוזה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה הם]\u0006 \u0003פיתחי שימאי? פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב ריחומי ואבא יוסי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: דלית להו\u0004 \u0005[שאין להם]\u0006 \u0003תקרה\u0004 כלל, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: דלית להו שקופי\u0004 \u0005[שאין להם משקוף].\u0006","\u0003אמר רבה בר שילא, אמר רב חסדא: אכסדרה\u0004 (מבנה בכניסה לבית, שפרוץ לגמרי מצידו הקדמי) \u0003פטורה מן המזוזה, לפי שאין לה פצימין\u0004 מכאן ומכאן. ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לה פצימין חייב?\u0004 הרי הפצימים הללו אינם לשם פתח, אלא \u0003לחיזוק תקרה הוא דעבידי\u0004 \u0005[שעשויים]!\u0006","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אף על פי שיש לה פצימין\u0004 — \u0003פטורה,\u0004 לפי \u0003שאין עשויין\u0004 לשם פתח \u0003אלא לחיזוק לתקרה.\u0004 ובדומה לכך \u0003אמר אביי: חזינא להו לאיספלידי דבי מר\u0004 \u0005[ראיתי את\u0006 \u0005האכסדראות של בית אדוני,\u0006 רבה\u0003]\u0004 \u0003דאית להו פצימי ולית להו מזוזתא\u0004 \u0005[שיש להן פצימים ואין להם מזוזות],\u0006 \u0003קסבר\u0004 \u0005[\u0006כ\u0005סבור הוא]:\u0006 \u0003לחיזוק תקרה הוא דעבידי\u0004 \u0005[שעשויים].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003בית שער\u0004 (מבנה בכניסה לחצר) וכן \u0003אכסדרה\u0004 או \u0003מרפסת\u0004 — \u0003חייבין במזוזה!\u0004 ומשיבים: שם מדובר \u0003ב\u0004\u0003אכסדרה דבי\u0004 \u0005[של בית]\u0006 \u0003רב,\u0004 שהיא סגורה מכל הצדדים וגם בכיוון הכניסה, אלא שהדפנות אינן מגיעות עד לתקרה. ומקשים: \u0003אכסדרה דבי\u0004 \u0005[של בית]\u0006 \u0003רב כאינדרונא מעלייתא\u0004 \u0005[כחדר מעולה]\u0006 \u0003הוא,\u0004 ואין מקום להגדירה כאכסדרה לענין זה! אלא מדובר שם \u0003באכסדרה רומיתא\u0004 \u0005[רומאית],\u0006 שאף על פי שעשויה חלונות חלונות, ולא כתלים ממש, חייבת במזוזה.","\u0003אמר רחבה, אמר רב יהודה: בי הרזיקי חייב בשתי מזוזות.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003בי הרזיקי? אמר רב פפא סבא\u0004 \u0005[הזקן]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: בית שער הפתוח לחצר ובתים פתוחין\u0004 גם כן \u0003לבית שער,\u0004 והוא צריך לשתי מזוזות, אחת לכניסה מן החצר אל תוכו, ואחת לכניסה ממנו לבתים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בית שער הפתוח\u0004 מצד אחד \u0003לגינה\u0004 שהיא פטורה ממזוזה, \u0003ו\u0004מצד שני \u0003לקיטונית\u0004 (חדר קטן) שחייבת במזוזה — \u0003ר' יוסי אומר: נידון כקיטונית\u0004 וצריך מזוזה, \u0003וחכמים אומרים: נידון כבית שער\u0004 של הגינה, ופטור ממזוזה. ובפירוש מחלוקת זו נחלקו אמוראים. \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 בפתח שבו נכנסים \u0003מגינה לבית,\u0004 כלומר, בפתח של בית השער לקיטונית — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שהוא \u0003חייב\u0004 במזוזה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 דרך \u0003ביאה\u0004 ל\u0003בית היא,\u0004 והבית חייב במזוזה.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה בפתח \u0003מבית לגינה\u0004 כלומר, בפתח של בית השער לגינה, \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, ר' יוסי, \u0005סבור]:\u0006 \u0003קיטונית\u0004 שבית השער פתוח אליה היא \u0003עיקר,\u0004 ומשום כך רואים את הפתח שבין הגינה לבית השער כפתח הבית, ולכן הוא חייב במזוזה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 ה\u0003גינה עיקר\u0004 בפתח זה, והיא אינה צריכה מזוזה.","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 הפתח \u0003מבית לגינה\u0004 כלומר, הפתח שבין בית השער לגינה — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שהוא \u0003פטור\u0004 ממזוזה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003פיתחא\u0004 \u0005[פתח]\u0006 של ה\u0003גינה הוא. כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה בפתח \u0003מגינה לבית,\u0004 כלומר, בפתח שבין בית השער לקיטונית, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוסי, \u0005סבור]:\u0006 \u0003ביאה\u0004 של ה\u0003בית הוא,\u0004 וחייב במזוזה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003כולה\u0004"],["\u0003אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003גינה הוא דעבידא\u0004 \u0005[שעשויה],\u0006 כדי להגיע לגינה, ולא לצורך כניסה לבית, וגם פתח זה שבין בית השער לקיטונית פטור.","\u0003מספרים:\u0004 \u0003אביי ורבא עבדי\u0004 \u0005[היו עושים]\u0006 \u0003כ\u0004שיטת \u0003רבה ורב יוסף\u0004 בפירוש המחלוקת, ולא היו נותנים מזוזה בשני הפתחים של בית השער, לא לגינה ולא לקיטונית, וכחכמים. \u0003ו\u0004אילו \u0003רב אשי עביד\u0004 \u0005[היה עושה]\u0006 \u0003כ\u0004שיטת \u0003רב ושמואל\u0004 בפירוש המחלוקת \u0003לחומרא\u0004 \u0005[ולהחמיר]\u0006 כשיטת ר' יוסי, ששני הפתחים חייבים במזוזה. ומסכמים: \u0003והילכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב ושמואל לחומרא\u0004 \u0005[להחמיר].\u0006","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003לול\u0004 (ארובה) ש\u0003פתוח מן הבית לעלייה,\u0004 וגרם מדרגות עובר בו, \u0003אמר רב הונא: אם יש לו פתח אחד\u0004 לאותו מעבר, מצד הבית או מצד העליה — \u0003חייב במזוזה אחת, אם יש לו שני פתחין,\u0004 מלמטה ומלמעלה — \u0003חייב בשתי מזוזות. אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003מ\u0004דברי \u0003רב הונא, האי אינדרונא דאית ליה\u0004 \u0005[אותו חדר שיש לו]\u0006 \u0003ארבעה באבי\u0004 \u0005[שערים]\u0006 — \u0003חייב בארבע מזוזות.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 לומר אלא \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003רגיל\u0004 להשתמש רק \u0003בחד\u0004 \u0005[באחד\u0006 מהם\u0005].\u0006","\u0003אמר אמימר: האי פיתחא דאקרנא\u0004 \u0005[הפתח שנמצא בקרן,\u0006 בזוית הבית\u0005]\u0006 \u0003חייב במזוזה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והא לית ליה\u0004 \u0005[והרי אין לו]\u0006 \u0003פצימין,\u0004 מזוזות! \u0003אמר ליה: עדי פצימי\u0004 \u0005[אלה\u0006 הם \u0005פצימיו]\u0006 כלומר, הקצוות של הקירות הם הם הפצימים שלו.","\u0003מסופר,\u0004 \u0003רב פפא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003מר שמואל, חזא ההוא פיתחא דלא הוה ליה\u0004 \u0005[ראה פתח אחד שלא היה לו]\u0006 \u0003אלא פצים\u0004 (מזוזת שער) \u0003אחד משמאלא\u0004 \u0005[מצד שמאל]\u0006 של הכניסה, \u0003ועבידא ליה\u0004 \u0005[ועשה לו]\u0006 \u0003מזוזה\u0004 לאותו פצים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003כמאן\u0004 \u0005[כמי]\u0006 אתה נוהג, \u0003כ\u0004דעת \u0003ר' מאיר,\u0004 המחייב מזוזה בפתח שיש לו פצים אחד? \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' מאיר\u0004 בפצים שנמצא \u0003מימין,\u0004 אבל \u0003מ\u0004צד \u0003שמאל מי\u0004 \u0005[האם]\u0006 \u0003אומר?\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 מנין שצריך ליתן מזוזה בצד ימין? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר \"על מזוזות \u0003ביתך\"\u0004 (דברים ו, ט) יש לדורשו: ביתך = \u0003ביאתך, מן הימין,\u0004 מצד ימין של ביאתך לבית. \u0003אתה אומר מן הימין? או אינו אלא משמאל! תלמוד לומר \"ביתך\".\u0004 ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד\u0006 בזה\u0005]\u0006 כיצד למדים מכאן שהוא מן הימין? \u0003אמר רבה: דרך ביאתך\u0004 היא \u0003מן הימין, דכי עקר איניש כרעיה דימינא עקר\u0004 \u0005[שכאשר עוקר אדם את רגליו\u0006 להיכנס לבית, את רגלו \u0005הימנית עוקר]\u0006 תחילה.","\u0003רב שמואל בר אחא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא בר עולא אמר, מהכא\u0004 \u0005[מכאן]\u0006 יש ללמוד לתת את המזוזה מימין הנכנס, שנאמר: \u0003\"ויקח יהוידע הכהן ארון אחד ויקב חור בדלתו ויתן אותו אצל המזבח מימין בבוא איש בית ה' ונתנו שמה הכהנים שומרי הסף את כל הכסף המובא בית ה' \"\u0004(מלכים ב יב, י), משמע שמה שמיועד לבאים לבית נותנים בצד ימין של הנכנס.","ועוד מבררים: \u0003מאי\u0004 \u0005[מהו]\u0006 הדבר שהוזכר בשם \u0003ר' מאיר? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003בית שאין לו אלא פצים אחד\u0004 — \u0003ר' מאיר מחייב במזוזה, וחכמים פוטרין.\u0004 ומסבירים, \u0003מאי טעמא דרבנן\u0004 \u0005[מה טעמם של חכמים]?\u0006 מפני ש\u0003\"מזוזת\"\u0004 (דברים ו, ט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 בלשון רבים, עד שיהיו שתי מזוזות לבית.","\u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' מאיר\u0004 שדי במזוזה אחת? כפי \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"מזוזת\"\u0004 (דברים ו, ט) — \u0003שומע אני\u0004 מכאן \u0003מיעוט מזוזות שתים, כשהוא\u0004 חוזר ו\u0003אומר \"מזוזת\" בפרשה שניה\u0004 (\"והיה אם שמוע\". שם יא, כ), \u0003שאין תלמוד\u0004 (צורך) \u0003לומר\u0004 לכאורה, ולפיכך \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003ריבוי אחר ריבוי, ואין ריבוי אחר ריבוי אלא למעט,\u0004 ובכך \u0003מעטו הכתוב למזוזה אחת,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: אינו צריך\u0004 לראיה זו, אלא \u0003כשהוא אומר: \"על המשקוף ועל שתי המזוזת\"\u0004 (שמות יב, כב) — \u0003שאין תלמוד\u0004 (צורך) \u0003לומר \"שתי\",\u0004 שהרי נאמר מזוזות, ומיעוט רבים שנים, אלא \u0003מה תלמוד לומר \"שתי\"? זה בנה אב,\u0004 מכאן למדים בבנין אב ש\u0003כל מקום שנאמר \"מזוזות\" אינו אלא אחת, עד שיפרט לך הכתוב שתים.\u0004","ועוד בענין מזוזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"וכתבתם\u0004 על מזוזות ביתך\" (דברים ו, ט) — \u0003יכול יכתבנה\u0004 את המזוזה \u0003על האבנים\u0004 של הפתח? לכך \u0003נאמר כאן\u0004 במזוזה \u0003כתיבה, ונאמר להלן כתיבה\u0004 בספר תורה, \u0003מה להלן\u0004 נאמרה מצות כתיבה \u0003על הספר,\u0004 בקלף וכיוצא בו — \u0003אף כאן\u0004 במזוזה \u0003על הספר.\u0004","\u0003או כלך\u0004 (לך) \u0003לדרך זו: נאמר כאן\u0004 במזוזה \u0003כתיבה ונאמר להלן כתיבה\u0004 לכתוב את דברי התורה על אבנים בכניסה לארץ (שם כז, ג), \u0003מה להלן על האבנים\u0004 עצמן, \u0003אף כאן על האבנים!\u0004","ואומרים: \u0003נראה למי\u0004 לאיזה ענין הדבר \u0003דומה?\u0004 \u0003דנין\u0004 מצות \u0003כתיבה הנוהגת לדורות\u0004 במזוזה \u0003מכתיבה הנוהגת לדורות\u0004 בספר תורה, \u0003ואין דנין כתיבה\u0004 של מזוזה \u0003הנוהגת לדורות מכתיבה\u0004 על האבנים \u0003שאינה נוהגת לדורות,\u0004 אלא בשעת הכניסה לארץ. \u0003ו\u0004מנין שלדורות נוהגים על הספר — \u0003כמו שנאמר להלן:\u0004 \u0003\"ויאמר להם ברוך מפיו יקרא אלי את הדברים האלה ואני כתב על הספר בדיו\"\u0004 (ירמיהו לו, יח).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי, רחמנא אמר\u0004 \u0005[התורה אמרה]:\u0006 \u0003\"על מזוזת\"\u0004 שמשמעו בפשטות שיכתוב על המזוזות עצמן, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003\"כתיבה כתיבה\"\u0004 בגזירה שווה? מדוע אין אנו מפרשים כפשוטו! אמר לו, \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"וכתבתם\u0004 על מזוזות\" (דברים ו, ט) — תחילה \u0003כתיבה תמה,\u0004 לכתוב את הפרשיות בשלימות, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 צריך ליתן אותן \u0003על המזוזות\u0004 של הבית.","ושואלים: \u0003ומאחר דכתיב\u0004 \u0005[שנאמר]\u0006 \"וכתבתם\", ומכאן אנו למדים, \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003גזירה שוה\u0004 \"כתיבה כתיבה\" \u0003למה לי?\u0004 ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא היתה]\u0006 ה\u0003גזירה שוה, הוה אמינא ליכתבא אאבנא\u0004 \u0005[הייתי אומר שיכתוב על אבן]\u0006 \u0003וליקבעה אסיפא\u0004 \u0005[ו\u0006אחר כך \u0005יקבע אותה\u0006 את האבן \u0005בסף],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שצריך כתיבה על ספר.","שנינו במשנה: \u0003ארבע פרשיות שבתפילין מעכבות זו את זו, ואפילו כתב אחד\u0004 (אות אחת) \u0003מעכבן.\u0004 ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שאפילו אות אחת מעכבת!","\u0003אמר רב יהודה, אמר רב: לא נצרכא אלא לקוצו של יו\"ד. ו\u0004אומרים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט],\u0006 שכיון שהוא חלק מהאות בוודאי שבלעדיו האות פסולה! ומשיבים: \u0003לא נצרכא אלא לאידך\u0004 \u0005[ל\u0006הלכה \u0005האחרת]\u0006 של \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה אמר רב: כל אות שאין גויל\u0004 (קלף) \u0003מוקף לה מארבע רוחותיה,\u0004 שהיא נוגעת באות אחרת — הרי זו \u0003פסולה,\u0004 אף על פי שהאות עצמה כתובה \u0003כראוי.\u0004"],["ובענין ששנינו שיש ארבע פרשיות בתפילין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר פעמיים \u0003\"לטטפת\"\u0004 (דברים ו, ח) \u0003\"לטטפת\"\u0004 (שם יא, יח), ולפי הכתיב מדובר בכל פעם בטוטפת אחת, ושוב \u0003\"לטוטפת\"\u0004 (שמות יג, טז) בו' יתירה, שיש בה לשון רבים — \u0003הרי כאן ארבע,\u0004 מכאן למדים לארבע פרשיות שבארבעה בתים בתפילין, אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: אינו צריך\u0004 לדרשה זו, אלא המילה \"טטפת\" עצמה משמעה ארבע, כי \u0003\"טט\" ב\u0004לשון \u0003כתפי\u0004 פירושו \u0003שתים, \"פת\" ב\u0004לשון \u0003אפריקי שתים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול יכתבם\u0004 את הפרשיות של תפילין של ראש \u0003על ארבעה עורות\u0004 (קלפים) נפרדים, \u0003ויניחם בארבעה בתים בארבעה עורות,\u0004 פרשיה אחת בכל בית? \u0003תלמוד לומר: \"ולזכרון בין עיניך\"\u0004 (שם ט), ויש בכך הדגשה: \u0003זכרון אחד אמרתי לך,\u0004 כלומר, שגוף התפילין יהיה אחד, \u0003ולא שנים ושלשה זכרונות, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד? כותבן על ארבעה עורות\u0004 (קלפים) \u0003ומניחן בארבעה בתים\u0004 שעשויים \u0003בעור אחד\u0004 שמקפלים אותו.","\u0003ואם כתבן בעור\u0004 (בקלף) \u0003אחד\u0004 את כל הפרשיות \u0003והניחן בארבעה\u0004 ה\u0003בתים\u0004, כל פרשיה בבית אחר — \u0003יצא. ו\u0004במקרה זה \u0003צריך\u0004 \u0003שיהא ריוח ביניהן\u0004 (בין הפרשיות) כדי שיוכל לתת כל פרשיה בבית נפרד, \u0003דברי רבי, וחכמים אומרים: אינו צריך. ושוין,\u0004 כלומר, גם חכמים סבורים \u0003שנותן חוט או משיחה\u0004 (חוט עבה) \u0003בין כל אחת ואחת.\u0004 ומוסיפה הברייתא: \u0003ואם אין חריצן\u0004 (החריץ שבין כל בית ובית) \u0003ניכר\u0004 כלפי חוץ — \u0003פסולות.\u0004","וביחס לתפילין של יד \u0003תנו רבנן\u0004 \u0005[שנו\u0006 \u0005חכמים]:\u0006 \u0003כיצד כותבן? תפלה של יד כותבה\u0004 את ארבע הפרשיות \u0003על עור אחד\u0004 ומניחה בבית אחד, \u0003ואם כתבה בארבע עורות\u0004 נפרדים \u0003והניחה בבית אחד\u0004 — \u0003יצא. ו\u0004במקרה זה \u0003צריך לדבק\u0004 את ארבע העורות לעור אחד, \u0003שנאמר: \"והיה לך לאות על ידך\"\u0004 (שמות יג, ט), לומר: \u0003כשם שאות אחת מבחוץ,\u0004 שהבית עשוי מעור אחד — \u0003כך אות אחת מבפנים,\u0004 שארבע הפרשיות יהיו כתובות על עור אחד, אלו \u0003דברי ר' יהודה. ר' יוסי אומר: אינו צריך\u0004 לדבק.","\u0003אמר ר' יוסי: ומודה לי ר' יהודה ברבי\u0004 (הגדול) \u0003שאם אין לו תפילין של יד, ויש לו שתי תפילין של ראש,\u0004 שעשויות מארבעה בתים, \u0003שטולה\u0004 מכסה בטלאי של \u0003עור על אחת מהן\u0004 כדי לעשות אותה כבית אחד, \u0003ומניחה.\u0004 ותוהים: מה שייך לומר כאן \u0003מודה? היינו פלוגתייהו\u0004 \u0005[\u0006הרי \u0005זו היא\u0006 עצמה \u0005המחלוקת שלהם],\u0006 האם אפשר שיהיו הפרשיות של יד כתובות על עורות נפרדים, או לא! \u0003אמר רבא:\u0004 באמת, \u0003מדבריו של ר' יוסי\u0004 יש ללמוד ש\u0003חזר בו ר' יהודה\u0004 לגמרי משיטתו, והודה לר' יוסי בעיקר ההלכה.","ועל עצם האפשרות לעשות תפילה של יד מתפילה של ראש, שואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלח רב חנניה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: תפלה של יד עושין אותה\u0004 תפילה \u0003של ראש, ושל ראש אין עושין אותה\u0004 תפילה \u0003של יד, לפי שאין מורידין מקדושה חמורה לקדושה קלה!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא בעתיקתא\u0004 \u0005[זו בישנות]\u0006 שכבר נקשרו על הראש, וכבר שימשו בקדושה חמורה, \u0003הא בחדתתא\u0004 \u0005[זו בחדשות],\u0006 שלא השתמשו בהן עדיין כתפילין של ראש. \u0003ולמאן דאמר\u0004 \u0005[ולמי\u0006 \u0003שאומר]\u0004 ש\u0003הזמנה\u0004 כשלעצמה \u0003מילתא\u0004 \u0005[דבר]\u0006 \u0003היא,\u0004 ודי שיזמן אותה לשם תפילין של ראש כדי שלא יוכל עוד לשנותה, \u0003מדובר\u0004 \u0003דאתני עלייהו מעיקרא\u0004 \u0005[שהיתנה עליהם מתחילה],\u0006 שיוכל להפוך אותה משל ראש לשל יד, ובאופן זה מותר הדבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד סדרן\u0004 של הפרשיות בתוך התפילין? \u0003\"קדש לי\"\u0004 (שמות יג, א— י) \u0003\"והיה כי יביאך\"\u0004 (שם יא—טז) מונחות \u0003מימין,\u0004 פרשת \u0003\"שמע\"\u0004 (דברים ו, ד— ט) \u0003\"והיה אם שמוע\"\u0004 (שם יא, יג— כא) \u0003משמאל.\u0004","ומקשים: \u0003והתניא איפכא\u0004 \u0005[והרי שנויה\u0006 ברייתא \u0005להיפך]\u0006 \"קדש לי\" \"והיה כי יביאך\" משמאל, \"שמע\" \"והיה אם שמוע\" מימין! \u0003אמר אביי, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן מימינו של קורא\u0004 העומד מול המניח תפילין, \u0003כאן מימינו של מניח,\u0004 שהיא שמאלו של העומד מולו, \u0003והקורא קורא כסדרן,\u0004 כלומר, כסדר הכתוב בתורה, \"קדש לי\" מימינו של הקורא, ואחר כך \"והיה כי יביאך\" וכו'.","\u0003אמר רב חננאל אמר רב:\u0004 אם \u0003החליף פרשיותיה\u0004 כלומר, שינה את סדר הפרשיות בתוך בתי התפילין — הרי הן \u0003פסולות. אמר אביי: לא אמרן\u0004 \u0005[לא אמרנו]\u0006"],["\u0003אלא\u0004 כשמחליף \u0003גוייתא לברייתא\u0004 \u0005[\u0006פרשה \u0005חיצונית לפנימית],\u0006 כגון שנתן \"והיה כי יביאך\" מימין ל\"קדש\",\u0003 וברייתא לגוייתא\u0004 \u0005[ו\u0006פרשה \u0005פנימית לחיצונית],\u0006 שנתן \"והיה אם שמוע\" מימין ל\"שמע\", \u0003אבל\u0004 \u0003גוייתא לגוייתא\u0004 \u0005[פנימית לפנימית],\u0006 שהחליף \"והיה כי יביאך\" ו\"שמע\", \u0003וברייתא לברייתא\u0004 \u0005[וחיצונית לחיצונית],\u0006 \"קדש\" ו\"והיה אם שמוע\" — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מאי שנא גוייתא לברייתא וברייתא לגוייתא דלא\u0004 \u0005[במה שונה פנימית לחיצונית וחיצונית לפנימית שלא]\u0006 יחליף — \u0003דהך דבעי למיחזי אוירא לא קא חזייא\u0004 \u0005[שזו שצריכה לראות את האויר,\u0006 להיות בצד החיצוני, \u0005אינה רואה],\u0006 \u0003והא דלא קא בעי למיחזי אוירא קא חזייא\u0004 \u0005[וזו שאינה צריכה לראות אויר רואה],\u0006 והרי \u0003ברייתא לברייתא וגוייתא לגוייתא נמי\u0004 \u0005[\u0006כשמחליף \u0005חיצונית לחיצונית ופנימית לפנימית גם כן]\u0006 — \u0003הך דבעיא למיחזי אוירא\u0004 \u0005[זו שצריכה לראות אויר]\u0006 של \u0003ימין קא חזיא אוירא\u0004 \u0005[רואה אויר]\u0006 של \u0003שמאל, ו\u0004זו של \u0003שמאל קא חזיא אוירא\u0004 \u0005[רואה אויר]\u0006 של \u0003ימין! אלא לא שנא\u0004 \u0005[אינו שונה],\u0006 וכל שהופך את הסדר — פסול.","\u0003ואמר רב חננאל, אמר רב: תיתורא\u0004 \u0005[גשר,\u0006 הבסיס\u0005]\u0006 \u0003של ה\u0004\u0003תפילין,\u0004 שעליו יושבים הבתים — \u0003הלכה למשה מסיני. אמר אביי: מעברתא\u0004 \u0005[המעבורת]\u0006 של ה\u0003תפילין,\u0004 שבה משחילים את הרצועה — גם היא \u0003הלכה למשה מסיני. ואמר אביי: שי\"ן של תפילין\u0004 שמקמטים את העור בתפילין של ראש כצורת שי\"ן — \u0003הלכה למשה מסיני. ו\u0004עוד אמר:","\u0003צריך שיגיע\u0004 ה\u0003חריץ\u0004 שבין בית לבית בתפילין של ראש עד \u0003למקום התפר\u0004 כלומר, עד לתיתורא שאליה תופרים את הבתים. \u0003רב דימי מנהרדעא אמר: כיון דמנכר\u0004 \u0005[שניכר]\u0006 שיש חריץ ביניהם \u0003לא צריך\u0004 שיגיע עד לתפר.","\u0003ואמר אביי: האי קילפא\u0004 \u0005[קלף זה]\u0006 שכותבים עליו את פרשיות ה\u0003תפילין צריך למיבדקיה\u0004 \u0005[לבדוק אותו]\u0006 קודם כתיבה, \u0003דדילמא אית בה ריעותא\u0004 \u0005[שמא יש בו פגם,\u0006 נקב\u0005],\u0006 \u0003ובעינא\u0004 \u0005[וצריכים אנו]\u0006 שתהיה \u0003כתיבה תמה וליכא\u0004 \u0005[ואין כאן],\u0006 אם יהיה נקב בתוך האות. \u0003רב דימי מנהרדעא אמר: לא צריך\u0004 בדיקה מוקדמת, אלא \u0003קולמוסא בדיק לה\u0004 \u0005[הקולמוס בודק אותה]\u0006 בתוך כדי כתיבה, וכל נקב שהדיו עובר עליו אינו נחשב.","\u0003אמר ר' יצחק: רצועות שחורות\u0004 שבתפילין — \u0003הלכה למשה מסיני. מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו: \u0003תפילין אין קושרין אותן אלא במינן,\u0004 כלומר, צריך שיהיו הרצועות מעור, \u0003בין ירוקות בין שחורות\u0004 \u0003בין לבנות,\u0004 אבל רצועות \u0003אדומות לא יעשה, מפני גנאי\u0004 שיש בזה, כאילו יש פצעים בראשו, \u0003ו\u0004עוד מפני \u0003דבר אחר,\u0004 שמא יאמרו שבעל אשתו בנידתה.","\u0003אמר ר' יהודה: מעשה בתלמידו של ר' עקיבא שהיה קושר\u0004 \u0003תפיליו בלשונות של\u0004 צמר צבוע ב\u0003תכלת,\u0004 ולא בעור, \u0003ולא אמר לו דבר,\u0004 וכי \u0003איפשר אותו צדיק ראה תלמידו\u0004 שעושה דבר שלא כדין \u0003ולא מיחה בו?\u0004 משמע שהדבר מותר! \u0003אמר לו: הן\u0004 \u0005[כן],\u0006 \u0003לא ראה אותו, ואם ראה אותו לא היה מניחו.\u0004","ועוד אמר ר' יהודה: \u0003מעשה בהורקנוס בנו של ר' אליעזר בן הורקנוס שהיה קושר תפיליו בלשונות של ארגמן, ולא אמר לו דבר,\u0004 וכי \u0003איפשר אותו צדיק ראה בנו ולא מיחה בו? אמרו לו: הן\u0004 \u0005[כן],\u0006 \u0003לא ראה אותו, ואם ראה אותו\u0004 באמת \u0003לא היה מניחו.\u0004","\u0003קתני מיהא\u0004 \u0005[הריהו שונה על כל פנים]\u0006 לדעת הכל, שעושה רצועות \u0003בין ירוקות בין שחורות ובין לבנות,\u0004 שלא כפי שאמר ר' יצחק שרצועות שחורות הן הלכה למשה מסיני! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן\u0004 בברייתא, שצובע בכל גוון (חוץ מאדום), מדובר \u0003מבפנים,\u0004 בצד המונח על גופו. \u0003כאן\u0004 שהרצועות צריכות להיות שחורות — בצד ש\u0003מבחוץ.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מבפנים מאי\u0004 \u0005[מה]\u0006 \u0003גנאי ודבר אחר איכא\u0004 \u0005[יש]\u0006 בצבע אדום? הרי אין רואים צד זה של הרצועה! ומשיבים: \u0003זימנין דמתהפכין ליה\u0004 \u0005[פעמים שמתהפכות לו]\u0006 הרצועות.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003תפילין מרובעות\u0004 — \u0003הלכה למשה מסיני. אמר רב פפא:\u0004 וצריכות להיות מרובעות \u0003בתפרן ובאלכסונן,\u0004 כלומר, בתפירה של הבתים לתיתורא, שיהיה אורכה ורוחבה שווה בכל צד.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר שמסייע לו]\u0006 מה ששנינו במשנה: \u0003העושה תפילתו\u0004 (תפילין שלו) \u0003עגולה\u0004 — הרי זו \u0003סכנה\u0004 \u0003ו\u0004גם \u0003אין בה מצוה? אמר רב פפא:\u0004 אין מכאן ראיה, שכן יש לומר כי \u0003מתניתין\u0004 \u0005[המשנה]\u0006 עוסקת בתפילין \u0003דעבידא כי אמגוזא\u0004 \u0005[שעשויה כאגוז],\u0006 שהתחתית שלה מעוגלת, ולכן יש בה סכנה אם ייתקל בקיר וכדומה, וייחבל בראשו. אבל אם היתה התחתית שטוחה היינו אומרים כי היא כשירה למרות שאינה מרובעת, לכן נאמר בברייתא כי צריך שתהיה מרובעת.","\u0003אמר רב הונא: תפילין\u0004 של ראש, \u0003כל זמן שפני טבלא\u0004 (העור החיצון) \u0003קיימת,\u0004 שלא נקרע — הרי הם \u0003כשירות,\u0004 אף על פי שנקרע העור שבין בית לבית. \u0003רב חסדא אמר:\u0004 אם \u0003נפסקו\u0004 \u0003שתים\u0004 שתי דפנות של שני בתים — \u0003כשירות,\u0004 אבל אם נפסקו \u0003שלש\u0004 — \u0003פסולות.\u0004","\u0003אמר רבא: הא דאמרת\u0004 \u0005[זה שאתה אומר]\u0006 שאם נפסקו עד \u0003שתים כשירות, לא אמרן\u0004 \u0005[לא אמרנו]\u0006 \u0003אלא\u0004 שנפסקו הדפנות \u0003זה שלא כנגד זה, אבל\u0004 נפסקו \u0003זה כנגד זה\u0004 — \u0003פסולות. ו\u0004עוד, \u0003זה\u0004 \u0003כנגד זה נמי\u0004 \u0005[גם כן]\u0006 שאמרנו שהן פסולות, \u0003לא אמרן\u0004 \u0005[לא אמרנו]\u0006 \u0003אלא בחדתתא\u0004 \u0005[בחדשות],\u0006 שוודאי עור מקולקל הוא ופסול, \u0003אבל בעתיקתא לית לן\u0004 \u0005[בישנות אין לנו]\u0006 \u0003בה,\u0004 שמחמת היושן נקרעו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: היכי דמיין חדתתא, והיכי דמיין עתיקתא\u0004 \u0005[כיצד הוא בדיוק חדשות, וכיצד הוא עתיקות]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל היכא כי מיתלי ביה בשלחא והדר חלים\u0004 \u0005[כל מקום שכאשר הוא אוחז\u0006 \u0003בעור ומושך אותו, הוא חוזר למקומו]\u0004 — הרי הן \u0003עתיקתא\u0004 \u0005[ישנות],\u0006 \u0003ואידך\u0004 \u0005[והאחרות],\u0006 כאשר העור נמשך אינו חוזר למקומו \u0003—\u0004 הרי הן נקראות \u0003חדתתא\u0004 \u0005[חדשות].\u0006"],["\u0003ואי נמי\u0004 \u0005[או גם כן],\u0006 \u0003כל היכי דכי מיתלי ביה במתנא אתייה אבתריה\u0004 \u0005[כל מקום שכאשר\u0006 התפילין \u0005תלויות\u0006 \u0003ברצועה\u0004 הן \u0005הולכות אחריה\u0006 ואינן ניתקות\u0003]\u0004 — הרי אלו \u0003חדתתא\u0004 \u0005[חדשות],\u0006 \u0003ואידך עתיקתא\u0004 \u0005[והאחרות,\u0006 שניתקות, \u0005ישנות].\u0006","\u0003אביי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב יוסף, איפסיק ליה\u0004 \u0005[נפסקה לו]\u0006 ה\u0003רצועה דתפילי\u0004 \u0005[של התפילין],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו למיקטריה\u0004 \u0005[האם\u0006 מותר \u0005לקשור אותה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"וקשרתם\"\u0004 (דברים ו, ח) \u0003כתיב\u0004 \u0005[נאמר]\u0006 בתפילין, ללמד \u0003שתהא קשירה תמה\u0004 שלימה ויפה, ואין הדבר מתקיים באופן זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי: מהו למיתפריה ועייליה\u0004 \u0005[האם מותר לתפור אותה,\u0006 את הרצועה, \u0005ולהכניס]\u0006 את ה\u0003תפירה לגאו\u0004 \u0005[פנימה],\u0006 כך שהדבר אינו נראה כלפי חוץ? \u0003אמר\u0004 לו: \u0003פוק חזי מה עמא דבר\u0004 \u0005[צא וראה מה העם נוהג].\u0006","\u0003אמר רב פפא: גרדומי רצועות,\u0004 כלומר, רצועות שנקטעו בחלקן — \u0003כשירות.\u0004 ומעירים: \u0003ולאו מילתא היא\u0004 \u0005[ולא כלום הוא],\u0006 \u0003מדאמרי\u0004 \u0005[מ\u0006מה \u0005שאמרו]\u0006 \u0003בני ר' חייא: גרדומי תכלת\u0004 של ציצית, שנחתכו ונשאר מהם רק מעט, \u0003ו\u0004כן \u0003גרדומי אזוב\u0004 של הזאת מי פרה אדומה \u0003כשירין,\u0004 ולא אמרו כן על גרדומי רצועות התפילין. וטעם הדבר, \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שכשרים משום ש\u0003תשמישי מצוה נינהו\u0004 \u0005[הם],\u0006 ואין קדושתם מרובה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בתפילין ש\u0003תשמישי קדושה נינהו\u0004 \u0005[הם]\u0006 — \u0003לא.\u0004","ואומרים: על כל פנים, \u0003מכלל\u0004 הדברים אתה לומד \u0003דאית להו שיעורא\u0004 \u0005[\u0006\u0005שיש להם שיעור]\u0006 לרצועות, שהרי אנו מדברים על רצועות שלמות ועל גרדומין, \u0003ו\u0004אם כן, \u0003כמה שיעורייהו\u0004 \u0005[שיעורם]?\u0006 \u0003אמר רמי בר חמא, אמר ריש לקיש: עד אצבע צרדה,\u0004 הסמוכה לאגודל. ובהסבר דבר זה, מהיכן מודדים עד אצבע צרידה, \u0003רב כהנא מחוי\u0004 \u0005[\u0006היה \u0005מראה]\u0006 \u0003כפוף,\u0004 מראש האמה עד ראש האצבע. \u0003רב אשי מחוי\u0004 \u0005[היה מראה]\u0006 \u0003פשוט,\u0004 מראש האגודל עד ראש האצבע.","ועוד אומרים: \u0003רבה קטר להו ופשיט ושדי להו\u0004 \u0005[היה קושר אותן\u0006 את הרצועות \u0005ופושט ומשליך אותן\u0006 לאחוריו\u0003].\u0004 \u0003רב אחא בר יעקב\u0004 \u0003קטר להו ומתלית להו\u0004 \u0005[היה קושר אותן ומשלש אותן],\u0006 גודל אותן כמין צמה. \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003דרבנא עביד כדידן\u0004 \u0005[היה עושה כמונו],\u0006 שהיה נותן את הרצועות מלפניו.","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: קשר של\u0004 רצועות ה\u0003תפילין\u0004 שיהא כצורת דל\"ת בתפילין של ראש, ומעין יו\"ד בתפילין של יד — \u0003הלכה למשה מסיני. אמר רב נחמן:\u0004 \u0003ונוייהן לבר\u0004 כלומר, הנוי, הצד השחור, צריך להיות לחוץ ולא בפנים. \u0003רב אשי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003מר זוטרא, איתהפכא ליה\u0004 \u0005[התהפכה לו]\u0006 ה\u0003רצועה\u0004 של ה\u0003תפילין, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סבר לה מר ונוייהן לבר\u0004 \u0005[האם אין אדוני סבור\u0006 שצד \u0005הנוי שבהם\u0006 צריך להיות \u0005לחוץ]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אדעתאי\u0004 \u0005[לא היה זה בדעתי],\u0006 כלומר, לא שמתי לב לדבר.","נאמר: \u0003\"וראו כל עמי הארץ כי שם ה' נקרא עליך ויראו ממך\"\u0004 (דברים כח, י), ועל כך \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: אלו תפילין שבראש,\u0004 שיש בהם שם ה', והם מראים לעיני כל ששם ה' נקרא על ישראל. ועל מה שאמר הקדוש ברוך הוא למשה: \u0003\"והסרתי את כפי וראית את אחרי\"\u0004 (שמות לג, כג), \u0003אמר רב חנא בר ביזנא, אמר ר' שמעון חסידא: מלמד שהראה לו הקדוש ברוך הוא למשה קשר של תפילין.\u0004","\u0003אמר רב יהודה: קשר של תפילין צריך שיהא למעלה,\u0004 בגובה הראש ולא בצואר, \u0003כדי שיהו ישראל למעלה ולא למטה, ו\u0004כן \u0003צריך שיהא\u0004 מונח \u0003כלפי פנים,\u0004 כלומר, בעורף ולא בצדדים, \u0003כדי שיהו ישראל לפנים ולא לאחור.\u0004","\u0003אמר רב שמואל בר בידרי, אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר ר' אחא אריכא, אמר רב הונא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שמועה זו ש\u0003אמר רב מנשיא אמר שמואל: תפילין מאימתי מברך עליהן? משעת הנחתן\u0004 על היד ואילך. ומקשים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה, אמר שמואל: כל המצו‍ת כולן מברך עליהן עובר\u0004 (קודם) \u0003לעשייתן,\u0004 וכיצד מברך עליהן לאחר הנחתן! \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 ותירצו \u0005את הסתירה: מברך עליהם\u0006 \u0003משעת הנחה ועד שעת קשירה,\u0004 שקשירתן היא עשייתן."],["\u0003אמר רב חסדא:\u0004 מי ש\u0003סח,\u0004 דיבר, והפסיק על ידי כך \u0003בין\u0004 הנחת \u0003תפילה\u0004 של יד \u0003לתפילה\u0004 של ראש \u0003—\u0004 \u0003חוזר ומברך\u0004 על תפילה של ראש.","ותמהים: אם \u0003סח\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 חוזר ומברך על של ראש, \u0003לא סח\u0004 — \u0003לא?\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלח רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן\u0004 שאמר: \u0003על תפילה של יד אומר\u0004 בברכה: \u0003\"ברוך אשר קדשנו במצותיו וצונו להניח תפילין\", על תפילין של ראש אומר: \"ברוך אשר קדשנו במצותיו וצונו על מצות תפילין\",\u0004 משמע שתמיד \u0003מברך על תפילין של ראש!\u0004","\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 בתירוץ הדברים: אם \u0003לא סח\u0004 — \u0003מברך\u0004 ברכה \u0003אחת,\u0004 אם \u0003סח\u0004 — \u0003מברך שתים,\u0004 גם על תפילין של ראש.","ובענין זה מביאים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 מי ש\u0003סח בין תפילה\u0004 של יד \u0003לתפילה\u0004 של ראש \u0003עבירה היא בידו, ו\u0004המתיירא מעונשה \u0003חוזר עליה מערכי המלחמה,\u0004 כאשר נערכים למלחמה והשוטרים מכריזים: \"מי האיש הירא ורך הלבב ילך וישוב לביתו\" (דברים כ, ח), ופירשו חכמים כי הכוונה למי שמתיירא מעבירות שבידו.","ועוד \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשהוא מניח\u0004 את התפילין — \u0003מניח\u0004 תפילין \u0003של יד ואחר כך מניח של ראש, וכשהוא חולץ\u0004 אותן — \u0003חולץ של ראש\u0004 תחילה \u0003ואחר כך חולץ של יד.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרנו \u0003כשהוא מניח, מניח של יד ואחר כך מניח של ראש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה: \u0003\"וקשרתם לאות על ידך\"\u0004 (שם ו, ט) \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"והיו לטוטפת בין עיניך\"\u0004 (שם),","\u0003אלא כשהוא חולץ, חולץ של ראש ואחר כך חולץ של יד, מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר רבה: רב הונא אסברא\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 את הדבר, ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"וקשרתם לאות על ידך \u0003והיו לטוטפת בין עיניך\"\u0004 (שם), לומר: \u0003כל זמן ש\u0004התפילין \u0003בין עיניך\u0004 בראש — \u0003יהו שתים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תפילין מאימתי מברך עליהן? משעת\u0004 זמן \u0003הנחתן. כיצד? היה משכים לצאת לדרך ומתיירא שמא יאבדו\u0004 התפילין \u0003—\u0004 \u0003מניחן\u0004 אפילו בלילה, אף שאינו זמן תפילין, \u0003וכשיגיע זמנן\u0004 בבוקר, \u0003ממשמש בהן ומברך עליהן.\u0004","\u0003ועד מתי מניחן? עד שתשקע החמה, ר' יעקב אומר:\u0004 מאוחר יותר, \u0003עד שתכלה רגל מן השוק, וחכמים אומרים: עד זמן שינה. ומודים חכמים לר' יעקב\u0004 \u0003שאם חלצן\u0004 כדי \u0003לצאת לבית הכסא או\u0004 כדי \u0003ליכנס לבית המרחץ, ושקעה חמה\u0004 — \u0003שוב אינו חוזר ומניחן.\u0004","\u0003אמר רב נחמן: הלכה כר' יעקב.\u0004 וכן מסופר כי \u0003רב חסדא ורבה בר רב הונא מצלו בהו באורתא\u0004 \u0005[היו מתפללים בהן\u0006 בתפילין \u0005בערב]\u0006 בתפילת ערבית, כר' יעקב. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 שאמר רב נחמן ש\u0003אין הלכה כר' יעקב,\u0004 אלא כתנא הראשון, שזמן תפילין עד שתשקע החמה."],["ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב חסדא ורבה בר רב הונא מצלו בהו באורתא\u0004 \u0005[היו מתפללים בהן בערב]!\u0006 ומשיבים: \u0003ההוא\u0004 מעשה זה \u0003פליגא\u0004 \u0005[חלוק]\u0006 על ההלכה שאמר רב נחמן.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבה בר רב הונא הכי\u0004 \u0005[כך]\u0006 שלילה הוא זמן תפילין? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה בר רב הונא:\u0004 אם \u0003ספק חשיכה ספק לא חשיכה\u0004 — \u0003לא חולץ\u0004 תפילין, משום שעדיין אין זה לילה ודאי, אבל גם \u0003לא מניח\u0004 אותן לכתחילה. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003ודאי חשיכה\u0004 — \u0003חולץ!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003בערב שבת איתמר\u0004 \u0005[נאמר]\u0006 הדבר, מפני שאינו רשאי להניח תפילין בשבת, שאינה זמן תפילין, ולא מפני שהוא לילה.","על תירוץ זה מקשים: \u0003מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 ש\u0003לילה\u0004 הוא \u0003זמן תפילין,\u0004 אם כן \u0003שבת נמי\u0004 \u0005[גם כן]\u0006 \u0003זמן תפילין. אי קסבר\u0004 \u0005[אם הוא סבור]:\u0006 \u0003שבת לאו\u0004 \u0005[אינה]\u0006 \u0003זמן תפילין,\u0004 אם כן \u0003לילה נמי\u0004 \u0005[גם כן]\u0006 \u0003לאו\u0004 \u0005[אינו]\u0006 \u0003זמן תפילין, דמהיכא דממעטא\u0004 \u0005[ש\u0006הרי \u0005מ\u0006אותו \u0005מקום שמתמעטת]\u0006 ה\u0003שבת\u0004 מתפילין, \u0003מהתם ממעטי\u0004 \u0005[משם מתמעטים]\u0006 גם \u0003ה\u0004\u0003לילות!\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 לאחר הציווי על התפילין נאמר: \u0003\"ושמרת את החקה הזאת למועדה מימים ימימה\"\u0004 (שמות יג, י), ומכאן נדייק: \u0003\"ימים\"\u0004 — \u0003ולא לילות, \"מימים\"\u0004 — הרי זה בא למעט: \u0003ולא כל\u0004 ה\u0003ימים, פרט לשבתות וימים טובים,\u0004 אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר: לא נאמר חוקה זו אלא לפסח בלבד,\u0004 שבו עוסקת בעיקר פרשיה זו, לומר שצריך לעשותו מידי שנה בשנה, ולא לענין תפילין. ואם כן, ר' יוסי הגלילי שממעט לילה מתפילין — ממעט גם שבת!","ומשיבים: רבה בר רב הונא \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 פטור תפילין בשבת ממקור אחר, \u0003מהיכא דנפקא ליה\u0004 \u0005[ממקום שיוצאת לו]\u0006 הלכה זו \u0003לר' עקיבא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: יכול יניח אדם תפילין בשבתות ובימים טובים? תלמוד לומר: \"והיה לאות על ידך ולטוטפת בין עיניך\u0004 כי בחוזק יד הוציאנו ה' ממצרים\" (שם טז), ויש לדייק: דברים אלו אמורים דווקא ב\u0003מי\u0004 \u0003שצריכין אות,\u0004 סימן וזכר ליציאת מצרים, \u0003יצאו שבתות וימים טובים שהן גופן\u0004 (עצמם) \u0003אות\u0004 וזכר ליציאת מצרים.","ועוד בענין תפילין בלילה, \u0003אמר ר' אלעזר: כל המניח תפילין אחר שקיעת החמה עובר ב\u0004מצות \u0003עשה, ור' יוחנן אמר: עובר בלאו,\u0004 במצות לא תעשה. ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003ב\u0004דברי \u0003ר' אבין אמר ר' אילעא קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ש\u0003אמר ר' אבין אמר ר' אילעא: כל מקום שנאמר\u0004 בתורה \u0003\"השמר\"\u0004 או \u0003\"פן\"\u0004 או \u0003\"אל\"\u0004 — \u0003אינו אלא\u0004 מצות \u0003לא תעשה,\u0004","\u0003דמר אית ליה\u0004 \u0005[שחכם זה,\u0006 ר' יוחנן, \u0005יש לו,\u0006 סבור\u0005]\u0006 כ\u0003ר' אבין,\u0004 ולפיכך מה שנאמר: \"ושמרת את החוקה הזאת למועדה מימים\" ולא לילות, הוא מצות לא תעשה, \u0003ומר לית ליה\u0004 \u0005[וחכם זה,\u0006 ר' אלעזר, \u0005אין לו,\u0006 אינו סבור\u0005]\u0006 כ\u0003ר' אבין,\u0004 ו\"שמרת\" הוא מצות עשה?","ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם]\u0006 סבורים הם כדברי \u0003ר' אבין אמר ר' אילעא, והכא בהא קא מיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר, \u0005סבור]:\u0006 \u0003\"השמר\"\u0004 שכתוב בענין של \u0003לאו,\u0004 כאשר יש ציווי האוסר לעשות דבר — הרי הוא \u0003לאו, ו\"השמר\"\u0004 שנאמר לגבי מצות \u0003עשה\u0004 — נחשב מצות \u0003עשה,\u0004 ולפיכך \"ושמרת\" האמור במצות עשה של תפילין הוא מצות עשה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן, \u0005סבור]:\u0006 \u0003\"השמר\"\u0004 שכתוב במקום של \u0003עשה נמי\u0004 \u0005[גם כן]\u0006 \u0003לאו\u0004 הוא.","\u0003ואמר ר' אלעזר:\u0004 אף על פי שאסור להניח תפילין בלילה, \u0003אם\u0004 עושה כן כדי \u0003לשמרן,\u0004 שלא ייגנבו וכיוצא בזה — \u0003מותר. ואמר רבינא: הוה יתיבנא קמיה\u0004 \u0005[הייתי יושב לפני]\u0006 \u0003רב אשי וחשך\u0004 היום \u0003והניח תפילין, ואמרי ליה\u0004 \u0005[ואמרתי לו]:\u0006 האם \u0003לשמרן קא בעי להו מר\u0004 \u0005[רוצה אותן אדוני]?\u0006 \u0003ואמר לי: אין\u0004 \u0005[כן],\u0006 \u0003וחזיתיה לדעתיה\u0004 \u0005[וראיתי את דעתו]\u0006 \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003לשמרן הוא בעי\u0004 \u0005[צריך],\u0006 אלא שהוא סבור שהלכה כדעת האומרים שלילה זמן תפילין, אבל \u0003קסבר\u0004 \u0005[סבור היה]:\u0006 \u0003הלכה\u0004 היא \u0003ואין מורין כן\u0004 לאחרים, ולכן השיב לי כפי שהשיב.","\u0003אמר רבה בר רב הונא: חייב אדם למשמש בתפילין בכל שעה, קל וחומר מציץ\u0004 שבראש הכהן הגדול: \u0003ומה ציץ שאין בו אלא אזכרה אחת\u0004 של שם ה', שחקוק בו \"קדש לה' \", \u0003אמרה תורה: \"והיה על מצחו תמיד\"\u0004 (שמות כח, לח), וכוונתו — \u0003שלא תסיח דעתו ממנו, תפילין שיש בהן אזכרות הרבה\u0004 של שם ה', \u0003על אחת כמה וכמה!\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"על \u0003ידך\"\u0004 (שם יג, ט) — \u0003זו\u0004 יד \u0003שמאל. אתה אומר: שמאל, או אינו אלא ימין? תלמוד לומר: \"אף ידי יסדה ארץ וימיני טפחה שמים\"\u0004 (ישעיהו מח, יג), משמע שסתם \"יד\" — יד שמאל היא. \u0003ו\u0004כן הוא \u0003אומר\u0004 בפסוק אחר: \u0003\"ידה ליתד תשלחנה וימינה להלמות עמלים\"\u0004 (שופטים ה, כו), \u0003ואומר: \"למה תשיב ידך וימינך מקרב חיקך כלה\"\u0004 (תהלים עד, יא), שמכולם עולה ש\"יד\" היא יד שמאל."],["\u0003ר' יוסי החורם אומר:\u0004 אין מכאן ראיה, כי \u0003מצינו\u0004 גם \u0003ימין שנקרא יד, שנאמר: \"וירא יוסף כי ישית אביו יד ימינו\"\u0004 (בראשית מח, יז). \u0003ואידך\u0004 \u0005[ו\u0006התנא \u0005האחר]\u0006 מה הוא משיב לכך? \u0003\"יד ימינו\" איקרי\u0004 \u0005[נקרא],\u0006 אבל \u0003יד סתמא\u0004 \u0005[סתם]\u0006 \u0003לא איקרי\u0004 \u0005[לא נקרא].\u0006","\u0003ר' נתן אומר: אינו צריך\u0004 לראיה זו, אלא \u0003הרי הוא אומר:\u0004 \u0003\"וקשרתם\u0004 לאות על ידך...\" (דברים ו, ח) וסמוך לו: \u0003\"וכתבתם\u0004 על מזוזות ביתך\" (שם ט), ללמד: \u0003מה כתיבה בימין,\u0004 שדרך בני אדם לכתוב בימין — \u0003אף קשירה\u0004 של התפילין צריך שתיעשה \u0003בימין, וכיון\u0004 ש\u0003קשירה\u0004 נעשית \u0003בימין\u0004 — ממילא \u0003הנחה בשמאל היא,\u0004 שאינו יכול לקשור את התפילין ביד שעליה הוא מניח אותן. ושואלים: \u0003ור' יוסי החורם,\u0004 הסבור שגם ימין קרויה יד, \u0003הנחה\u0004 של תפילין \u0003ב\u0004יד \u0003שמאל מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה מהיכא דנפקא ליה\u0004 \u0005[יוצאת לו מהיכן שיוצאת לו]\u0006 \u0003לר' נתן,\u0004 מ\"וקשרתם... וכתבתם\".","\u0003רב אשי אמר:\u0004 הנחה על יד שמאל נלמדת \u0003מ\u0004מה ש\u0003\"ידכה\"\u0004 \u0003כתיב\u0004 \u0005[נאמר]\u0006 (שמות יג, טז), \u0003בה\"י,\u0004 ויש לדורשו: יד \u0003כהה,\u0004 כלומר, היד החלשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי, ואימא\u0004 \u0005[ואמור]\u0006 ודרוש \"ידכה\" כמו \"ידכח\", כלומר: \u0003ידך שבכח,\u0004 יד ימין! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \"ידכח\" \u0003בחי\"ת?\u0004 הלא בה' הוא כתוב.","ומעירים: מה שדרש רב אשי הנחה על יד שמאל מ\"ידכה\", שנוי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 ששנינו בברייתא: \u0003\"ידכה\" בה\"י\u0004 — \u0003זו שמאל, אחרים אומרים:\u0004 מה שנאמר \u0003\"ידך\"\u0004 (כלומר, \"ידכה\") בא \u0003לרבות את הגידם,\u0004 שנכרתה אמת ידו, שמכל מקום מניח תפילין. ומעירים, \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 מי ש\u0003אין לו זרוע\u0004 שמאל — \u0003פטור מן התפילין. אחרים אומרים:\u0004 מה שנאמר \u0003\"ידכה\"\u0004 — הרי זה \u0003לרבות את הגידם,\u0004 שמניח בימין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אטר מניח תפילין בימינו, שהוא שמאלו,\u0004 היד החלשה שלו. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 אטר \u0003מניח בשמאלו שהוא שמאלו של כל אדם! אמר אביי: כי תניא ההיא\u0004 \u0005[כאשר שנויה\u0006 הברייתא \u0005ההיא]\u0006 שמניח בשמאלו, הרי זה \u0003בשולט בשתי ידיו,\u0004 שכיון שמשתמש גם בימינו כשאר כל אדם — יניח כמו השאר.","ביחס למקום הנחת התפילין \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה: \"על ידך\"\u0004 (שמות יג, ט) — \u0003זו קיבורת,\u0004 הבשר התפוח, השריר שבזרוע; מה שנאמר \u0003\"בין עיניך\"\u0004 (שמות יג, ט) — \u0003זו קדקד.\u0004 ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 בדיוק הקדקוד? \u0003אמרי דבי\u0004 \u0005[אומרים בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 אותו \u0003מקום שמוחו של תינוק רופס,\u0004 רך, שאינו מכוסה בעצם.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 החכם \u0003פלימו מרבי: מי שיש לו שני ראשים באיזה מהן מניח תפילין?\u0004 כעס רבי על שאלה מוזרה זו, שנראה היה כאילו פלימו שואל רק לשם בדיחה, ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003או קום גלי\u0004 \u0005[עמוד\u0006 ו\u0005גלה]\u0006 מכאן, \u0003או קבל עלך שמתא\u0004 \u0005[עליך חרם]!\u0006 \u0003אדהכי אתא ההוא גברא\u0004 \u0005[בינתיים בא\u0006 \u0003אדם\u0004 אחד\u0003],\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרבי: \u0003איתיליד לי ינוקא דאית ליה תרי רישי\u0004 \u0005[נולד לי תינוק\u0006 בכור \u0005שיש לו שני ראשים],\u0006 \u0003כמה בעינן למיתב\u0004 \u0005[צריך אני לתת]\u0006 \u0003לכהן? אתא ההוא\u0004 \u0003סבא תנא ליה\u0004 \u0005[בא זקן אחד\u0006 ו\u0005שנה לו]:\u0006 \u0003חייב ליתן לו עשרה סלעים,\u0004 אחד לכל ראש.","ושואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 וכי ולד כזה טעון פדיון? \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רמי בר חמא, מתוך שנאמר: \"פדה תפדה את בכור האדם\"\u0004 (במדבר יח, טו), \u0003שומע אני אפילו נטרף,\u0004 כלומר, נהרג \u0003בתוך שלשים\u0004 יום גם כן צריך לפדות אותו? \u0003תלמוד לומר:\u0004"],["\u0003\"אך\u0004 פדה תפדה את בכור האדם\" (במדבר יח, טו), ובכך \u0003חלק\u0004 הכתוב, לומר שיש בכור שאינו נפדה, והוא זה שנטרף. והרי תינוק זה בעל שני ראשים כנטרף הוא, שבודאי איננו עתיד לחיות! ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בענין פדיון הבן, ש\u0003בגולגולת תלא רחמנא\u0004 \u0005[תלתה התורה],\u0006 שנאמר: \"ולקחת חמשת חמשת שקלים לגולגולת\" (שם ג, מז), ומכאן שיש מקרה בו צריך לפדות בבכור יותר מגולגולת אחת.","ושבים למה ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"ידך\"\u0004 (שמות יד, ט) — \u0003זו קיבורת\u0004 שבזרוע. ומבארים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003\"על ידך\"\u0004 (שם) — \u0003זו גובה שביד,\u0004 המקום הגבוה שביד. ויש לשאול: \u0003אתה אומר: זו גובה שביד, או אינו אלא על\u0004 \u0003ידך ממש,\u0004 כף היד? לכך יש להשיב, \u0003אמרה תורה: הנח תפילין ביד והנח תפילין בראש, מה להלן בגובה שבראש,\u0004 כאשר יבואר להלן — \u0003אף כאן בגובה שביד.\u0004","\u0003ר' אליעזר אומר: אינו צריך\u0004 לראיה זו, \u0003הרי הוא אומר: \"והיה לך לאות\u0004 על ידך\" (שם יג, ט), לומר: \u0003לך לאות ולא לאחרים לאות,\u0004 שצריך להניח את התפילין של יד במקום שאינו נראה לאחרים, והוא הזרוע המכוסה בדרך כלל, ולא על כף היד. \u0003ר' יצחק אומר: אינו צריך\u0004 לראיה זו, אלא, \u0003הרי הוא אומר: \"ושמתם את דברי אלה על לבבכם... וקשרתם\"\u0004 (דברים יא, יח), לומר \u0003שתהא שימה\u0004 של התפילין \u0003כנגד הלב,\u0004 והוא על הקיבורת שבזרוע.","מסופר, \u0003ר' חייא ורב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא\u0004 היה \u0003מכוין ומנח ליה להדי ליביה\u0004 \u0005[ומניח אותו כנגד ליבו].\u0006 מסופר, \u0003רב אשי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003אמימר, הוה ציריא בידיה וקא מתחזיין\u0004 \u0005[היה חתך ב\u0006שרוול \u0005ידו\u0006 של אמימר, \u0005ונראו]\u0006 ה\u0003תפילין,\u0004 שלא היו מכוסים בבגד, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003לא סבר לה מר\u0004 \u0005[האם אין אדוני סבור]\u0006 שנאמר \u0003\"לך לאות\" ולא לאחרים לאות? אמר ליה\u0004 \u0005[לו]:\u0006 לא נאמר שהתפילין חייבים להיות מוסתרים, אלא שצריך להניח \u0003במקום\u0004 שהוא \u0003לך לאות איתמר\u0004 \u0005[נאמר].\u0006","וביחס למה ששנינו בברייתא שתפילין של ראש הם ב\u0003גובה שבראש,\u0004 מבארים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003\"בין עיניך\"\u0004 (שמות יג, ט) — \u0003זו גובה שבראש.\u0004 ויש לשאול: \u0003אתה אומר: זו גובה שבראש, או אינו אלא בין עיניך ממש?\u0004 ועל כך יש להשיב: \u0003נאמר כאן \"בין עיניך\", ונאמר להלן \"לא תשימו קרחה בין עיניכם למת\"\u0004 (דברים יד, א), \u0003מה להלן\u0004 בקרחה, כוונתו \u0003בגובה שבראש,\u0004 \u0003מקום שעושה\u0004 בו \u0003קרחה,\u0004 שהרי אין קרחה אלא במקום שיער — \u0003אף כאן\u0004 בתפילין הרי זה \u0003בגובה של ראש,\u0004 באותו \u0003מקום שעושה קרחה.\u0004","\u0003ר' יהודה אומר: אינו צריך\u0004 לראיה זו, אלא \u0003אמרה תורה: הנח תפילין ביד\u0004 ו\u0003הנח תפילין בראש, מה להלן\u0004 בתפילין של יד, מדובר \u0003במקום הראוי ליטמא בנגע אחד\u0004 של צרעת, שהוא נגע עור בשר — \u0003אף כאן\u0004 בתפילין של ראש, מדובר \u0003במקום הראוי ליטמא בנגע אחד,\u0004 נגע של מקום שיער,","\u0003לאפוקי\u0004 \u0005[להוציא]\u0006 המקום שהוא \u0003\"בין עיניך\"\u0004 ממש, \u0003דאיכא\u0004 \u0005[שיש\u0006 שם\u0005]\u0006 \u0003בשר ושער\u0004 גבות העיניים, \u0003דאיכא\u0004 \u0005[שיש]\u0006 בו טומאה ב\u0003שער לבן\u0004 שצמח בנגע, כדין נגעי עור הבשר, \u0003ואיכא נמי\u0004 \u0005[ויש גם כן]\u0006 טומאה ב\u0003שער צהוב\u0004 הצומח בנגע, כדין נגעי הראש והזקן.","שנינו במשנה: \u0003ארבע ציציות מעכבות זו את זו, שארבעתן מצוה אחת,\u0004 ואין המצוה מתקיימת בפחות מכך. ר' ישמעאל אומר: ארבעתן ארבע מצוות נפרדות, ואינן מעכבות זו את זו. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל להלכה \u0005ביניהם]?\u0006 \u0003אמר רב יוסף:\u0004 \u0003סדין\u0004 של פשתן \u0003בציצית\u0004 (שהיא עשויה צמר) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 האם ניתן להתעטף בסדין כאשר יש בו פחות מארבע ציציות, שלדעת התנא הראשון שאין כאן מצוה — אסור הדבר משום לבישת שעטנז, ולדעת ר' ישמעאל מותר הדבר, שהרי כל ציצית מצוה לעצמה היא, ואיסור שעטנז הותר במצות ציצית.","\u0003רבא בר אהינא אמר: טלית בעלת חמש\u0004 כנפות \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 האם גם הכנף החמישית חייבת בציצית, מפני שכל אחת מצוה לעצמה, או שמא אין כאן אלא מצוה אחת של ארבע ציציות.","\u0003רבינא אמר:\u0004 מה שאמר \u0003רב הונא איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 ש\u0003אמר רב הונא: היוצא בטלית שאינה מצוייצת כהלכתה\u0004 לרשות הרבים \u0003בשבת\u0004 בשגגה — \u0003חייב חטאת\u0004 משום הציציות, שאינן נחשבות כחלק מלבושו, והריהו כנושא משוי. ונחלקו במקרה שהיו בטלית פחות מארבע ציציות, שלדעת תנא קמא אינה מצוייצת כהלכתה וחייב חטאת, ולדעת ר' ישמעאל שבכל אחת יש מצוה — אין זה נחשב משוי, ופטור.","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: האי מאן דבצריה לגלימיה\u0004 \u0005[מי שחתך את גלימתו\u0006 בפינה\u0005]\u0006 — \u0003לא עביד\u0004 \u0005[לא עשה]\u0006 \u0003ולא כלום\u0004 לפוטרה מדין ציצית, כי \u0003שוייה\u0004 \u0005[עשה אותה]\u0006 ל\u0003טלית בעלת חמש\u0004 שחייבת בציצית.","\u0003אמר רב משרשיא: האי מאן דצייריה לגלימיה\u0004 \u0005[מי שצרר,\u0006 קשר \u0005את גלימתו]\u0006 — \u0003לא עבד\u0004 \u0005[לא עשה]\u0006 \u0003ולא כלום\u0004 לפוטרה מציצית. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דכמאן דשרייה דמי\u0004 \u0005[שכמי שהתירה היא נחשבת],\u0006 שהרי אפשר להתירה כל עת. \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]:\u0006 \u0003כל חמתות הצרורות\u0004 (נודות קשורות) ששוליהן אינם תפורים אלא קשורים — \u0003טהורות\u0004 כלומר, אינן מקבלות טומאה, משום שאינן נחשבות לכלי קיבול, מפני שהקשרים עומדים להתרה, \u0003חוץ מ\u0004חמתות \u0003של ערביים\u0004 שהיו עושים את החמתות שלהם קשורות באופן קבוע.","\u0003אמר רב דימי מנהרדעא: האי מאן דחייטיה לגלימיה\u0004 \u0005[מי שתפר את גלימתו]\u0006 שקיפל את טליתו שהיתה ארוכה, ותפר את הכפל — \u0003לא עבד\u0004 \u0005[לא עשה]\u0006 \u0003ולא כלום,\u0004 שנחשב הדבר כאילו לא תפר, ויטיל את הציציות בקרנות המקוריות, כי \u0003אם איתא דלא מיבעי ליה\u0004 \u0005[אם באמת אינו צריך אותו\u0006 את החלק המקופל\u0005],\u0006 \u0003ליפסוק ולישדייה\u0004 \u0005[שיחתכנו ויזרקנו].\u0006","שנינו במשנה, \u0003ר' ישמעאל אומר: ארבעתן\u0004 ארבע הציציות \u0003ארבע מצות\u0004 נפרדות הן. \u0003אמר רב יהודה, אמר שמואל: הלכה כר' ישמעאל.\u0004 ומוסיפה הגמרא: \u0003ולית הלכתא כותיה\u0004 \u0005[ואין הלכה כמותו].\u0006","וכן מסופר, \u0003רבינא הוה קא אזיל אבתריה\u0004 \u0005[היה הולך אחרי]\u0006 \u0003מר בר רב אשי בשבתא דריגלא\u0004 \u0005[בשבת הרגל],\u0006 \u0003איפסיק קרנא דחוטיה\u0004 \u0005[נפסקה,\u0006 נחתכה, \u0005הקרן שבה\u0006 תלויות \u0005הציציות שלו,\u0006 של מר בר רב אשי\u0005]\u0006 \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 רבינא \u0003ולא מידי\u0004 \u0005[ולא כלום].\u0006 \u0003כד מטא לביתיה\u0004 \u0005[כאשר הגיע לביתו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003מהתם איפסיק\u0004 \u0005[משם,\u0006 מאמצע הדרך, \u0005נפסקה\u0006 הקרן\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר בר רב אשי: \u0003אי אמרת לי מהתם שדיתיה\u0004 \u0005[אם היית אומר לי, משם הייתי משליך אותה]\u0006 את הטלית, שכיון שנפסקה אחת הציציות שוב אינו מקיים מצוה בשאר, ואסור ללכת בטלית כזו ברשות הרבים, והוא כדעת התנא החולק על ר' ישמעאל, כמבואר לעיל.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003גדול כבוד הבריות שדוחה את לא תעשה שבתורה,\u0004 ובכלל זה איסור טלטול בשבת ברשות הרבים!","ומתרצים, הרי \u0003תרגומה\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 \u0003רב בר שבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב כהנא:\u0004"]]};
